#include <core.p4>
#include <v1model.p4>

const bit<16> TYPE_IPV4 = 0x800;
const bit<8>  TYPE_TCP  = 6;

const bit<48> ACTIVE_FLOW_THRESHOLD = 5000000; // in microseconds
const bit<48> FLOW_THRESHOLD = 120000000; // in microseconds
const bit<48> MALICIOUS_TIMEOUT = 600000000; // in microseconds

const bit<2> MALWARE_FLAG = 0b11;
const bit<2> BENIGN_FLAG = 0b10;

const bit<16> NO_FEATURE = 1024;


#define BLOOM_FILTER_ENTRIES 4096

/*************************************************************************
*********************** H E A D E R S  ***********************************
*************************************************************************/

typedef bit<9>  egressSpec_t;
typedef bit<48> macAddr_t;
typedef bit<32> ip4Addr_t;

header ethernet_t {
    macAddr_t dstAddr;
    macAddr_t srcAddr;
    bit<16>   etherType;
}

header ipv4_t {
    bit<4>    version;
    bit<4>    ihl;
    bit<8>    diffserv;
    bit<16>   totalLen;
    bit<16>   identification;
    bit<3>    flags;
    bit<13>   fragOffset;
    bit<8>    ttl;
    bit<8>    protocol;
    bit<16>   hdrChecksum;
    ip4Addr_t srcAddr;
    ip4Addr_t dstAddr;
}


header tcp_t {
    bit<16> srcPort;
    bit<16> dstPort;
    bit<32> seqNo;
    bit<32> ackNo;
    bit<4>  dataOffset;
    bit<4>  res;
    bit<1>  cwr;
    bit<1>  ece;
    bit<1>  urg;
    bit<1>  ack;
    bit<1>  psh;
    bit<1>  rst;
    bit<1>  syn;
    bit<1>  fin;
    bit<16> window;
    bit<16> checksum;
    bit<16> urgentPtr;
}

header udp_t {
    bit<16> srcPort;
    bit<16> dstPort;
    bit<16> length_;
    bit<16> checksum;
}

struct headers {
    ethernet_t ethernet;
    ipv4_t     ipv4;
	tcp_t 	   tcp;
}

struct metadata {
	// the index in registers where current flow stats are located
	bit<32> flow_pos;

	// flag counters
	bit<16> psh_flag_count;
	bit<16> syn_flag_count;
	bit<16> ack_flag_count;
	bit<32> total_packets;

	// lengths
	bit<32> total_length_of_packets;
	bit<32> total_length_of_fwd_packets;
	bit<32> init_win_byte_forward;

	// timestamps
	bit<48> active_flow_start_timestamp;
	bit<48> flow_start_timestamp;
	bit<48> last_seen;
	bit<48> last_malicous_classified; // only valid if malicious_flow == 1

	// durations
	bit<48> flow_duration;
	bit<48> active_min;
	bit<48> flow_iat_min;

	// flow identification
	bit<32> init_src_addr;
	bit<32> init_dst_addr;
	bit<1>  known_flow;
	bit<1> malicious_flow;

	// for making final decision
	bit<1> 	feature_less_than_threshold;
	bit<16> previous_feature;

	// the final decision
	bit<16> total_value;
	bit<1> stop_traversal;

	// for matching
	bit<16> node_id;
}

/*************************************************************************
*********************** P A R S E R  ***********************************
*************************************************************************/


parser MyParser(packet_in packet,
                out headers hdr,
                inout metadata meta,
                inout standard_metadata_t standard_metadata) {
	state start {
		transition parse_ethernet;
	}

	state parse_ethernet {
		packet.extract(hdr.ethernet);
		transition select (hdr.ethernet.etherType) {
			TYPE_IPV4: parse_ipv4;
			default:   accept;
		}
	}

	state parse_ipv4 {
		packet.extract(hdr.ipv4);
		transition select (hdr.ipv4.protocol) {
			TYPE_TCP: parse_tcp;
			default: accept;
		}
	}

	state parse_tcp {
		packet.extract(hdr.tcp);
		transition accept;
	}
}

