#include <core.p4>
#include <v1model.p4>


// Testbed parameters
const bit<9> SERVER_PORT=12; 
const bit<32> SERVER_IP=0x0c000003;

// 12.0.0.3

typedef bit<48> mac_addr_t;
typedef bit<32> ipv4_addr_t;
typedef bit<16> ether_type_t;
const ether_type_t ETHERTYPE_IPV4 = 16w0x0800;
const ether_type_t ETHERTYPE_SIPH_INTM = 16w0xff00;

typedef bit<8> ip_protocol_t;
const ip_protocol_t IP_PROTOCOLS_ICMP = 1;
const ip_protocol_t IP_PROTOCOLS_TCP = 6;
const ip_protocol_t IP_PROTOCOLS_UDP = 17;

const bit<16> PORT_TIMEDELTA_UPDATE = 5555;

// for time delta

const bit<4> CALLBACK_TYPE_SYNACK=1;
const bit<4> CALLBACK_TYPE_TAGACK=2; 


#define DEFAULT_SIP_KEY_0 0x33323130
#define DEFAULT_SIP_KEY_1 0x42413938

#define TIMESTAMP_NOW_TICK_16 ((bit<32>) standard_metadata.ingress_global_timestamp[47:16])

const bit<32> const_0 = 0x70736575;
const bit<32> const_1 = 0x6e646f6d;
const bit<32> const_2 = 0x6e657261;
const bit<32> const_3 = 0x79746573;

struct paired_32bit {
    bit<32> lo;
    bit<32> hi;
}

header ethernet_h {
    mac_addr_t dst_addr;
    mac_addr_t src_addr;
    bit<16> ether_type;
}

header sip_meta_h {
    bit<32> v_0;
    bit<32> v_1;
    bit<32> v_2;
    bit<32> v_3;
    bit<8> round;
    bit<4> __padding1;
    bit<4> callback_type;
    bit<7> __padding2;
    bit<9> egr_port;

    bit<32> cookie_time;
    bit<32> ack_verify_timediff;
}

header ipv4_h {
    bit<4> version;
    bit<4> ihl;
    bit<8> diffserv;
    bit<16> total_len;
    bit<16> identification;
    bit<3> flags;
    bit<13> frag_offset;
    bit<8> ttl;
    bit<8> protocol;
    bit<16> hdr_checksum;
    ipv4_addr_t src_addr;
    ipv4_addr_t dst_addr;
}

header tcp_h {
    bit<16> src_port;
    bit<16> dst_port;

    bit<32> seq_no;
    bit<32> ack_no;
    bit<4> data_offset;
    bit<4> res;

//
    bit<1> flag_cwr;
    bit<1> flag_ece; 

//
    bit<1> flag_urg;
    bit<1> flag_ack;
    bit<1> flag_psh;
    bit<1> flag_rst;
    bit<1> flag_syn;
    bit<1> flag_fin;

//
    bit<16> window;
    bit<16> checksum;
    bit<16> urgent_ptr;
}

header udp_h {
    bit<16> src_port;
    bit<16> dst_port;
    bit<16> udp_total_len;
    bit<16> checksum;
}

header udp_payload_h {
    bit<32> timestamp;
}

struct header_t {
    ethernet_h ethernet;
    sip_meta_h sip_meta;
    ipv4_h ipv4;
    tcp_h tcp;
    udp_h udp;
    udp_payload_h udp_payload;
}

struct metadata_t {

    bit<32> a_0;
    bit<32> a_1;
    bit<32> a_2;
    bit<32> a_3;


// new introduced metadata
    bit<1> sip_meta_valid;
    bit<1> tcp_valid;
    bit<1> udp_payload_valid;

    bit<32> timestamp_now_copy;
    bit<32> timestamp_minus_servertime;
    bit<32> msg_var;

    bit<1> bloom_read_1;
    bit<1> bloom_read_2;

// new introduced metadata
    bit<32> bloom_hash_1;
    bit<32> bloom_hash_2;


    bit<1> bloom_read_passed;
    bit<1> ingress_is_server_port;
    bit<1> ack_verify_timediff_exceeded_limit;

    bit<1> flag_ece;
    bit<1> flag_ack;
    bit<1> flag_syn;

    bit<16> tcp_total_len;

// always 20
    bit<1> redo_checksum;


// Egress

    bit<32> cookie_val;
    bit<32> incoming_ack_minus_1;
    bit<32> incoming_seq_plus_1;

    bit<1> tb_output_stage;


// newly introduced ot bypass egress
    bit<1> bypass_egress;

    standard_metadata_t standard_metadata;
}

parser SwitchIngressParser(
        packet_in pkt,
        out header_t hdr,
        inout metadata_t meta,
        inout standard_metadata_t standard_metadata) {


    state start {
        transition parse_ethernet;
    }

    state parse_ethernet {
        pkt.extract(hdr.ethernet);
        transition select (hdr.ethernet.ether_type) {
            ETHERTYPE_IPV4 : parse_ipv4;
            ETHERTYPE_SIPH_INTM: parse_sip_meta;

// default : reject;
            default : accept;
        }
    }

    state parse_sip_meta {
        pkt.extract(hdr.sip_meta);
        meta.sip_meta_valid = 1;
        transition parse_ipv4;
    }

    state parse_ipv4 {
        pkt.extract(hdr.ipv4);
        transition select(hdr.ipv4.protocol) {
            IP_PROTOCOLS_TCP : parse_tcp;
            IP_PROTOCOLS_UDP : parse_udp;
            default : accept;
        }
    }

    state parse_tcp {
        pkt.extract(hdr.tcp);
        meta.tcp_valid = 1;
        transition select(hdr.ipv4.total_len) {
            default : accept;
        }
    }

    state parse_udp {
        pkt.extract(hdr.udp);
        transition select(hdr.udp.dst_port) {
            PORT_TIMEDELTA_UPDATE: parse_udp_payload;
            default: accept;
        }
    }

    state parse_udp_payload {
        pkt.extract(hdr.udp_payload);
        meta.udp_payload_valid = 1;
        transition accept;
    }
}





