                        if (meta.bloom_hash > STAGE_SIZE_MINUS_ONE) {
                            meta.bloom_hash = meta.bloom_hash - BLOOM_STAGE_SIZE;
                            if (meta.bloom_hash > STAGE_SIZE_MINUS_ONE) {
