// Cookie-related
    bit<32> cookie_hash;
    bit<32> cookie_val;
    bit<32> cookie_time;
    bit<32> ack_verify_timediff;
    bit<1> ack_verify_timediff_exceeded_limit;


// Cookie control flow
    bit<4> callback_type;
    bit<1> bypass_egress;
    bit<1> skip_routing;
    bit<9> egr_port;

    standard_metadata_t standard_metadata;
}

parser SwitchIngressParser(
        packet_in pkt,
        out header_t hdr,
        inout metadata_t meta,
        inout standard_metadata_t standard_metadata) {


    state start {
        transition parse_ethernet;
    }

    state parse_ethernet {
        pkt.extract(hdr.ethernet);
        transition select (hdr.ethernet.ether_type) {
            ETHERTYPE_IPV4 : parse_ipv4;

            default : accept;
        }
    }



    state parse_ipv4 {
        pkt.extract(hdr.ipv4);
        transition select(hdr.ipv4.protocol) {
            IP_PROTOCOLS_TCP : parse_tcp;
            IP_PROTOCOLS_UDP : parse_udp;
            default : accept;
        }
    }

    state parse_tcp {
        pkt.extract(hdr.tcp);
        meta.tcp_valid = 1;
        transition select(hdr.ipv4.total_len) {
            default : accept;
        }
    }

    state parse_udp {
        pkt.extract(hdr.udp);
        transition select(hdr.udp.dst_port) {
            PORT_TIMEDELTA_UPDATE: parse_udp_payload;
            default: accept;
        }
    }

    state parse_udp_payload {
        pkt.extract(hdr.udp_payload);
        meta.udp_payload_valid = 1;
        transition accept;
    }
}



control MyVerifyChecksum(inout header_t hdr, inout metadata_t meta) {
    apply {
     verify_checksum(
	    hdr.ipv4.isValid(),
            { hdr.ipv4.version,
	      hdr.ipv4.ihl,
              hdr.ipv4.diffserv,
              hdr.ipv4.total_len,
              hdr.ipv4.identification,
              hdr.ipv4.flags,
              hdr.ipv4.frag_offset,
              hdr.ipv4.ttl,
              hdr.ipv4.protocol,
              hdr.ipv4.src_addr,
              hdr.ipv4.dst_addr},
            hdr.ipv4.hdr_checksum,
            HashAlgorithm.csum16);
     }
}




control SwitchIngress(
        inout header_t hdr,
        inout metadata_t meta,
        inout standard_metadata_t standard_metadata) {



// Implement counter that counts all packets arriving at Ingress


    action bypass_egress(){

// bypass final step "egress"
        meta.bypass_egress = 1;
    }
    action dont_bypass_egress(){

// don't bypass final step "egress"
        meta.bypass_egress = 0;
    }

    action skip_routing(){

// skip table based IPv4 forwarding
        meta.skip_routing = 1;
    }

    action drop() {

// drops the packet as quick as possible
        mark_to_drop(standard_metadata);
        bypass_egress();
        skip_routing();
    }





// time-delta

    register< bit<32> >(1) reg_timedelta;

	action timedelta_step0(){
        meta.timestamp_now_copy = (bit<32>) standard_metadata.ingress_global_timestamp[47:16];
    }


// to specify the time delta between server and proxy application
    action timedelta_step1_write(){
        meta.timestamp_minus_servertime = meta.timestamp_now_copy - hdr.udp_payload.timestamp;
    }

    action timedelta_step2_write(){
        reg_timedelta.write((bit<32>) 0, meta.timestamp_minus_servertime);

    }


// calculate the actual cookie time as it would be at the server itself
    action timedelta_step1_read(){
        reg_timedelta.read(meta.timestamp_minus_servertime, (bit<32>) 0);
    }

    action timedelta_step2_read(){
       meta.cookie_time = meta.timestamp_now_copy - meta.timestamp_minus_servertime;
       if (meta.cookie_time == 0) {

        meta.cookie_time = 0;
       }
	}

	action timedelta_step3_read(){
  		meta.cookie_time = meta.cookie_time >> 7;

        reg_timedelta.write((bit<32>) 0, meta.cookie_time);
    }



    action client_to_server_nonsyn_ongoing(){
        bypass_egress();
    }

    action server_to_client_normal_traffic(){
        bypass_egress();
    }

    action non_tcp_traffic(){
        bypass_egress();
    }


// Hash Calculation


// create cookie hash
    action start_crc_calc_synack() {
        meta.callback_type = CALLBACK_TYPE_SYNACK;

// reroute to ingress port
        meta.egr_port = standard_metadata.ingress_port; 


// Compute CRC32 hash and store in metadata
        hash(meta.cookie_hash, HashAlgorithm.crc32, (bit<32>) 0, 
            { hdr.ipv4.src_addr, hdr.ipv4.dst_addr, hdr.tcp.src_port, hdr.tcp.dst_port, hdr.tcp.seq_no }, 
            (bit<32>) 65535);

    }


// create cookie hash for later verification
    action start_crc_calc_tagack() {
        meta.callback_type = CALLBACK_TYPE_TAGACK;

// reroute to server port
        meta.egr_port = SERVER_PORT;
        bit<32> seq_no_minusone = hdr.tcp.seq_no - 1;


// Compute CRC32 hash and store in metadata
        hash(meta.cookie_hash, HashAlgorithm.crc32, (bit<32>) 0, 
            { hdr.ipv4.src_addr, hdr.ipv4.dst_addr, hdr.tcp.src_port, hdr.tcp.dst_port, seq_no_minusone }, 
            (bit<32>) 65535);
    }



    table tb_triage_pkt_types_nextstep {
        key = {
            meta.tcp_valid: exact;
            meta.udp_payload_valid: exact;
            meta.cuckoo_loop_count: ternary;

            meta.ingress_is_server_port: ternary;

            hdr.tcp.flag_syn: ternary;
            hdr.tcp.flag_ack: ternary;
            hdr.tcp.flag_ece: ternary; 
            hdr.tcp.flag_psh: ternary;



            meta.cuckoo_check_passed: ternary;
        }
        actions = {
            drop;

            start_crc_calc_synack;
            start_crc_calc_tagack;

            client_to_server_nonsyn_ongoing;
            server_to_client_normal_traffic;

            NoAction;
            non_tcp_traffic;

        }
        default_action = drop();





        size = 32;
    }


// forward packet to the appropriate port
    action ipv4_forward(mac_addr_t dst_addr, egress_spec_t port) {
        standard_metadata.egress_spec = port;
        hdr.ethernet.src_addr = hdr.ethernet.dst_addr;
        hdr.ethernet.dst_addr = dst_addr;
        hdr.ipv4.ttl = hdr.ipv4.ttl - 1;
    }


// we have one table responsible for forwarding packets
    table tb_ipv4_lpm {
        key = {
            hdr.ipv4.dst_addr: lpm;
        }
        actions = {
            ipv4_forward;
            drop;
            NoAction;
        }
        size = 1024;

// maximum number of entries in the table
        default_action = drop();
    }

    action final_xor_with_time(){
        hdr.tcp.seq_no = meta.cookie_hash ^ meta.cookie_time;
    }

	action verify_timediff(){
	    meta.ack_verify_timediff = meta.cookie_time - meta.cookie_val;

// should be 0 or 1
	}

    action final_xor_with_ackm1(){
        meta.cookie_val = meta.incoming_ack_minus_1 ^ meta.cookie_hash;
    }

    action verify_ack(){
        final_xor_with_ackm1();
        verify_timediff();
    }

    action craft_synack_reply(){
        hdr.tcp.ack_no = meta.incoming_seq_plus_1;

	   final_xor_with_time();



//swap IP
        bit<32> tmp_ip = hdr.ipv4.src_addr;
        hdr.ipv4.src_addr = hdr.ipv4.dst_addr;
        hdr.ipv4.dst_addr = tmp_ip;


//swap port
    	bit<16> tmp_port = hdr.tcp.src_port;  
        hdr.tcp.src_port=hdr.tcp.dst_port;
        hdr.tcp.dst_port=tmp_port;


//packet crafting
        hdr.tcp.data_offset=5;


        hdr.tcp.flag_ack=1;
        hdr.tcp.flag_syn=1;

        hdr.ipv4.ihl=5;
    }

    table tb_decide_output_type {
        key = {

            meta.tcp_valid: exact;

            meta.callback_type: ternary;
        }
        actions = {
            craft_synack_reply; 
            verify_ack;
            NoAction;
        }
        default_action = NoAction;
        size = 16;

    }

    action craft_onward_ack(){
        hdr.tcp.seq_no = hdr.tcp.seq_no - 1;
        hdr.tcp.data_offset = 5;

//add setup tag
        hdr.tcp.flag_ece = 1;
    }

    action finalize_tagack(){
        if (meta.ack_verify_timediff_exceeded_limit == 1) {
            mark_to_drop(standard_metadata);
        }
        craft_onward_ack();
    }

    action compute_tcp_length(){
        bit<16> tcpLength;
        bit<16> ipv4HeaderLength = ((bit<16>) hdr.ipv4.ihl) * 4;

        tcpLength = hdr.ipv4.total_len - ipv4HeaderLength;

// save this value to metadata to be used later in checksum computation
        meta.tcp_len = tcpLength;
    }


    register<cuckoo_fingerprint_t>(CUCKOO_N_FINGERPRINTS) reg_cuckoo;

    action cuckoo_bucket_insert(bit<32> bucket_index) {

// check all 4 possible bucket values and insert if any of them is empty


// bucket index -> entry index in register
        bit<32> entry_index = bucket_index << 2;


        cuckoo_fingerprint_t curr_fingerprint = 0;

        reg_cuckoo.read(curr_fingerprint, (bit<32>) entry_index);
        bit<2> insert_pos = 0;

        if (curr_fingerprint != 0) {
            reg_cuckoo.read(curr_fingerprint, (bit<32>) entry_index + 1);
            insert_pos = 1;
        }

        if (curr_fingerprint != 0) {
            reg_cuckoo.read(curr_fingerprint, (bit<32>) entry_index + 2);
            insert_pos = 2;
        }

        if (curr_fingerprint != 0) {
            reg_cuckoo.read(curr_fingerprint, (bit<32>) entry_index + 3);
            insert_pos = 3;
        }


        if (curr_fingerprint == 0) {
            meta.cuckoo_insert_success = 1;
            entry_index = entry_index + (bit<32>) insert_pos;

            reg_cuckoo.write((bit<32>) entry_index, meta.cuckoo_fingerprint);            
        }
    }

    action cuckoo_calc_index_pair() {

        hash(meta.cuckoo_index1, HashAlgorithm.crc32, (bit<32>)0, {hdr.ipv4.src_addr, hdr.ipv4.dst_addr, hdr.tcp.src_port, hdr.tcp.dst_port},
        (bit<32>) N_BUCKETS_MINUS_ONE);


        hash(meta.cuckoo_index2, HashAlgorithm.crc32, (bit<32>)0, {meta.cuckoo_fingerprint},
        (bit<32>) N_BUCKETS_MINUS_ONE);

        bit<32> temp_index;

        temp_index = meta.cuckoo_index1 ^ meta.cuckoo_index2;
        if(temp_index >= N_BUCKETS){
            temp_index = temp_index - N_BUCKETS;
        }
        meta.cuckoo_index2 = temp_index;
    }

    action cuckoo_calc_fingerprint() {
        bit<32> index_hash;
        hash(index_hash, HashAlgorithm.crc32, (bit<32>)0, 
            {hdr.ipv4.src_addr, hdr.ipv4.dst_addr, hdr.tcp.src_port, hdr.tcp.dst_port}, 
            (bit<32>)4294967295);

        meta.cuckoo_fingerprint = index_hash[31:fp_bit_index];
        meta.pseudo_random_bits = index_hash[3:0];
    }

    action cuckoo_insert_init() {
        cuckoo_calc_fingerprint();
        cuckoo_calc_index_pair();




// check if bucket at index1 is empty

        cuckoo_bucket_insert(meta.cuckoo_index1);

        if (meta.cuckoo_insert_success == 0){
            cuckoo_bucket_insert(meta.cuckoo_index2);
        }


// If unsuccessfull then start the insertion-kick loop
        if (meta.cuckoo_insert_success == 0){


// Choose a random out of the indices to save to header
            bit<1> random_bit;
            random(random_bit, 0, 1);

            if (random_bit == 1) {
                meta.cuckoo_index = meta.cuckoo_index1;
            }
            else {
                meta.cuckoo_index = meta.cuckoo_index2;
            }

// all necessary metadata is now set
            meta.cuckoo_loop_count = 1;

// this is a marker for the Cuckoo algorithm to start the kicking process

        }




    }

    action cuckoo_swap_fingerprint() {
        bit<2> random_entry;
        random(random_entry, 0, 3);

        bit<32> entry_index;
        entry_index = meta.cuckoo_index << 2;
        entry_index = entry_index + (bit<32>) random_entry;


// swap fingerprint in meta and in the random entry in the bucket
        cuckoo_fingerprint_t temp;
        reg_cuckoo.read(temp, (bit<32>) entry_index);
        reg_cuckoo.write((bit<32>) entry_index, meta.cuckoo_fingerprint);
        meta.cuckoo_fingerprint = temp;
    }

    action cuckoo_insert_kick_round() {

        cuckoo_swap_fingerprint();

        bit<32> index_hash;
        hash(index_hash, HashAlgorithm.crc32, (bit<32>)0, {meta.cuckoo_fingerprint},
        (bit<32>) N_BUCKETS_MINUS_ONE);
        index_hash = meta.cuckoo_index ^ index_hash;
        if (index_hash >= N_BUCKETS) {
            index_hash = index_hash - N_BUCKETS;

// workaround for modulo
        }
        meta.cuckoo_index = index_hash;

        cuckoo_bucket_insert(meta.cuckoo_index);

        meta.cuckoo_loop_count = meta.cuckoo_loop_count + 1;
    }



    action cuckoo_check_index(bit<32> index) {

        cuckoo_fingerprint_t curr_fingerprint;
        bit<32> entry_index = index << 2;


// Checky entry 0
        reg_cuckoo.read(curr_fingerprint, (bit<32>) entry_index);


// Checky entry 1
        if (curr_fingerprint != meta.cuckoo_fingerprint) {
            reg_cuckoo.read(curr_fingerprint, (bit<32>) entry_index + 1);
        }


// Checky entry 2
        if (curr_fingerprint != meta.cuckoo_fingerprint) {
            reg_cuckoo.read(curr_fingerprint, (bit<32>) entry_index + 2);
        }


// Checky entry 3
        if (curr_fingerprint != meta.cuckoo_fingerprint) {
            reg_cuckoo.read(curr_fingerprint, (bit<32>) entry_index + 3);
        }

        if (curr_fingerprint == meta.cuckoo_fingerprint) {
            meta.cuckoo_check_passed = 1;
        }
    }

    action cuckoo_check() {
        cuckoo_calc_fingerprint();
        cuckoo_calc_index_pair();

        cuckoo_check_index(meta.cuckoo_index1);
        if(meta.cuckoo_check_passed == 0){
            cuckoo_check_index(meta.cuckoo_index2);
        }

// check if this exact fingerprint is in one of the two buckets
    }

    action cuckoo_bucket_delete(bit<32> bucket_index) {
        bit<32> entry_index = bucket_index << 2;

        cuckoo_fingerprint_t curr_fingerprint = 0;

        reg_cuckoo.read(curr_fingerprint, (bit<32>) entry_index);

        bit<2> delete_pos = 0;

        if (curr_fingerprint != meta.cuckoo_fingerprint) {
            reg_cuckoo.read(curr_fingerprint, (bit<32>) entry_index + 1);
            delete_pos = 1;
        }

        if (curr_fingerprint != meta.cuckoo_fingerprint) {
            reg_cuckoo.read(curr_fingerprint, (bit<32>) entry_index + 2);
            delete_pos = 2;
        }

        if (curr_fingerprint != meta.cuckoo_fingerprint) {
            reg_cuckoo.read(curr_fingerprint, (bit<32>) entry_index + 3);
            delete_pos = 3;
        }


        if (curr_fingerprint == meta.cuckoo_fingerprint) {
            meta.cuckoo_delete_success = 1;
            entry_index = entry_index + (bit<32>) delete_pos;

            reg_cuckoo.write((bit<32>) entry_index, (cuckoo_fingerprint_t) 0);            
        }
    }

    action cuckoo_delete() {

// first: swap src, dst addr and port
        bit<32> temp_ip = hdr.ipv4.src_addr;
        hdr.ipv4.src_addr = hdr.ipv4.dst_addr;
        hdr.ipv4.dst_addr = temp_ip;

        bit<16> temp_port = hdr.tcp.src_port;
        hdr.tcp.src_port = hdr.tcp.dst_port;
        hdr.tcp.dst_port = temp_port;

        cuckoo_calc_fingerprint();
        cuckoo_calc_index_pair();


// Try to delete from one of both buckets

        cuckoo_bucket_delete(meta.cuckoo_index1);

        if (meta.cuckoo_delete_success == 0){
            cuckoo_bucket_delete(meta.cuckoo_index2);
        }


// swap it back
        hdr.ipv4.dst_addr = hdr.ipv4.src_addr;
        hdr.ipv4.src_addr = temp_ip;

        hdr.tcp.dst_port = hdr.tcp.src_port;
        hdr.tcp.src_port = temp_port;
    }

    action cuckoo_insert_kick_success(){

    }

    action cuckoo_insert_kick_fail(){

    }

    register< bit<32> >(1) reg_debug;
    register< bit<32> >(2) reg_debug2;

    action debug_write_loop_count(){
        reg_debug.write((bit<32>) 0, (bit<32>) meta.cuckoo_loop_count);
    }

    action debug_write_final_loop_count(){
        reg_debug2.write((bit<32>) 0, (bit<32>) meta.cuckoo_loop_count);
        reg_debug2.write((bit<32>) 1, (bit<32>) hdr.tcp.src_port);
    }


    counter(1, CounterType.packets) ingressCounter;

    apply {

// Count packets on ingress
        ingressCounter.count(0);


// Timedelta verification and setup
        timedelta_step0();
        if(hdr.udp.isValid() && standard_metadata.ingress_port == SERVER_PORT){
            timedelta_step1_write();
            timedelta_step2_write();
        }else{
            timedelta_step1_read();
            timedelta_step2_read();
            timedelta_step3_read();
        }


// Cuckoo Filter set and get




        if (hdr.tcp.isValid() && standard_metadata.ingress_port == SERVER_PORT && hdr.tcp.flag_ece == 1 && meta.cuckoo_loop_count == 0){
            if(hdr.tcp.flag_urg == 1){
                cuckoo_delete();

// set the flags back to normal so ACK packet can reach client
                hdr.tcp.flag_urg = 0;
                hdr.tcp.flag_ece = 0;
            }
            else{
                cuckoo_insert_init();

            }


        }

        if(meta.cuckoo_loop_count != 0){
            cuckoo_insert_kick_round();


            if (meta.cuckoo_loop_count == 501) {
                cuckoo_insert_kick_fail();

                drop();
            }

            debug_write_loop_count();

            if(meta.cuckoo_insert_success == 0){

                resubmit_preserving_field_list(1);

// marks the packet for resubmission
                bypass_egress();
                skip_routing();
            }
            else{
                cuckoo_insert_kick_success();

                debug_write_final_loop_count();
                drop();
            }
        }else{

// standard case
            cuckoo_check();

        }


// pre-calculate conditions and save in metadata. used in final stage triage.
        if(standard_metadata.ingress_port==SERVER_PORT){
            meta.ingress_is_server_port = 1;
        }else{
            meta.ingress_is_server_port = 0;
        }

        tb_triage_pkt_types_nextstep.apply();



// final packet processing stage: "egress"

        if(meta.bypass_egress == 0){
            meta.incoming_ack_minus_1 = hdr.tcp.ack_no - 1;
            meta.incoming_seq_plus_1 = hdr.tcp.seq_no + 1;

            tb_decide_output_type.apply(); 

            if(meta.callback_type == CALLBACK_TYPE_TAGACK){

                if(meta.ack_verify_timediff==0){

                    meta.ack_verify_timediff_exceeded_limit=0;
                }else{
                    meta.ack_verify_timediff_exceeded_limit=1;
                    mark_to_drop(standard_metadata);
                    skip_routing();
                }

                if(hdr.tcp.isValid() && !hdr.udp.isValid() && meta.callback_type == CALLBACK_TYPE_TAGACK){
                    finalize_tagack();
                }

// necessary for checksum update
                hdr.ipv4.ihl=5;
                hdr.ipv4.total_len=40;
            }

        }

        compute_tcp_length();


// Normal forwarding scenario after processing based on the scenario
        if (meta.skip_routing == 0 && hdr.ipv4.isValid()) {
            tb_ipv4_lpm.apply();
        }
    }
}


control SwitchEgress(
        inout header_t hdr,
        inout metadata_t meta,
        inout standard_metadata_t standard_metadata) {

    apply {}
}




control MyComputeChecksum(inout header_t hdr, inout metadata_t meta) {
     apply {
	update_checksum(
	    hdr.ipv4.isValid(),
            { hdr.ipv4.version,
	      hdr.ipv4.ihl,
              hdr.ipv4.diffserv,
              hdr.ipv4.total_len,
              hdr.ipv4.identification,
              hdr.ipv4.flags,
              hdr.ipv4.frag_offset,
              hdr.ipv4.ttl,
              hdr.ipv4.protocol,
              hdr.ipv4.src_addr,
              hdr.ipv4.dst_addr },
            hdr.ipv4.hdr_checksum,
            HashAlgorithm.csum16);

        update_checksum_with_payload(
	    hdr.tcp.isValid() && hdr.ipv4.isValid(),
            { hdr.ipv4.src_addr,
	      hdr.ipv4.dst_addr,
              8w0,
              hdr.ipv4.protocol,
              meta.tcp_len,
              hdr.tcp.src_port,
              hdr.tcp.dst_port,
              hdr.tcp.seq_no,
              hdr.tcp.ack_no,
              hdr.tcp.data_offset,
              hdr.tcp.res,
              hdr.tcp.flag_cwr,
              hdr.tcp.flag_ece,
              hdr.tcp.flag_urg,
              hdr.tcp.flag_ack,
              hdr.tcp.flag_psh,
              hdr.tcp.flag_rst,
              hdr.tcp.flag_syn,
              hdr.tcp.flag_fin,
              hdr.tcp.window,
              hdr.tcp.urgent_ptr
              },
            hdr.tcp.checksum,
            HashAlgorithm.csum16);

    }
}


control SwitchEgressDeparser(
        packet_out pkt,
        in header_t hdr) {

    apply {

// Emit headers
        pkt.emit(hdr.ethernet);

        pkt.emit(hdr.ipv4);
        pkt.emit(hdr.tcp);
        pkt.emit(hdr.udp);
    }
}


V1Switch(
    SwitchIngressParser(),
    MyVerifyChecksum(),
    SwitchIngress(),
    SwitchEgress(),
    MyComputeChecksum(),
    SwitchEgressDeparser()
) main;

raw_p4:
/* -*- P4_16 -*- */
#include <core.p4>
#include <v1model.p4>

const bit<16> TYPE_IPV4 = 0x800;
const bit<16> TYPE_BROADCAST = 0x1234;
const bit<8>  TCP_PROTOCOL = 0x06;
const bit<8>  UDP_PROTOCOL = 0x11;   // UDP parsing is not implemented

#define BLOOM_FILTER_ENTRIES 4096
#define BLOOM_FILTER_BIT_WIDTH 1

#define TIMER_COUNT 15
#define MSS_SERVER_ENCODING_VALUE 1
//represents MSS 1460

#define SERVER_ADDRESS 167772419


/*************************************************************************
*********************** H E A D E R S  ***********************************
*************************************************************************/

typedef bit<9>  egressSpec_t;
typedef bit<48> macAddr_t;
typedef bit<32> ip4Addr_t;

header ethernet_t {
    macAddr_t dstAddr;
    macAddr_t srcAddr;
    bit<16>   etherType;
}

header ipv4_t {
    bit<4>    version;
    bit<4>    ihl;
    bit<8>    diffserv;
    bit<16>   totalLen;
    bit<16>   identification;
    bit<3>    flags;
    bit<13>   fragOffset;
    bit<8>    ttl;
    bit<8>    protocol;
    bit<16>   hdrChecksum;
    ip4Addr_t srcAddr;
    ip4Addr_t dstAddr;
}

header tcp_t{
    bit<16> srcPort;
    bit<16> dstPort;
    bit<32> seqNo;
    bit<32> ackNo;
    bit<4>  dataOffset;
    bit<4>  res;
    bit<1>  cwr;
    bit<1>  ece;
    bit<1>  urg;
    bit<1>  ack;
    bit<1>  psh;
    bit<1>  rst;
    bit<1>  syn;
    bit<1>  fin;
    bit<16> window;
    bit<16> checksum;
    bit<16> urgentPtr;
}

struct learn_ip_t {
    bit<8> type;
    bit<32> srcIP;
    bit<32> dstIP;
    bit<32> extra_1;
    bit<32> extra_2;
}

struct learn_connection_t {
    bit<8> type;
    bit<32> connection_hash;
    bit<32> seqNo;
    bit<32> connection_hash_rev;
    bit<32> seqNo_rev;
}

struct learn_debug_t {
    bit<8> type;    // should be always set to 0 for debug messages
    bit<32> data;   // data fields are set depending on the debug parameters
    bit<32> extra_1;
    bit<32> extra_2;
    bit<32> extra_3;
}


struct metadata {
    bit<1> is_valid_cookie;
    bit<32> connectionHash;
    bit<32> connectionHash_rev;
    bit<1> is_connection_established;
    bit<32> tempDiff;
    bit<32> seqDiff;
    bit<32> seqDiff_rev;
    bit<32> cookieValue;
    bit<16> tcpLength; // this value is computed for each packet for TCP checksum recalculations
    learn_ip_t ip_digest; // Structure for sending digest messages that contain whitelisted IP addresses
    learn_connection_t seq_digest; // Structure for sending digest messages that contain connection information and seqNo
    learn_debug_t debug_digest; // Structure for sending debug digest messages with Type 0
    bit<1> debug_bool;
}

struct headers {
    ethernet_t   ethernet;
    ipv4_t       ipv4;
    tcp_t      tcp;
}

/*************************************************************************
*********************** P A R S E R  ***********************************
*************************************************************************/

parser MyParser(packet_in packet,
                out headers hdr,
                inout metadata meta,
                inout standard_metadata_t standard_metadata) {

    state start {
        transition parse_ethernet;
    }

    state parse_ethernet {
        packet.extract(hdr.ethernet);
        transition select(hdr.ethernet.etherType) {
            TYPE_IPV4: parse_ipv4;
            default: accept;
        }
    }

    state parse_ipv4 {
        packet.extract(hdr.ipv4);
        transition select(hdr.ipv4.protocol) {
            TCP_PROTOCOL: parse_tcp;
            default: accept;
        }
    }

    state parse_tcp {
        packet.extract(hdr.tcp);
        transition accept;
    }

}

/*************************************************************************
************   C H E C K S U M    V E R I F I C A T I O N   *************
*************************************************************************/

control MyVerifyChecksum(inout headers hdr, inout metadata meta) {
    apply {
     verify_checksum(
	    hdr.ipv4.isValid(),
            { hdr.ipv4.version,
	      hdr.ipv4.ihl,
              hdr.ipv4.diffserv,
              hdr.ipv4.totalLen,
              hdr.ipv4.identification,
              hdr.ipv4.flags,
              hdr.ipv4.fragOffset,
              hdr.ipv4.ttl,
              hdr.ipv4.protocol,
              hdr.ipv4.srcAddr,
              hdr.ipv4.dstAddr},
            hdr.ipv4.hdrChecksum,
            HashAlgorithm.csum16);
     }
}


/*************************************************************************
**************  I N G R E S S   P R O C E S S I N G   *******************
*************************************************************************/

control MyIngress(inout headers hdr,
                  inout metadata meta,
                  inout standard_metadata_t standard_metadata) {
    action drop() {
        mark_to_drop(standard_metadata);
    }
    // forward packet to the appropriate port
    action ipv4_forward(macAddr_t dstAddr, egressSpec_t port) {
        standard_metadata.egress_spec = port;
        hdr.ethernet.srcAddr = hdr.ethernet.dstAddr;
        hdr.ethernet.dstAddr = dstAddr;
        hdr.ipv4.ttl = hdr.ipv4.ttl - 1;
    }

    action send_digest_whitelist() {
       //send digest message to control plane, structure can be adjusted to send any data for debugging
       // digest messages for whitelist has a type 1
        meta.ip_digest.type = 1;
        meta.ip_digest.srcIP = hdr.ipv4.srcAddr;
        meta.ip_digest.dstIP = hdr.ipv4.dstAddr;
        //digest packet
        digest(1, meta.ip_digest);
    }

    // digest<learn_connection_t> ip_connection_digest;

     action send_digest_connection() {
         //send digest message to control plane, structure can be adjusted to send any data for debugging
         // digest messages for connection information has a type 2
        meta.seq_digest.type = 2;
        meta.seq_digest.connection_hash = meta.connectionHash;
        meta.seq_digest.seqNo = meta.seqDiff;
        meta.seq_digest.connection_hash_rev = meta.connectionHash_rev;
        meta.seq_digest.seqNo_rev = meta.seqDiff_rev;
        //digest packet
        // digest(ip_connection_digest, meta.seq_digest);
        digest(1, meta.seq_digest);
    }

    // action send_digest_connection() {
    //      //send digest message to control plane, structure can be adjusted to send any data for debugging
    //      // digest messages for connection information has a type 2
    //     // meta.seq_digest.type = 2;
    //     // meta.seq_digest.connection_hash = meta.connectionHash;
    //     // meta.seq_digest.seqNo = meta.seqDiff;
    //     // meta.seq_digest.connection_hash_rev = meta.connectionHash_rev;
    //     // meta.seq_digest.seqNo_rev = meta.seqDiff_rev;
    //     //digest packet
    //     // digest(ip_connection_digest, meta.seq_digest);
    //     // digest<learn_connection_t>(1, {meta.seq_digest.type, meta.seq_digest.connection_hash, meta.seq_digest.seqNo, meta.seq_digest.connection_hash_rev, meta.seq_digest.seqNo_rev});
    //     digest<learn_connection_t>(1, {2, meta.connectionHash, meta.seqDiff, meta.connectionHash_rev, meta.seqDiff_rev});

    // }

    action send_digest_debug(bit<32> extra) {
         //send digest message to control plane, structure can be adjusted to send any data for debugging
         // digest messages for connection information has a type 2
        meta.debug_digest.type = 0;
        meta.debug_digest.data = (bit<32>)meta.debug_bool;
        meta.debug_digest.extra_1 = extra;
        //digest packet
        digest(1, meta.debug_digest);
    }

    action compute_connection_hash(){

         meta.seqDiff = meta.cookieValue - hdr.tcp.seqNo;
         hash(meta.connectionHash, HashAlgorithm.crc32, (bit<32>)0, {hdr.ipv4.srcAddr,
                                                          hdr.ipv4.dstAddr,
                                                          hdr.tcp.srcPort,
                                                          hdr.tcp.dstPort,
                                                          hdr.ipv4.protocol},
                                                          (bit<32>)65535);
         meta.seqDiff_rev = hdr.tcp.seqNo - meta.cookieValue;
         hash(meta.connectionHash_rev, HashAlgorithm.crc32, (bit<32>)0, {hdr.ipv4.dstAddr,
                                                          hdr.ipv4.srcAddr,
                                                          hdr.tcp.dstPort,
                                                          hdr.tcp.srcPort,
                                                          hdr.ipv4.protocol},
                                                          (bit<32>)65535);

    }

    // create SYN-cookie packet or SYN-ACK in response to a new connection from a client that is not whitelisted
    action create_syn_cookie_packet(){
        //This action is using the SYN packet received from the client and transform it to SYN-ACK
        //SeqNo is replaced with custom cookie value computed based in several values.

        //Save all the values before exchangiung them, to be used for hash later
        bit<32> clientIPAddress = hdr.ipv4.srcAddr;
        bit<16> clientPortNum = hdr.tcp.srcPort;

        // reverse MAC address
        // commented the following out because this causes mac address issues, since it is already reversed in ipv4_forward
        // bit<48> srcMAC = hdr.ethernet.srcAddr;
        // bit<48> dstMAC = hdr.ethernet.dstAddr;
        // hdr.ethernet.dstAddr = srcMAC;
        // hdr.ethernet.srcAddr = dstMAC;

        // return the packet to the same port it came from
        // is this really necessary ? you are already doing this in the forwarding part
        //standard_metadata.egress_spec = standard_metadata.ingress_port;


        // switch source and destination IP addresses
        bit<32> clientAddr = hdr.ipv4.srcAddr;
        bit<32> serverAddr = hdr.ipv4.dstAddr;

        hdr.ipv4.srcAddr = serverAddr;
        hdr.ipv4.dstAddr = clientAddr;

        //Switch port numbers as well
        bit<16> clientPort = hdr.tcp.srcPort;
        bit<16> serverPort = hdr.tcp.dstPort;
        hdr.tcp.dstPort = clientPort;
        hdr.tcp.srcPort = serverPort;

        // set data offset to 5, to indicate that no options are included
        //hdr.tcp.dataOffset=5;  // ignore dataoffset did not solve retransmission issues
        // parsing TCP option is also complicated and removed. use random MSS encoding value

        // set SYN-ACK flags to create the second packet in the TCP handshake
        hdr.tcp.syn = 1;
        hdr.tcp.ack = 1;

        // set the Acknowledgement number to the sequence number received + size of packet (check from wireshark)
        hdr.tcp.ackNo = hdr.tcp.seqNo + 1;
        //ref" https://cr.yp.to/syncookies.html
        //generate a valid cookie, check limitations on each part
        //syn cookie is the initial sequence number selected by the proxy
        // first 5 bits: t mod 32, where t is 32 bit time counter
        // next 3 bits: encoding of MSS selected by the server in response to client's MSS
        // bottom 24 bits: hash of client IP address port and t
        // random value for all connections for now
        bit<5> time = TIMER_COUNT;   //constant value for time
        bit<3> mss_encoding = MSS_SERVER_ENCODING_VALUE; //random value for mss encvoding
        bit<24> hash_value;

        //metadata has a timestamp standard_metadata.enq_timestamp ---> bit <32>

        // compute the hash over source address and port number in addition to time counter
        //check if you need information for the server as well inside the hash or just the client!
        hash(hash_value,
	    HashAlgorithm.crc16,
	    (bit<24>)0,
	    { clientIPAddress,
              clientPortNum,
              time
            },
	     (bit<24>)2^24);

        //TODO: find an alternative way to concatenate bit strings --> P4_16 spec says ++ but it does not work!
	bit <8> temp = (bit<8>)time;
	bit <8> tempWT = temp << 3;
	bit <8> tempWTE = tempWT | (bit<8>)mss_encoding;
	bit <32> tempSeq = (bit<32>)tempWTE;
	bit <32> tempSeqS = tempSeq << 24;
        hdr.tcp.seqNo =tempSeqS | (bit<32>)hash_value;
    }

    action compute_cookie_value(){
            //ref" https://cr.yp.to/syncookies.html
        //generate a valid cookie, check limitations on each part
        //syn cookie is the initial sequence number selected by the proxy
        // first 5 bits: t mod 32, where t is 32 bit time counter
        // next 3 bits: encoding of MSS selected by the server in response to client's MSS
        // bottom 24 bits: hash of client IP address port and t
        // random value for all connections for now
        bit<5> time = TIMER_COUNT;   //constant value for time
        bit<3> mss_encoding = MSS_SERVER_ENCODING_VALUE; //random value for mss encvoding
        bit<24> hash_value;
        bit<32> clientIPAddress;
        bit<16> clientPortNum;
        if(hdr.ipv4.srcAddr == SERVER_ADDRESS){
             clientIPAddress = hdr.ipv4.dstAddr;
             clientPortNum = hdr.tcp.dstPort;
        }else{
             clientIPAddress = hdr.ipv4.srcAddr;
             clientPortNum = hdr.tcp.srcPort;
        }

        //metadata has a timestamp standard_metadata.enq_timestamp ---> bit <32>

        // compute the hash over source address and port number in addition to time counter
        //check if you need information for the server as well inside the hash or just the client!
        hash(hash_value,
	    HashAlgorithm.crc16,
	    (bit<24>)0,
	    { clientIPAddress,
              clientPortNum,
              time
            },
	     (bit<24>)2^24);

        //TODO: find an alternative way to concatenate bit strings --> P4_16 spec says ++ but it does not work!
	bit <8> temp = (bit<8>)time;
	bit <8> tempWT = temp << 3;
	bit <8> tempWTE = tempWT | (bit<8>)mss_encoding;
	bit <32> tempSeq = (bit<32>)tempWTE;
	bit <32> tempSeqS = tempSeq << 24;
        meta.cookieValue =tempSeqS | (bit<32>)hash_value;
    }

    //Validate SYN cookie received from a client, last packet in the handshake
    //if a valid cookie is received, the client information is added to whitelist (bloom filter)
    action validate_syn_cookie(){
        // check if the sequence number of SYN-ACK packet is a valid cookie for the client
        bit<5> time = TIMER_COUNT;   //constant value for time
        bit<3> mss_encoding = MSS_SERVER_ENCODING_VALUE; //random value for mss encvoding
        bit<24> hash_value;

        // compute the hash over source address and port number in addition to time counter
        hash(hash_value,
	    HashAlgorithm.crc16,
	    (bit<24>)0,
	    { hdr.ipv4.srcAddr,
              hdr.tcp.srcPort,
              time
            },
	     (bit<24>)2^24);

        // find an alternative way to concatenate bit strings --> P4_16 spec says ++ but it does not work !
	bit <8> temp = (bit<8>)time;
	bit <8> tempWT = temp << 3;
	bit <8> tempWTE = tempWT | (bit<8>)mss_encoding;
	bit <32> tempSeq = (bit<32>)tempWTE;
	bit <32> tempSeqS = tempSeq << 24;
        bit <32> seqNo=tempSeqS | (bit<32>)hash_value;


        // cookie sequence number is ack -1
        if(hdr.tcp.ackNo -1 == seqNo){
           meta.is_valid_cookie = 1;
        }else{
           meta.is_valid_cookie = 0;
        }
    }

    // for TCP checksum calculations, TCP checksum requires some IPv4 header fields in addition to TCP checksum that is
    //not present as a value and must be computed, tcp length = length in bytes of TCP header + TCP payload
    // from IPv4 header we have ipv4 total length that is a sum of the ip header and the ip payload (in our case) the TCP length
    // IPv4 length is IHL field * 4 bytes (or 32 bits 8*4), therefore, tcp length = ipv4 total length - ipv4 header length
    action compute_tcp_length(){
        bit<16> tcpLength;
        bit<16> ipv4HeaderLength = ((bit<16>) hdr.ipv4.ihl) * 4;
        //this gives the size of IPv4 header in bytes, since ihl value represents
        //the number of 32-bit words including the options field
        tcpLength = hdr.ipv4.totalLen - ipv4HeaderLength;
        // save this value to metadata to be used later in checksum computation
        meta.tcpLength = tcpLength;
    }

    action create_new_tcp_connection(){
        //this action is used to create a new tcp connection between the proxy and the server
        // minimal flags are set, this action is called based on the ACK packet received
        hdr.tcp.syn = 1;
        hdr.tcp.ack = 0;

        hdr.tcp.seqNo = hdr.tcp.seqNo - 1;
        hdr.tcp.ackNo = 0;

        hdr.tcp.dataOffset = 5;

    }

    // create ACK response for the SYN-ACK packet received from the server.
    // This action is used to establish a spoofed TCP connection between proxy and server
    action create_ack_response(){
        // reverse MAC address
        bit<48> srcMAC = hdr.ethernet.srcAddr;
        bit<48> dstMAC = hdr.ethernet.dstAddr;
        hdr.ethernet.dstAddr = srcMAC;
        hdr.ethernet.srcAddr = dstMAC;

        // switch source and destination IP addresses
        bit<32> clientAddr = hdr.ipv4.srcAddr;
        bit<32> serverAddr = hdr.ipv4.dstAddr;
        hdr.ipv4.srcAddr = serverAddr;
        hdr.ipv4.dstAddr = clientAddr;

        //Switch port numbers as well
        bit<16> clientPort = hdr.tcp.srcPort;
        bit<16> serverPort = hdr.tcp.dstPort;
        hdr.tcp.dstPort = clientPort;
        hdr.tcp.srcPort = serverPort;

        // set data offset to 5, to indicate that no options are included
       // hdr.tcp.dataOffset = 5; // not required, checksum was the cause of the re-transmission problem

        // set ACK flags to create the final packet in the TCP handshake
        hdr.tcp.syn = 0;
        hdr.tcp.ack = 1;
        hdr.tcp.psh = 0;

        // set sequence number to the acknowledgement number expected by server
        bit <32> serverSeq = hdr.tcp.seqNo;
        bit <32> serverAck = hdr.tcp.ackNo;
        hdr.tcp.seqNo = serverAck;

        // set the Acknowledgement number to the sequence number received + size of payload (check from wireshark)
        hdr.tcp.ackNo = serverSeq + 1;
    }

    action saveDifferenceValue(bit<32> difference){
        meta.tempDiff = difference;
    }

    action forward_request(){
        // sequence number should remain the same since we used the same sequence number for the second TCP connection
        // the connection table has seqNo of the previous connection stored which can be used to compute the correct ACK
        //visualization of the process
        /*
          Client                        Proxy                                  Server
                   SYN
             ---------------->
             seq = x, ack = 0
                                   k = createCookie()
                   SYN-ACK
             <----------------
             seq = k, ack = x+1

                    ACK
             ----------------->
             seq = x+1, ack = k+1
                                   bool = verifyCookie(k)
                                                                  SYN
                                   use the same initial SYN --------------->
                                                            seq = x, ack = 0

                                                                 SYN-ACK
                                  connection is established <----------------   r=selectRandomSeq()
                                                            seq = r, ack = x+1
                                  add state of the connection
                                  to connections table              ACK
                                                            ----------------->
                                                            seq = x+1, ack = r+1

                  HTTP GET                                       HTTP GET
             ----------------->         TRANSFORM           ------------------>
             seq = x+1, ack = k+1                           seq = x+1, ack = r+1

                   ACK                                             ACK
             <-----------------         TRANSFORM           <------------------
             seq = k+1, ack = x+1+ payload                   seq = r+1, ack = x+1 +payload

        */
        // this function will forward all traffic from both sides after translation if the connection is established
        // if the packet is sent by the client --> update the ACK number
        // if the packet is sent by the server --> update the sequence number
        // you should have the difference
        bit<32> sequence = hdr.tcp.seqNo;
        bit<32> acknowledgment = hdr.tcp.ackNo;
        if(hdr.ipv4.srcAddr == SERVER_ADDRESS){
            meta.debug_bool=1;
            hdr.tcp.seqNo = sequence + meta.tempDiff;
        }else{
            meta.debug_bool=0;
            hdr.tcp.ackNo = acknowledgment + meta.tempDiff;
        }
        //send_digest_debug(meta.tempDiff);
    }

    // we have one table responsible for forwarding packets
    table ipv4_lpm {
        key = {
            hdr.ipv4.dstAddr: lpm;
        }
        actions = {
            ipv4_forward;
            drop;
            NoAction;
        }
        size = 1024;   // maximum number of entries in the table
        default_action = drop();
    }
/*
    table whitelist {
        key = {
            hdr.ipv4.srcAddr: exact;
        }
        actions = {
            send_digest_whitelist;
            NoAction;
        }
        size = 4096;
        default_action = send_digest_whitelist;
    }
*/
    table connections {
        key = {
            meta.connectionHash: exact;
        }
        actions = {
            saveDifferenceValue;
            NoAction;
        }
        size = 4096;
        default_action = NoAction;
    }


    apply {
       if(hdr.ipv4.isValid() && hdr.tcp.isValid()){
               // compute the hash of the connection and check if the TCP connection is already established
               // This solution replaces multiple apply on table for processing single packet which is not allowed in P4
               //compute_cookie_value();
               compute_connection_hash();
               if(connections.apply().hit){
                 meta.is_connection_established = 1;
               }else{
                 meta.is_connection_established = 0;
               }

                //check if the connection is established to forward, otherwise discard
               if (meta.is_connection_established == 1){
                     //sequence and acknowledgment numbers should be adapted to the new connection
                     forward_request();
               }else{

                   if(hdr.tcp.syn == 1 && hdr.tcp.ack == 0){
                   //always use cookies, why do we even need a whitelist
/*
                        // if the packet is establishing a TCP connection with only SYN flag set, check white list
                           if (whitelist.apply().hit){
                               //do nothing, wait for forwarding
                           }else{
                                 //if it is a new connection, create a new syn cookie and forward
                                 create_syn_cookie_packet();
                           }
*/
                           create_syn_cookie_packet();
                   }else if(hdr.tcp.ack == 1 && hdr.tcp.syn == 0){
                         // if the packet is a ACK response for the TCP handshake
                          // check cookie value first if it is a valid cookie or not
                          validate_syn_cookie();
                          if(meta.is_valid_cookie == 1){
                           //reset the meta value
                            meta.is_valid_cookie = 0;
                             // add the client to the white list
                           // send_digest_whitelist();
                            // after receiving the final ACK from the client create a new TCP connection with the server.
                             //create a new TCP connection between Proxy-server, using same initial sequence number as client
                            create_new_tcp_connection();
                          }else{
                             // if it is not valid cookie, just drop the packet
                             drop();
                             return;
                          }
                   }else if(hdr.tcp.ack == 1 && hdr.tcp.syn == 1 && hdr.tcp.psh == 0){
                      //if you receive SYN-ACK from server to create a TCP connection
                      // change the same packet and transform it into ACK packet.
                      // add both connection and reverse to connection list
                      compute_cookie_value();
                      compute_connection_hash();
                      send_digest_connection();
                      create_ack_response();

                   }else{
                        send_digest_debug((bit<32>)000);
                        drop();
                        return;
                   }
               }
       }
        // Normal forwarding scenario after processing based on the scenario
       if (hdr.ipv4.isValid()) {
           ipv4_lpm.apply();
       }
       // TCP length is required for TCP header checksum value calculations.
       // compute TCP length after modification of TCP header
       compute_tcp_length();
    }
}
