    register <bit<32>>(4096) bloom_filter;


    action drop() {
        mark_to_drop(standard_metadata);
    }

    action update_bloom_filter(){
        //TODO 7: Define the update bloom filter action

        // Hash 1
        hash(meta.hash_1, 
        HashAlgorithm.crc16, 
        (bit<1>)0, 
        {hdr.ipv4.srcAddr,
	      hdr.ipv4.dstAddr,
          hdr.tcp.srcPort,
          hdr.tcp.dstPort,
          hdr.ipv4.protocol
        },(bit<16>)4096);

