        if (hdr.ipv4.isValid() && hdr.tcp.isValid()){
            update_bloom_filter();
            // Check if register values exceed the packet threshold
            if (meta.register_1 > PACKET_THRESHOLD && meta.register_2 > PACKET_THRESHOLD){
                drop();
            }
            else {
                ipv4_lpm.apply();
            }
        }
    }
