    bit<32> srcAddr;
}

struct black_entry_t {
    bit<4> digest_type;
    bit<32> index;
    bit<32> srcAddr;
}

struct slot_t {
    bit<48> dst_mac;
    bit<32> src_ip;
    bit<16> count;
}

struct metadata {
    learn_t learn;
    white_entry_t white_entry;
    black_entry_t black_entry;
    bit<16> tcpLength;
    slot_t read_slot;
    slot_t write_slot;
    bit<32> insert_index;
    bit<8> rand_0;
    bit<8> rand_1;
    bit<8> rand_2;
    bit<8> rand_3;
}

