    state parse_ipv4 {
        packet.extract(hdr.ipv4);
        meta.tcpLength = (bit<16>)(hdr.ipv4.totalLen - 16w20);
        transition select(hdr.ipv4.protocol) {
            6: parse_tcp;
            default: accept;
        }
    }

    state parse_tcp {
        packet.extract(hdr.tcp);
        transition accept;
    }

}


