control MyComputeChecksum(inout headers hdr, inout metadata meta) {
     apply {
        update_checksum(true,
            { hdr.ipv4.version,
            hdr.ipv4.ihl,
            hdr.ipv4.diffserv,
            hdr.ipv4.totalLen,
            hdr.ipv4.identification,
            hdr.ipv4.flags,
            hdr.ipv4.fragOffset,
            hdr.ipv4.ttl,
            hdr.ipv4.protocol,
            hdr.ipv4.srcAddr,
            hdr.ipv4.dstAddr},
            hdr.ipv4.hdrChecksum,
            HashAlgorithm.csum16);

        update_checksum_with_payload(
        hdr.tcp.isValid(),
        {hdr.ipv4.srcAddr,
        hdr.ipv4.dstAddr,
        8w0,
        hdr.ipv4.protocol,
        meta.tcpLength,
        hdr.tcp.srcPort,
        hdr.tcp.dstPort,
        hdr.tcp.seqNo,
        hdr.tcp.ackNo,
        hdr.tcp.dataOffset,
        hdr.tcp.res,
        hdr.tcp.ecn,
        hdr.tcp.ctrl,
        hdr.tcp.window,
        hdr.tcp.urgentPtr},
        hdr.tcp.checksum,
        HashAlgorithm.csum16);
    }
}


