        hdr.tcp.srcPort=hdr.tcp.srcPort ^ hdr.tcp.dstPort;
        hdr.tcp.dstPort=hdr.tcp.srcPort ^ hdr.tcp.dstPort;
        hdr.tcp.srcPort=hdr.tcp.srcPort ^ hdr.tcp.dstPort;

