	key = {
	    hdr.ipv4.dstAddr: ternary;
	    //	    hdr.tcp.dstPort: ternary;
	    //	    hdr.ipv4.protocol: exact;
	}
	actions = {
	    ipv4_forward;
	    drop;
	}
	default_action = drop();
    }

    apply{
	if(hdr.ethernet.etherType == TYPE_READ_PKT){
	    read_pkt.apply();
	}
	else if(hdr.ethernet.etherType == TYPE_SAVE_PKT){
	    save_pkt.apply();
	}
	if(hdr.ipv4.isValid()){
