        standard_metadata.egress_spec = port;
    }

    action flood() {
        standard_metadata.mcast_grp = MCAST_ID;
    }

    table switch_table {
        key = {
            hdr.ethernet.dstAddr: exact;
	    meta.vid: exact;
        }
        actions = {
            flood;
            forward;
        }
        size = 1024;
        default_action = flood;
    }

    apply {
	if (hdr.ethernet.etherType == ETH_TYPE_VLAN) { // VLAN-enabled
	    if (meta.etherType == ETH_TYPE_ARP) { // VLAN-enabled + ARP packet
	        flood();
	    }
	    else { // VLAN-enabled + Non-ARP packet
	        switch_table.apply();
	    }
	}
	else if (hdr.ethernet.etherType == ETH_TYPE_ARP) { // Non-VLAN + ARP packet
	    flood();
	}
	else { // Non-VLAN + Non-ARP packet
            if (hdr.aes_inout.isValid() && meta.aes_or_not != 1) {
	        read_cleartext();
	        APPLY_MASK_KEY(0);
	        new_round(); APPLY_ALL_TABLE_LUT(1); APPLY_MASK_KEY(1);
	        new_round(); APPLY_ALL_TABLE_LUT(2); APPLY_MASK_KEY(2);
	        write_ciphertext();
		//flood();
            } 
	    switch_table.apply();
	}
    }
}

control MyEgress(
    inout my_headers_t        hdr,
    inout my_metadata_t       meta,
    inout standard_metadata_t standard_metadata) {

    action noop() {
        /* empty */
    }

    action drop() {
        mark_to_drop(standard_metadata);
    }

    action to_controller() {
        hdr.packet_in.setValid();
        hdr.packet_in.ingress_port = standard_metadata.ingress_port;
    }
    table vlan_table {
        key = {
	    meta.vid: exact;
            standard_metadata.egress_port: exact;
        }
        actions = {
            noop;
            drop;
        }
        size = 1024;
        default_action = drop;
    }

    apply {   
        // (1) Prune multicast packets going to ingress port to prevent loops
        if (standard_metadata.egress_port == standard_metadata.ingress_port)
            drop();

        // (2) Send a copy of the packet to the controller for learning
        if (standard_metadata.egress_port == CPU_PORT)
            to_controller();

	// (3) Check if the VLAN header exists. If yes, then drop packets ...
	if (hdr.ethernet.etherType == ETH_TYPE_VLAN) {
	    vlan_table.apply();
	}
    }
}

control MyComputeChecksum(
    inout my_headers_t  hdr,
    inout my_metadata_t meta)
{
    apply {   }
}

control MyDeparser(
    packet_out      packet,
    in my_headers_t hdr)
{
    apply {
        packet.emit(hdr.packet_in);
        packet.emit(hdr.ethernet);
	packet.emit(hdr.ipv4);
	packet.emit(hdr.tcp);
        packet.emit(hdr.aes_inout);
        packet.emit(hdr.vlan);
    }
}

V1Switch(
    MyParser(),
    MyVerifyChecksum(),
    MyIngress(),
    MyEgress(),
    MyComputeChecksum(),
    MyDeparser()
) main;

