typedef bit<48> EthernetAddress;
typedef bit<32> IPv4Address;
typedef bit<128> IPv6Address;

typedef bit<16> EthernetType;
const EthernetType ETH_P_IPV4 = 16w0x0800;
const EthernetType ETH_P_ARP  = 16w0x0806;
const EthernetType ETH_P_VLAN = 16w0x8100;
const EthernetType ETH_P_IPV6 = 16w0x86dd;


typedef bit<8> IPProtocol;
const IPProtocol IPPROTO_HOPOPT = 0;

// IPv6 Hop-by-Hop Option
const IPProtocol IPPROTO_ICMP = 1;
const IPProtocol IPPROTO_IPV4 = 4;
const IPProtocol IPPROTO_TCP = 6;
const IPProtocol IPPROTO_UDP = 17;
const IPProtocol IPPROTO_IPV6 = 41;
const IPProtocol IPPROTO_ROUTE = 43;

// Routing Header for IPv6
const IPProtocol IPPROTO_FRAG = 44;

// Fragment Header for IPv6
const IPProtocol IPPROTO_GRE = 47;
const IPProtocol IPPROTO_ICMPv6 = 58;

// ICMP for IPv6
const IPProtocol IPPROTO_NONXT = 59;

// No Next Header for IPv6

typedef bit<16> UDPPort;
const UDPPort UDP_PORT_GTPC = 2123;
const UDPPort UDP_PORT_GTPU = 2152;

header Ethernet_h {
    EthernetAddress dstAddr;
    EthernetAddress srcAddr;
    EthernetType etherType;
}

header IPv4_h {
    bit<4> version;
    bit<4> ihl;
    bit<8> diffserv;
    bit<16> totalLen;
    bit<16> identification;
    bit<3> flags;
    bit<13> fragOffset;
    bit<8> ttl;
    IPProtocol protocol;
    bit<16> hdrChecksum;
    IPv4Address srcAddr;
    IPv4Address dstAddr;
}

header IPv6_h {
    bit<4> version;
    bit<8> trafficClass;
    bit<20> flowLabel;
    bit<16> payloadLen;
    bit<8> nextHdr;
    bit<8> hopLimit;
    IPv6Address srcAddr;
    IPv6Address dstAddr;
}

header TCP_h {
    bit<16> srcPort;
    bit<16> dstPort;
    bit<32> seq;
    bit<32> ack;
    bit<4> dataOffset;
    bit<4> res;
    bit<8> flags;
    bit<16> window;
    bit<16> checksum;
    bit<16> urgentPtr;
}

header UDP_h {
    bit<16> srcPort;
    bit<16> dstPort;
    bit<16> length;
    bit<16> checksum;
}

header ICMP_h {
    bit<8> type;
    bit<8> code;
    bit<16> hdrChecksum;
    bit<32> restOfHeader;

}


header SRH_h {
    bit<8> nextHdr;
    bit<8> hdrExtLen;
    bit<8> routingType;
    bit<8> segmentsLeft;
    bit<8> lastEntry;
    bit<8> flags;
    bit<12> tag;
    bit<4> gtpMessageType;

// least significant 4 bits of tag field
}

header SRH_SegmentList_h {
    bit<128> sid;
}


typedef bit<8> GTPv1Type;
const GTPv1Type GTPV1_ECHO    = 1;

// Echo Request
const GTPv1Type GTPV1_ECHORES = 2;

// Echo Response
const GTPv1Type GTPV1_ERROR = 26;

// Error Indication
const GTPv1Type GTPV1_END  = 254;

// End Marker
const GTPv1Type GTPV1_GPDU = 255;

// G-PDU


// 3GPP TS 29.060 V15.3.0 (2018-12) "6 GTP Header"
header GTPU_h {
    bit<3>  version;

// Version field: always 1 for GTPv1
    bit<1>  pt;

// Protocol Type (PT): GTP(1), GTP'(0)
    bit<1>  reserved;

// always zero (0)
    bit<1>  e;

// Extension Header flag (E)
    bit<1>  s;

// Sequence number flag (S): not present(0), present(1)
    bit<1>  pn;

// N-PDU Number flag (PN)
    GTPv1Type messageType;
    bit<16> messageLen;
    bit<32> teid;

    bit<16> seq;

// Sequence Number
    bit<8>  npdu;

// N-PDU number
    bit<8>  nextExtHdr;

// Next Extention Header Type
}



#endif /* _HEADERS_ */


#define SRH_SID_MAX 4

// Max number of SIDs in SRH Segment List
struct Header {
    Ethernet_h ether;
    IPv6_h ipv6;
    SRH_h srh;
    SRH_SegmentList_h[SRH_SID_MAX] srh_sid;

    IPv4_h ipv4;
    ICMP_h icmp;
    TCP_h tcp;
    UDP_h udp;
    GTPU_h gtpu;

// inner headers
    Ethernet_h inner_ether;
    IPv6_h inner_ipv6;
    IPv4_h inner_ipv4;

    TCP_h inner_tcp;
    UDP_h inner_udp;
}




// Generic ingress metadata (architecture independent)
struct IngressMetadata {

// none defined yet
}

// Generic egress metadata (architecture independent)
struct EgressMetadata {

}
struct SRv6Metadata {
    bit<128> nextsid;
    bit<4> gtp_message_type;

    bit<8> gtpv1_type;

}

// User Metadata (for v1model)
struct UserMetadata {
    IngressMetadata ig_md;
    EgressMetadata eg_md;
    SRv6Metadata srv6;
}




#ifndef _PARSER_
#define _PARSER_



parser SwitchParser(
            packet_in pkt,
            out Header hdr,
            inout UserMetadata user_md,
            inout standard_metadata_t st_md) {

    state start {
        transition parse_ethernet;
    }
    state parse_ethernet {
        pkt.extract(hdr.ether);
        transition select(hdr.ether.etherType) {
            ETH_P_IPV4 : parse_ipv4;
            ETH_P_IPV6 : parse_ipv6;

            default : accept;
        }
    }
    state parse_ipv4 {
        pkt.extract(hdr.ipv4);
        transition select(hdr.ipv4.protocol) {
            IPPROTO_TCP : parse_tcp;
            IPPROTO_UDP : parse_udp;
            default : accept;
        }
    }
    state parse_ipv6 {
        pkt.extract(hdr.ipv6);
        transition select(hdr.ipv6.nextHdr) {
            IPPROTO_TCP : parse_tcp;
            IPPROTO_UDP : parse_udp;
            IPPROTO_ROUTE : parse_srh;
            IPPROTO_IPV4 : parse_inner_ipv4;
            IPPROTO_IPV6 : parse_inner_ipv6;
            default : accept;
        }
    }
    state parse_tcp {
        pkt.extract(hdr.tcp);
        transition accept;
    }
    state parse_udp {
        pkt.extract(hdr.udp);
        transition select(hdr.udp.dstPort) {
            UDP_PORT_GTPU: parse_gtpu;
            default: accept;
        }
    }
    state parse_gtpu {
        pkt.extract(hdr.gtpu);
        user_md.srv6.gtpv1_type = hdr.gtpu.messageType;
        bit<4> ip_ver = pkt.lookahead<bit<4>>();
        transition select(ip_ver) {
            4w4 : parse_inner_ipv4;
            4w6 : parse_inner_ipv6;
            default : parse_inner_ether;
        }
    }
    state parse_inner_ipv4 {
        pkt.extract(hdr.inner_ipv4);
        transition select(hdr.inner_ipv4.protocol) {
            IPPROTO_TCP : parse_inner_tcp;
            IPPROTO_UDP : parse_inner_udp;
            default : accept;
        }
    }
    state parse_inner_ipv6 {
        pkt.extract(hdr.inner_ipv6);
        transition select(hdr.inner_ipv6.nextHdr) {
            IPPROTO_TCP : parse_inner_tcp;
            IPPROTO_UDP : parse_inner_udp;
            default : accept;
        }
    }
    state parse_inner_ether {
        pkt.extract(hdr.inner_ether);
        transition accept;
    }

/*** PARSE SRH (SRv6) ***/
    state parse_srh {
        pkt.extract(hdr.srh);
        user_md.srv6.gtp_message_type = hdr.srh.gtpMessageType;
        transition parse_srh_sid_0;
    }
#define PARSE_SRH_SID(curr, next)               \
    state parse_srh_sid_##curr {                \
        pkt.extract(hdr.srh_sid[curr]);         \
        transition select(hdr.srh.lastEntry) {  \
            curr : parse_srh_next_header;       \
            default : parse_srh_sid_##next;     \
        }                                       \
    }                                           \

PARSE_SRH_SID(0, 1)
PARSE_SRH_SID(1, 2)
PARSE_SRH_SID(2, 3)
    state parse_srh_sid_3 {
        pkt.extract(hdr.srh_sid[3]);
        transition select(hdr.srh.lastEntry) {
            3 : parse_srh_next_header;

// v1model: no default rule: all other packets rejected
#ifndef _V1_MODEL_P4_
            default : reject;

// Too many SIDs
#endif /* _V1_MODEL_P4_ */
        }
    }
    state parse_srh_next_header {
        transition select(hdr.srh.nextHdr) {
            IPPROTO_TCP : parse_tcp;
            IPPROTO_UDP : parse_udp;
            IPPROTO_IPV4 : parse_inner_ipv4;
            IPPROTO_IPV6 : parse_inner_ipv6;
            default : accept;
        }
    }
    state parse_inner_udp {
        pkt.extract(hdr.inner_udp);
        transition accept;
    }
    state parse_inner_tcp {
        pkt.extract(hdr.inner_tcp);
        transition accept;
    }
}




control SwitchDeparser(
            packet_out pkt,
            in Header hdr) {

    apply {
        pkt.emit(hdr.ether);
        pkt.emit(hdr.ipv6);
        pkt.emit(hdr.srh);
        pkt.emit(hdr.srh_sid);
        pkt.emit(hdr.ipv4);

        pkt.emit(hdr.tcp);
        pkt.emit(hdr.udp);
        pkt.emit(hdr.gtpu);
        pkt.emit(hdr.inner_ether);
        pkt.emit(hdr.inner_ipv6);
        pkt.emit(hdr.inner_ipv4);
        pkt.emit(hdr.inner_tcp);
        pkt.emit(hdr.inner_udp);
    }
}
#endif /* _PARSER_ */



#ifndef _SRV6_
#define _SRV6_

control SRv6(
    inout Header hdr,
    inout UserMetadata user_md,
    in PortId_t in_port,
    inout PortId_t egress_port) {


// Counters for actions in transit and end (localsid) behaviors.
#ifdef _V1_MODEL_P4_

// see v1model.p4 for counter definitions.
    direct_counter(CounterType.packets_and_bytes) cnt_srv6_t_v4;
    direct_counter(CounterType.packets_and_bytes) cnt_srv6_t_v6;
    direct_counter(CounterType.packets_and_bytes) cnt_srv6_t_udp;
    direct_counter(CounterType.packets_and_bytes) cnt_srv6_e;
    direct_counter(CounterType.packets_and_bytes) cnt_srv6_e_iif;
#endif /* _V1_MODEL_P4_ */


/*** HELPER ACTIONS */
    action remove_srh_header() {
        hdr.srh.setInvalid();

        hdr.srh_sid[0].setInvalid();
        hdr.srh_sid[1].setInvalid();
        hdr.srh_sid[2].setInvalid();
        hdr.srh_sid[3].setInvalid();
        hdr.srh.setInvalid();
    }


/*** HELPER ACTIONS : PUSH SRH/SID */
    action push_srh(bit<8> nextHdr, bit<8> hdrExtLen, bit<8> segmentsLeft, bit<8> lastEntry) {
        hdr.srh.setValid();
        hdr.srh.nextHdr = nextHdr;
        hdr.srh.hdrExtLen = hdrExtLen;
        hdr.srh.routingType = 4;

// TBD, to be assigned by IANA (suggested value: 4)
        hdr.srh.segmentsLeft = segmentsLeft;
        hdr.srh.lastEntry = lastEntry;
        hdr.srh.flags = 0;
        hdr.srh.tag = 0;
    }
    action push_srh_sid1(
            bit<8> nextHdr,
            bit<8> segmentsLeft,
            bit<128> sid1) {

// SID List <sid1>
        hdr.ipv6.payloadLen = hdr.ipv6.payloadLen + 16w24;

// SRH(8) + SID(16)
        push_srh(nextHdr, 8w2, segmentsLeft, 8w0);
        hdr.srh_sid[0].setValid();
        hdr.srh_sid[0].sid = sid1;
    }
    action push_srh_sid2(
            bit<8> nextHdr,
            bit<8> segmentsLeft,
            bit<128> sid1, bit<128> sid2) {

// SID List <sid1, sid2>
        hdr.ipv6.payloadLen = hdr.ipv6.payloadLen + 16w40;

// SRH(8) + SID(16)*2
        push_srh(nextHdr, 8w4, segmentsLeft, 8w1);
        hdr.srh_sid[0].setValid();
        hdr.srh_sid[0].sid = sid2;
        hdr.srh_sid[1].setValid();
        hdr.srh_sid[1].sid = sid1;
    }
    action push_srh_sid3(
            bit<8> nextHdr,
            bit<8> segmentsLeft,
            bit<128> sid1, bit<128> sid2, bit<128> sid3) {

// SID List <sid1, sid2, sid3>
        hdr.ipv6.payloadLen = hdr.ipv6.payloadLen + 16w56;

// SRH(8) + SID(16)*3
        push_srh(nextHdr, 8w6, segmentsLeft, 8w2);
        hdr.srh_sid[0].setValid();
        hdr.srh_sid[0].sid = sid3;
        hdr.srh_sid[1].setValid();
        hdr.srh_sid[1].sid = sid2;
        hdr.srh_sid[2].setValid();
        hdr.srh_sid[2].sid = sid1;
    }
    action push_srh_sid4(
            bit<8> nextHdr,
            bit<8> segmentsLeft,
            bit<128> sid1, bit<128> sid2, bit<128> sid3, bit<128> sid4) {

// SID List <sid1, sid2, sid3, sid4>
        hdr.ipv6.payloadLen = hdr.ipv6.payloadLen + 16w72;

// SRH(8) + SID(16)*4
        push_srh(nextHdr, 8w8, segmentsLeft, 8w3);
        hdr.srh_sid[0].setValid();
        hdr.srh_sid[0].sid = sid4;
        hdr.srh_sid[1].setValid();
        hdr.srh_sid[1].sid = sid3;
        hdr.srh_sid[2].setValid();
        hdr.srh_sid[2].sid = sid2;
        hdr.srh_sid[3].setValid();
        hdr.srh_sid[3].sid = sid1;
    }


/*** TRANSIT ACTION & TABLES */


// T.Insert will use ipv6.dstAddr as 1st SID. Thus, will have +1 SIDs.
    action t_insert_sid1(bit<128> sid1) {
        push_srh_sid2(hdr.ipv6.nextHdr, 1, sid1, hdr.ipv6.dstAddr);
        hdr.ipv6.nextHdr = IPPROTO_ROUTE;
        hdr.ipv6.dstAddr = sid1;
        cnt_srv6_t_v6.count();
    }
    action t_insert_sid2(bit<128> sid1, bit<128> sid2) {
        push_srh_sid3(hdr.ipv6.nextHdr, 2, sid1, sid2, hdr.ipv6.dstAddr);
        hdr.ipv6.nextHdr = IPPROTO_ROUTE;
        hdr.ipv6.dstAddr = sid1;
        cnt_srv6_t_v6.count();
    }
    action t_insert_sid3(bit<128> sid1, bit<128> sid2, bit<128> sid3) {
        push_srh_sid4(hdr.ipv6.nextHdr, 3, sid1, sid2, sid3, hdr.ipv6.dstAddr);
        hdr.ipv6.nextHdr = IPPROTO_ROUTE;
        hdr.ipv6.dstAddr = sid1;
        cnt_srv6_t_v6.count();
    }


    action t_m_gtp4_d_synthesize(bit<32> iw_prefix, bit<64> src_prefix) {

        hdr.ether.etherType = ETH_P_IPV6;
        hdr.ipv6.setValid();
        hdr.ipv6.version = 4w6;
        hdr.ipv6.trafficClass = 8w0;
        hdr.ipv6.flowLabel = 20w0;
        hdr.ipv6.payloadLen = hdr.ipv4.totalLen - 16w40;
        hdr.ipv6.nextHdr = 8w4;

        hdr.ipv6.hopLimit = hdr.ipv4.ttl;

// Synthesize IPv6 SA from GTP packet
        hdr.ipv6.srcAddr[127:64] = src_prefix;

// Local SRGW Src Prefix (64)
        hdr.ipv6.srcAddr[63:32] = hdr.ipv4.srcAddr;

// IPv4 SA (32)
        hdr.ipv6.srcAddr[31:0] = 32w0;

        hdr.ipv6.dstAddr[127:96] = iw_prefix;

// GTP SRv6 InterWork prefix
        hdr.ipv6.dstAddr[95:64] = hdr.ipv4.dstAddr;

        hdr.ipv6.dstAddr[63:56] = 8w0;

// GTP QFI/RQI (0 for now)
        hdr.ipv6.dstAddr[55:24] = hdr.gtpu.teid;
        hdr.ipv6.dstAddr[23:0] = 24w0;

        hdr.gtpu.setInvalid();
        hdr.udp.setInvalid();
        hdr.ipv4.setInvalid();
    }

    action t_m_gtp4_d(bit<32> iw_prefix, bit<64> src_prefix) {
        t_m_gtp4_d_synthesize(iw_prefix, src_prefix);
        cnt_srv6_t_udp.count();
    }

    action t_m_gtp4_d_sid1(bit<32> iw_prefix, bit<64> src_prefix,
            bit<128> sid1) {
        t_m_gtp4_d_synthesize(iw_prefix, src_prefix);
        push_srh_sid2(hdr.ipv6.nextHdr, 1, sid1, hdr.ipv6.dstAddr);
        hdr.ipv6.nextHdr = IPPROTO_ROUTE;
        hdr.ipv6.dstAddr = sid1;
        cnt_srv6_t_udp.count();
    }
    action t_m_gtp4_d_sid2(bit<32> iw_prefix, bit<64> src_prefix,
            bit<128> sid1, bit<128> sid2) {
        t_m_gtp4_d_synthesize(iw_prefix, src_prefix);
        push_srh_sid3(hdr.ipv6.nextHdr, 2, sid1, sid2, hdr.ipv6.dstAddr);
        hdr.ipv6.nextHdr = IPPROTO_ROUTE;
        hdr.ipv6.dstAddr = sid1;
        cnt_srv6_t_udp.count();
    }
    action t_m_gtp4_d_sid3(bit<32> iw_prefix, bit<64> src_prefix,
            bit<128> sid1, bit<128> sid2, bit<128> sid3) {
        t_m_gtp4_d_synthesize(iw_prefix, src_prefix);
        push_srh_sid4(hdr.ipv6.nextHdr, 3, sid1, sid2, sid3, hdr.ipv6.dstAddr);
        hdr.ipv6.nextHdr = IPPROTO_ROUTE;
        hdr.ipv6.dstAddr = sid1;
        cnt_srv6_t_udp.count();
    }
    action srv6_debug_v6() {

        cnt_srv6_t_v6.count();
    }
    table srv6_transit_v6 {
        key = {
            hdr.ipv6.dstAddr: exact;

        }
        actions = {
            @defaultonly NoAction;
            t_insert_sid1;

// T.Insert with 2 SIDs (DA + sid1)
            t_insert_sid2;

// T.Insert with 3 SIDs (DA + sid1/2)
            t_insert_sid3;

        }
        const default_action = NoAction;
        counters = cnt_srv6_t_v6;
    }
    table srv6_transit_v4 {
        key = {
            hdr.ipv4.dstAddr: exact;

        }
        actions = {
            @defaultonly NoAction;

        }
        const default_action = NoAction;
        counters = cnt_srv6_t_v4;
    }
    table srv6_transit_udp {
        key = {
            hdr.udp.dstPort : exact;
        }
        actions = {
            @defaultonly NoAction;

// SRv6 Mobile Userplane : draft-ietf-dmm-srv6-mobile-uplane
            t_m_gtp4_d;
            t_m_gtp4_d_sid1;

// 2 SIDs (DA + sid1)
            t_m_gtp4_d_sid2;

// 3 SIDs (DA + sid1/2)
            t_m_gtp4_d_sid3;

// 4 SIDs (DA + sid1/2/3)
        }
        const default_action = NoAction;
        counters = cnt_srv6_t_udp;
    }

    action end() {

        hdr.srh.segmentsLeft = hdr.srh.segmentsLeft - 1;

        hdr.ipv6.dstAddr = user_md.srv6.nextsid;

    }
    action end_m_gtp4_e() {
        hdr.ether.etherType = ETH_P_IPV4;
        hdr.ipv4.setValid();
        hdr.ipv4.version = 4w4;
        hdr.ipv4.ihl = 4w5;
        hdr.ipv4.diffserv = 8w0;

        hdr.ipv4.totalLen = hdr.ipv6.payloadLen - 16w8 - (bit<16>)hdr.srh.hdrExtLen*8 + 16w40;

        hdr.ipv4.identification = 16w0;
        hdr.ipv4.flags = 3w0;
        hdr.ipv4.fragOffset = 13w0;
        hdr.ipv4.ttl = hdr.ipv6.hopLimit;
        hdr.ipv4.protocol = IPPROTO_UDP;

// IPv4 header checksum will be calculated later.
        hdr.ipv4.srcAddr = hdr.ipv6.srcAddr[63:32];
        hdr.ipv4.dstAddr = hdr.ipv6.dstAddr[95:64];
        hdr.udp.setValid();
        hdr.udp.srcPort = UDP_PORT_GTPU;

        hdr.udp.dstPort = UDP_PORT_GTPU;

        hdr.udp.length = hdr.ipv6.payloadLen + 16w20 -16w40;

        hdr.gtpu.setValid();
        hdr.gtpu.version = 3w1;
        hdr.gtpu.pt = 1w1;
        hdr.gtpu.reserved = 1w0;
        hdr.gtpu.e = 1w0;

// No Extention Header
        hdr.gtpu.s = 1w1;

// YES Sequence number
        hdr.gtpu.pn = 1w0;
        hdr.gtpu.messageType = GTPV1_GPDU;

        hdr.gtpu.messageLen = hdr.ipv6.payloadLen - 16w8 - (bit<16>)hdr.srh.hdrExtLen*8 + 16w4; 
        hdr.gtpu.teid = hdr.ipv6.dstAddr[55:24];

        hdr.gtpu.seq = 16w0;

        hdr.gtpu.npdu = 8w0;
        hdr.gtpu.nextExtHdr = 8w0;

// remove IPv6/SRH headers
        remove_srh_header();
        hdr.ipv6.setInvalid();

        cnt_srv6_e.count();
    }

    action end_am(PortId_t oif, EthernetAddress dmac) {

        hdr.ipv6.dstAddr = hdr.srh_sid[0].sid;
        hdr.ether.dstAddr = dmac;
        egress_port = oif;
    }

    action end_am_d(PortId_t oif) {

        hdr.srh.segmentsLeft = hdr.srh.segmentsLeft - 1;
        hdr.ipv6.dstAddr = user_md.srv6.nextsid;
        egress_port = oif;

    }
    table srv6_end {

// localsid
        key = {
            hdr.ipv6.dstAddr : ternary;

        }
        actions = {
            @defaultonly NoAction;

// SRv6 Network Program  : draft-filsfils-spring-srv6-network-programming
            end;



// SRv6 Mobile Userplane : draft-ietf-dmm-srv6-mobile-uplane
            end_m_gtp4_e;

// End.M.GTP4.E


// Proxy Functions : draft-xuclad-spring-sr-service-programming
            end_am;
        }
        const default_action = NoAction;
        counters = cnt_srv6_e;
    }
    table srv6_end_iif {

// Input Interface based SRv6 End.* table
        key = {
            in_port : exact;

        }
        actions = {
            @defaultonly NoAction;

// Proxy Functions : draft-xuclad-spring-sr-service-programming
            end_am_d;
        }
        const default_action = NoAction;
        counters = cnt_srv6_e_iif;
    }



/*** HELPER TABLE TO SET NEXT SID */
    action set_nextsid_1() {
        user_md.srv6.nextsid = hdr.srh_sid[0].sid;
    }
    action set_nextsid_2() {
        user_md.srv6.nextsid = hdr.srh_sid[1].sid;
    }
    action set_nextsid_3() {
        user_md.srv6.nextsid = hdr.srh_sid[2].sid;
    }
    action set_nextsid_4() {
        user_md.srv6.nextsid = hdr.srh_sid[3].sid;
    }
    table srv6_set_nextsid {

// helper table
        key = {
            hdr.srh.segmentsLeft : exact;
        }
        actions = {
            NoAction;
            set_nextsid_1;
            set_nextsid_2;
            set_nextsid_3;
            set_nextsid_4;
        }
        const default_action = NoAction;
        const entries = {
            (1) : set_nextsid_1();
            (2) : set_nextsid_2();
            (3) : set_nextsid_3();
            (4) : set_nextsid_4();
        }
    }

    action set_gtpu_type(bit<8> type) {
        hdr.gtpu.messageType = type;
    }
    action set_srv6_GTPV1_END() {
        hdr.srh.gtpMessageType = 1;
    }
    action set_srv6_GTPV1_ERROR() {
        hdr.srh.gtpMessageType = 2;
    }
    action set_srv6_GTPV1_ECHO() {
        hdr.srh.gtpMessageType = 4;
    }
    action set_srv6_GTPV1_ECHORES() {
        hdr.srh.gtpMessageType = 8;
    }
    apply {
        if (hdr.srh.isValid()) {
            srv6_set_nextsid.apply();
        }
        if (hdr.ipv6.isValid()) {
            if(!srv6_end_iif.apply().hit) {
                if(srv6_end.apply().hit) {

// draft-murakami-dmm-user-plane-message-encoding
                    if (user_md.srv6.gtp_message_type == 1) {

                        set_gtpu_type(GTPV1_END);
                    } else if (user_md.srv6.gtp_message_type == 2) {
                        set_gtpu_type(GTPV1_ERROR);
                    } else if (user_md.srv6.gtp_message_type == 4) {
                        set_gtpu_type(GTPV1_ECHO);
                    } else if (user_md.srv6.gtp_message_type == 8) {
                        set_gtpu_type(GTPV1_ECHORES);
                    }
                } else {
                    srv6_transit_v6.apply();
                }
            }
        } else if (hdr.ipv4.isValid()) {
            if(srv6_transit_udp.apply().hit) {

// Assuming this is GTP/SRv6 translation
                if (user_md.srv6.gtpv1_type == GTPV1_END) {
                    set_srv6_GTPV1_END();
                } else if (user_md.srv6.gtpv1_type == GTPV1_ERROR){
                    set_srv6_GTPV1_ERROR();
                } else if (user_md.srv6.gtpv1_type == GTPV1_ECHO){
                    set_srv6_GTPV1_ECHO();
                } else if (user_md.srv6.gtpv1_type == GTPV1_ECHORES){
                    set_srv6_GTPV1_ECHORES();
                }
            } else {
                srv6_transit_v4.apply();
            }
        }
    }
}


#endif /* _SRV6_ */




control L2Fwd(
    in EthernetAddress ether_dst_addr,
    inout IngressMetadata ig_md,
    inout PortId_t egress_port)
    (bit<32> table_size_dmac) {

    action dmac_miss() {

    }
    action dmac_hit(PortId_t port) {
        egress_port = port;
    }

    table dmac {
        key = {
            ether_dst_addr : exact;
        }
        actions = {
            dmac_miss;
            dmac_hit;
        }
        const default_action = dmac_miss;
        size = table_size_dmac;
    }

    apply {
        dmac.apply();
    }
}
control PortFwd(
        in PortId_t in_port,
        inout PortId_t egress_port) {

    action set_egress_port(PortId_t port) {
        egress_port = port;
    }

    table portfwd {
        key = {
            in_port : exact;

// ingress phy port
        }

        actions = {
            set_egress_port;
        }
    }

    apply {
        portfwd.apply();
    }
}


// CONTROL: INGRESS 

control SwitchIngress(
            inout Header hdr,
            inout UserMetadata user_md,
            inout standard_metadata_t st_md) {


// Instantiate controlls
    PortFwd() port_fwd;
    SRv6() srv6;
    L2Fwd(1024) l2fwd;


// Local MAC address. Apply Layer 3 tables when hit.
    action local_mac_hit() {}
    table local_mac {
        key = {
            hdr.ether.dstAddr : exact;
        }
        actions = {
            NoAction;
            local_mac_hit();
        }
        const default_action = NoAction;
        size = 512;

// number of Layer 3 interfaces
    }

    apply {

        mark_to_drop(st_md);

// set default action to drop to avoid unexpected packets going out.


// policy L1 (port) forwarding table useful untill l2fwd is implemented.
        port_fwd.apply(st_md.ingress_port, st_md.egress_spec);


        srv6.apply(hdr, user_md, st_md.ingress_port, st_md.egress_spec);


        l2fwd.apply(hdr.ether.dstAddr, user_md.ig_md, st_md.egress_spec);
    }
}




// CONTROL: EGRESS 

control SwitchEgress(
            inout Header hdr,
            inout UserMetadata user_md,
            inout standard_metadata_t st_md) {

// do nothing
    apply { }
}



// CONTROL: CHECKSUM 

control NoSwitchVerifyChecksum(
            inout Header hdr,
            inout UserMetadata user_md) {

// dummy control to skip checkum
    apply { }
}
control SwitchVerifyChecksum(
            inout Header hdr,
            inout UserMetadata user_md) {
    apply {
        verify_checksum(hdr.ipv4.isValid() && hdr.ipv4.ihl == 5,
            { hdr.ipv4.version,
                hdr.ipv4.ihl,
                hdr.ipv4.diffserv,
                hdr.ipv4.totalLen,
                hdr.ipv4.identification,
                hdr.ipv4.flags,
                hdr.ipv4.fragOffset,
                hdr.ipv4.ttl,
                hdr.ipv4.protocol,
                hdr.ipv4.srcAddr,
                hdr.ipv4.dstAddr },
            hdr.ipv4.hdrChecksum, HashAlgorithm.csum16);
    }
}

