    state parse_pkt_ack {
        packet.extract(hdr.pkt_ack);
        transition parse_data;
    }

    state parse_data {
        packet.extract(hdr.aes_inout);
        transition accept;
    }

    state parse_dh_probe {
        packet.extract(hdr.dh_probe.next);
        transition accept;
    }
}

