                if (keysize == 0x2){APPLY_SBOX_256(0);expand_01_256_r2();expand_02_256_r2();expand_set_t_02_r2();expand_03_256_r2();}

                // Key encrypt R4
                expand_set_t_01_r3();
                if (keysize == 0x1){expand_01_192_r3();expand_02_192_r3();expand_set_t_02_r3();}
