    ip4Addr_t   dstAddr;
}


/* metadata carried by the packet through the processing pipelines */
struct metadata {
    macAddr_t   dstMAC;

// the dst MAC to which the packet should be directed on L2
    bit<1>      isClient;

// whether the src IP of the packet belongs to a client
    bit<1>      isServer;

// whether the src IP of the packet belongs to a server
    bit<8>      srcGroup;

// the group of the src host
    bit<8>      dstGroup;

// the group of the dst host
}

struct headers {
    ethernet_t  ethernet;
    arp_t       arp;
    ipv4_t      ipv4;
}



parser SLBParser(packet_in packet,
                 out headers hdr,
                 inout metadata meta,
                 inout standard_metadata_t standard_metadata) {


/* begin with pointing to Ethernet frame parser */
    state start {
        transition parse_ethernet;
    }


/* parser ethernet frame */
    state parse_ethernet {

/* WRITE YOUR CODE HERE */
        packet.extract(hdr.ethernet);
        transition select(hdr.ethernet.etherType) {
            TYPE_ARP: parse_arp;
            TYPE_IPV4: parse_ipv4;
            default:accept;
        }

    }

    state parse_arp {
        packet.extract(hdr.arp);
        transition accept;

// accept; the ARP packet will be pushed to ingress pipeline
    }

    state parse_ipv4 {
        packet.extract(hdr.ipv4);

// accept; the IP packet will be pushed to ingress pipeline
        transition accept;
    }

}



control SLBVerifyChecksum(inout headers hdr, inout metadata meta) {
    apply {  }
}





control SLBIngress(inout headers hdr,
                   inout metadata meta,
                   inout standard_metadata_t standard_metadata) {


/* Action that instructs the pipeline to drop a packet */
    action drop() {
        mark_to_drop(standard_metadata);
    }


/* Action that transforms an ARP request into a suitable ARP reply */
    action arp_request_to_reply(macAddr_t srcMAC, macAddr_t dstMAC, ip4Addr_t srcIP, ip4Addr_t dstIP) {

/* WRITE YOUR CODE HERE */
        hdr.ethernet.srcAddr   = dstMAC;
        hdr.ethernet.dstAddr   = srcMAC;

        hdr.arp.hwSrcAddr    = dstMAC;
        hdr.arp.hwDstAddr    = srcMAC;
        hdr.arp.protoSrcAddr = dstIP;
        hdr.arp.protoDstAddr = srcIP;
        hdr.arp.opCode       = 2;

        standard_metadata.egress_spec = standard_metadata.ingress_port;

// the reply should be sent out of the in-port
    }


    action set_egress_metadata(macAddr_t dstMAC, egressSpec_t port) {
        meta.dstMAC = dstMAC;
        standard_metadata.egress_spec = port;
    }


    action set_client_metadata(ip4Addr_t firstAllowedReplica, ip4Addr_t lastAllowedReplica) {
        meta.isClient = 1;
        meta.isServer = 0;

/* WRITE YOUR CODE HERE */
        random(hdr.ipv4.dstAddr, firstAllowedReplica, lastAllowedReplica);
    }


/* Action that updates metadata with the info that the src IP does not belong to a client */
    action unset_client_metadata() {
        meta.isClient = 0;
    }


/* Action that updates metadata with the info that the src IP belongs to a server */
    action set_server_metadata() {
        meta.isServer = 1;
        meta.isClient = 0;
    }


/* Action that updates metadata with the info that the src IP does not belong to a server */
    action unset_server_metadata() {
        meta.isServer = 0;
    }


/* Action that sets the group membership for a src host */
    action set_src_membership(bit<8> group) {
        meta.srcGroup = group;
    }


/* Action that sets the group membership for a dst host */
    action set_dst_membership(bit<8> group) {
        meta.dstGroup = group;
    }


/* Table that stores the mapping between dst IP and dst MAC and egress port */
    table arpmap {

/* WRITE YOUR CODE HERE */
        key = {
            hdr.ipv4.dstAddr: lpm;
        }
        actions = {
            set_egress_metadata;
        }
    }


/* Table that stores the info that a certain IP belongs to a client */
    table ipv4_clients {
        key = {
            hdr.ipv4.srcAddr: lpm;
        }
        actions = {
            set_client_metadata;
            unset_client_metadata;
        }
    }


/* Table that stores the info that a certain IP belongs to a server */
    table ipv4_servers {

/* WRITE YOUR CODE HERE */
        key = {
            hdr.ipv4.srcAddr: lpm;
        }
        actions = {
            set_server_metadata;
            unset_server_metadata;
        }
    }


/* Table that stores the info about which src IP is member of which group */
    table src_group_membership {

/* WRITE YOUR CODE HERE */
        key = {
            hdr.ipv4.srcAddr: lpm;
        }
        actions = {
            set_src_membership;
        }
    }


/* Table that stores the info about which dst IP is member of which group */
    table dst_group_membership {

/* WRITE YOUR CODE HERE */
        key = {
            hdr.ipv4.dstAddr: lpm;
        }
        actions = {
            set_dst_membership;
        }
    }


/* Apply ingress workflow */
    apply {
        if (!(hdr.arp.isValid() || hdr.ipv4.isValid())) {
            drop();

// drop irrelevant/invalid traffic
        }
        else if (hdr.arp.isValid() && hdr.arp.opCode == 1) {

// handle incoming ARP requests
/* WRITE YOUR CODE HERE */
            arp_request_to_reply(hdr.ethernet.srcAddr, lbMAC, hdr.arp.protoSrcAddr, hdr.arp.protoDstAddr);
        }
        else if (hdr.ipv4.isValid()) {

/* WRITE YOUR CODE HERE */
            ipv4_clients.apply();
            ipv4_servers.apply();
            src_group_membership.apply();
            dst_group_membership.apply();

            if (!((meta.isClient == 1) || meta.isServer == 1) || meta.srcGroup != meta.dstGroup) {
                drop();

// drop if not coming from client or server
            }

// of if the src/dst groups differ
            else {
                arpmap.apply();

// prepare for egress
            }
        }
    }
}



control SLBEgress(inout headers hdr,
                  inout metadata meta,
                  inout standard_metadata_t standard_metadata) {


/* Action that rewrites the header of client-to-server packets */
    action rewrite_client_to_server() {

/* WRITE YOUR CODE HERE */
       hdr.ethernet.srcAddr = lbMAC;
       hdr.ethernet.dstAddr = meta.dstMAC;
    }


/* Action that rewrites the header of server-to-client packets */
    action rewrite_server_to_client() {

/* WRITE YOUR CODE HERE */
       hdr.ipv4.srcAddr     = serviceIP;

       hdr.ethernet.srcAddr = lbMAC;
       hdr.ethernet.dstAddr = meta.dstMAC;
    }


/* Apply egress workflow */
    apply {
        if (hdr.ipv4.isValid()) {

/* WRITE YOUR CODE HERE */
            if(meta.isClient == 1) {
                rewrite_client_to_server();
            }
            else if(meta.isServer == 1) {
                rewrite_server_to_client();
            }
        }
    }
}



control SLBComputeChecksum(inout headers  hdr, inout metadata meta) {
    apply {
        update_checksum(
            hdr.ipv4.isValid(),
            { hdr.ipv4.version,
              hdr.ipv4.ihl,
              hdr.ipv4.diffserv,
              hdr.ipv4.totalLen,
              hdr.ipv4.identification,
              hdr.ipv4.flags,
              hdr.ipv4.fragOffset,
              hdr.ipv4.ttl,
              hdr.ipv4.protocol,
              hdr.ipv4.srcAddr,
              hdr.ipv4.dstAddr },
            hdr.ipv4.hdrChecksum,
            HashAlgorithm.csum16);
    }
}



control SLBDeparser(packet_out packet, in headers hdr) {
    apply {
        packet.emit(hdr.ethernet);

// emit ethernet frame
        packet.emit(hdr.arp);

// emit ARP packet
        packet.emit(hdr.ipv4);

// emit IP packet
    }
}



V1Switch(
    SLBParser(),

// parse packet headers
    SLBVerifyChecksum(),

// verify thet the packet is valid
    SLBIngress(),

// apply ingress logic
    SLBEgress(),

// apply egress logic
    SLBComputeChecksum(),

// compute the new checksum for the IP packet
    SLBDeparser()

// deparse (serialize) the packet
) main;

