/* -*- P4_16 -*- */
#include <core.p4>
#include <v1model.p4>

#include "include/headers.p4"
#include "include/parsers.p4"
#include "include/checksum.p4"
#include "include/sink.p4"
#include "include/transit.p4"
#include "include/source.p4"
#include "include/forward.p4"

/********************************************************************
**************** I N G R E S S   P R O C E S S I N G ****************
********************************************************************/

control MyIngress(inout headers hdr,
                  inout local_metadata_t local_metadata,
                  inout standard_metadata_t standard_metadata) {

    apply {
        if(hdr.ipv4.isValid()) {

            // Perform L2 forwarding based on IPv4 destination address
            l3_forward.apply(hdr, local_metadata, standard_metadata);

            if (hdr.udp.isValid() || hdr.tcp.isValid()) {

                // Setting source and sink local metadata
                process_int_source_sink.apply(hdr, local_metadata, standard_metadata);

                // In case of source add the INT header
                if (local_metadata.int_meta.source == true) {
                    process_int_source.apply(hdr, local_metadata);
                }

                // Clone packet for Telemetry Report
                if (local_metadata.int_meta.sink == true && hdr.int_header.isValid()) {
                    local_metadata.perserv_meta.ingress_port = standard_metadata.ingress_port;
                    local_metadata.perserv_meta.egress_port = standard_metadata.egress_port;
                    local_metadata.perserv_meta.deq_qdepth = standard_metadata.deq_qdepth;
                    local_metadata.perserv_meta.deq_timedelta = standard_metadata.deq_timedelta;
                    local_metadata.perserv_meta.ingress_global_timestamp = standard_metadata.ingress_global_timestamp;
                    local_metadata.perserv_meta.egress_global_timestamp = standard_metadata.egress_global_timestamp;
                    clone_preserving_field_list(CloneType.I2E, REPORT_MIRROR_SESSION_ID, 1);

                }
            }
        }
    }
}

/********************************************************************
***************** E G R E S S   P R O C E S S I N G *****************
********************************************************************/

control MyEgress(inout headers hdr,
                 inout local_metadata_t local_metadata,
                 inout standard_metadata_t standard_metadata) {

    apply {
        // Insert old packet metadata into the cloned packet
        if(hdr.int_header.isValid() && standard_metadata.instance_type == CLONE_PKT) {
            standard_metadata.ingress_port = local_metadata.perserv_meta.ingress_port;
            standard_metadata.egress_port = local_metadata.perserv_meta.egress_port;
            standard_metadata.deq_qdepth = local_metadata.perserv_meta.deq_qdepth;
            standard_metadata.deq_timedelta = local_metadata.perserv_meta.deq_timedelta;
            standard_metadata.ingress_global_timestamp = local_metadata.perserv_meta.ingress_global_timestamp;
            standard_metadata.egress_global_timestamp = local_metadata.perserv_meta.egress_global_timestamp;
        }

        process_int_transit.apply(hdr, local_metadata, standard_metadata);

        // In case of cloned packet, send telemetry report
        if (standard_metadata.instance_type == CLONE_PKT) {
            process_int_report.apply(hdr, local_metadata, standard_metadata);
        }

        // In case of sink, remove INT header from original packet
        if (hdr.int_header.isValid() && local_metadata.int_meta.sink == true && standard_metadata.instance_type != CLONE_PKT) {
            process_int_sink.apply(hdr);
        }
    }
}

/***********************************************************
*********************** S W I T C H ************************
***********************************************************/

V1Switch(
    MyParser(),
    MyVerifyChecksum(),
    MyIngress(),
    MyEgress(),
    MyComputeChecksum(),
    MyDeparser()
) main;

cleaned_p4:
#include <core.p4>
#include <v1model.p4>



#define MAX_PORTS 511
#define CLONE_PKT 1

const bit<6> HW_ID = 1;

const bit<16> TYPE_IPV4 = 0x0800;
const bit<8>  IP_PROTO_UDP = 0x11;
const bit<8>  IP_PROTO_TCP = 0x6;

const bit<6> DSCP_INT = 0x17;
const bit<6> DSCP_MASK = 0x3F;

typedef bit<48> mac_t;
typedef bit<32> ip_address_t;
typedef bit<16> l4_port_t;
typedef bit<9>  port_t;
typedef bit<32> node_id_t;

const bit<32> REPORT_MIRROR_SESSION_ID = 500;


header ethernet_t {
    bit<48> dst_addr;
    bit<48> src_addr;
    bit<16> ether_type;
}

const bit<8> ETH_HEADER_LEN = 14;


header ipv4_t {
    bit<4>  version;
    bit<4>  ihl;
    bit<6>  dscp;
    bit<2>  ecn;
    bit<16> len;
    bit<16> identification;
    bit<3>  flags;
    bit<13> frag_offset;
    bit<8>  ttl;
    bit<8>  protocol;
    bit<16> hdr_checksum;
    bit<32> src_addr;
    bit<32> dst_addr;
}

const bit<8> IPV4_MIN_HEAD_LEN = 20;


header udp_t {
    bit<16> src_port;
    bit<16> dst_port;
    bit<16> length_;
    bit<16> checksum;
}

const bit<8> UDP_HEADER_LEN = 8;


header tcp_t {
    bit<16> src_port;
    bit<16> dst_port;
    bit<32> seq_no;
    bit<32> ack_no;
    bit<4>  data_offset;
    bit<3>  res;
    bit<3>  ecn;
    bit<6>  ctrl;
    bit<16> window;
    bit<16> checksum;
    bit<16> urgent_ptr;
}

const bit<8> TCP_HEADER_LEN = 20;



// INT shim header for INT over TCP/UDP
header intl4_shim_t {
    bit<4> int_type;

// Type of INT Header
    bit<2> npt;

// Next protocol type
    bit<2> rsvd1;

// Reserved
    bit<8> len;

// Length of INT Metadata header and INT stack in 4-byte words, not including the shim header (1 word)
    bit<8> rsvd2;

// Reserved
    bit<6> original_dscp;

// Original DSCP value
    bit<2> rsvd3;

// Reserved
}

const bit<16> INT_SHIM_HEADER_SIZE = 4;


// INT header
header int_header_t {
    bit<4>   ver;

// Version
    bit<1>   d;

// Discard
    bit<1>   e;
    bit<1>   m;
    bit<12>  rsvd1;
    bit<5>   hop_metadata_len;
    bit<8>   remaining_hop_cnt;
    bit<4>   instruction_mask_0003;

// Split the bits for lookup
    bit<4>   instruction_mask_0407;
    bit<4>   instruction_mask_0811;
    bit<4>   instruction_mask_1215;
    bit<16>  domain_specific_id;

// Unique INT Domain ID
    bit<16>  ds_instruction;

// Instruction bitmap specific to the INT Domain identified by the Domain specific ID
    bit<16>  ds_flags;

// Domain specific flags
}

const bit<16> INT_HEADER_SIZE = 12;
const bit<8> INT_HEADER_WORD = 3;
const bit<16> INT_TOTAL_HEADER_SIZE = INT_HEADER_SIZE + INT_SHIM_HEADER_SIZE;



// INT meta-value headers - different header for each value type to monitor
header int_node_id_t {
    bit<32> node_id;
}
header int_level1_port_ids_t {
    bit<16> ingress_port_id;
    bit<16> egress_port_id;
}
header int_hop_latency_t {
    bit<32> hop_latency;
}
header int_q_occupancy_t {
    bit<8> q_id;
    bit<24> q_occupancy;
}
header int_ingress_tstamp_t {
    bit<64> ingress_tstamp;
}
header int_egress_tstamp_t {
    bit<64> egress_tstamp;
}
header int_level2_port_ids_t {
    bit<32> ingress_port_id;
    bit<32> egress_port_id;
}


// These two are not implemented yet
header int_egress_port_tx_util_t {
    bit<32> egress_port_tx_util;

// This is used but the queue latency is gathered instead
}

header int_buffer_t {
    bit<8> buffer_id;
    bit<24> buffer_occupancy;
}

header int_data_t {

    varbit<1920> data;
}


// Report Telemetry Headers - Group Header
header report_group_header_t {
    bit<4>  ver;
    bit<6>  hw_id;
    bit<22> seq_no;
    bit<32> node_id;
}
const bit<8> REPORT_GROUP_HEADER_LEN = 8;


// Report Telemetry Headers - Individual Header
header report_individual_header_t {
    bit<4>  rep_type;
    bit<4>  in_type;
    bit<8>  len;
    bit<8>  rep_md_len;
    bit<1>  d;
    bit<1>  q;
    bit<1>  f;
    bit<1>  i;
    bit<4>  rsvd;

    bit<16> rep_md_bits;
    bit<16> domain_specific_id;
    bit<16> domain_specific_md_bits;
    bit<16> domain_specific_md_status;
}
const bit<8> REPORT_INDIVIDUAL_HEADER_LEN = 12;


// Preserving metadata header for the cloned packet
struct preserving_metadata_t {
    @field_list(1)
    bit<9> ingress_port;
    @field_list(1)
    bit<9> egress_port;
    @field_list(1)
    bit<32> deq_timedelta;
    @field_list(1)
    bit<19> deq_qdepth;
    @field_list(1)
    bit<48> ingress_global_timestamp;
    @field_list(1)
    bit<48> egress_global_timestamp;
}

struct headers {


// Original Packet Headers
    ethernet_t                  ethernet;
    ipv4_t			            ipv4;
    udp_t			            udp;
    tcp_t			            tcp;


// INT Report Encapsulation
    ethernet_t                  report_ethernet;
    ipv4_t                      report_ipv4;
    udp_t                       report_udp;


// INT Headers
    int_header_t                int_header;
    intl4_shim_t                intl4_shim;


//INT Metadata
    int_data_t                  int_data;
    int_node_id_t               int_node_id;
    int_level1_port_ids_t       int_level1_port_ids;
    int_hop_latency_t           int_hop_latency;
    int_q_occupancy_t           int_q_occupancy;
    int_ingress_tstamp_t        int_ingress_tstamp;
    int_egress_tstamp_t         int_egress_tstamp;
    int_level2_port_ids_t       int_level2_port_ids;
    int_egress_port_tx_util_t   int_egress_tx_util;


// INT Report Headers
    report_group_header_t       report_group_header;
    report_individual_header_t  report_individual_header;
}

struct int_metadata_t {
    node_id_t node_id;
    bit<16> new_bytes;
    bit<8>  new_words;
    bool  source;
    bool  sink;
    bit<8> intl4_shim_len;
}

struct local_metadata_t {
    bit<16>       l4_src_port;
    bit<16>       l4_dst_port;
    int_metadata_t int_meta;
    preserving_metadata_t perserv_meta;
}



parser MyParser( packet_in packet,
                        out headers hdr,
                        inout local_metadata_t local_metadata,
                        inout standard_metadata_t standard_metadata) {

    state start {
        transition parse_ethernet;
    }

    state parse_ethernet {
        packet.extract(hdr.ethernet);
        transition select(hdr.ethernet.ether_type) {
            TYPE_IPV4: parse_ipv4;
            default: accept;
        }
    }

    state parse_ipv4 {
        packet.extract(hdr.ipv4);
        transition select(hdr.ipv4.protocol) {
            IP_PROTO_UDP: parse_udp;
            IP_PROTO_TCP: parse_tcp;
            default: accept;
        }
    }

    state parse_udp {
        packet.extract(hdr.udp);
        local_metadata.l4_src_port = hdr.udp.src_port;
        local_metadata.l4_dst_port = hdr.udp.dst_port;
        transition select(hdr.ipv4.dscp) {
            DSCP_INT &&& DSCP_MASK: parse_shim;
            default:  accept;
        }
    }

    state parse_tcp {
        packet.extract(hdr.tcp);
        local_metadata.l4_src_port = hdr.tcp.src_port;
        local_metadata.l4_dst_port = hdr.tcp.dst_port;
        transition select(hdr.ipv4.dscp) {
            DSCP_INT &&& DSCP_MASK: parse_shim;
            default:  accept;
        }
    }

    state parse_shim {
        packet.extract(hdr.intl4_shim);
        local_metadata.int_meta.intl4_shim_len = hdr.intl4_shim.len;
        transition parse_int_hdr;
    }

    state parse_int_hdr {
        packet.extract(hdr.int_header);
        transition parse_int_data;
    }

    state parse_int_data {
        packet.extract(hdr.int_data, ((bit<32>) (local_metadata.int_meta.intl4_shim_len - INT_HEADER_WORD)) << 5);
        transition accept;
    }
}




control MyDeparser(packet_out packet, 
                         in headers hdr) {

    apply {

        packet.emit(hdr.report_ethernet);
        packet.emit(hdr.report_ipv4);
        packet.emit(hdr.report_udp);

        packet.emit(hdr.report_group_header);
        packet.emit(hdr.report_individual_header);

        packet.emit(hdr.ethernet);
        packet.emit(hdr.ipv4);
        packet.emit(hdr.udp);
        packet.emit(hdr.tcp);

        packet.emit(hdr.intl4_shim);
        packet.emit(hdr.int_header);

        packet.emit(hdr.int_node_id);
        packet.emit(hdr.int_level1_port_ids);
        packet.emit(hdr.int_hop_latency);
        packet.emit(hdr.int_q_occupancy);
        packet.emit(hdr.int_ingress_tstamp);
        packet.emit(hdr.int_egress_tstamp);
        packet.emit(hdr.int_level2_port_ids);
        packet.emit(hdr.int_egress_tx_util);

        packet.emit(hdr.int_data);        
    }
}

control MyVerifyChecksum(inout headers hdr, inout local_metadata_t local_metadata) {
    apply {
        verify_checksum(
            hdr.ipv4.isValid(),
            { hdr.ipv4.version,
              hdr.ipv4.ihl,
              hdr.ipv4.dscp,
              hdr.ipv4.ecn,
              hdr.ipv4.len,
              hdr.ipv4.identification,
              hdr.ipv4.flags,
              hdr.ipv4.frag_offset,
              hdr.ipv4.ttl,
              hdr.ipv4.protocol,
              hdr.ipv4.src_addr,
              hdr.ipv4.dst_addr },
            hdr.ipv4.hdr_checksum,
            HashAlgorithm.csum16
        );
     }
}

control MyComputeChecksum(inout headers hdr, inout local_metadata_t local_metadata){
    apply{
        update_checksum(
            hdr.ipv4.isValid(),
            { hdr.ipv4.version,
              hdr.ipv4.ihl,
              hdr.ipv4.dscp,
              hdr.ipv4.ecn,
              hdr.ipv4.len,
              hdr.ipv4.identification,
              hdr.ipv4.flags,
              hdr.ipv4.frag_offset,
              hdr.ipv4.ttl,
              hdr.ipv4.protocol,
              hdr.ipv4.src_addr,
              hdr.ipv4.dst_addr },
            hdr.ipv4.hdr_checksum,
            HashAlgorithm.csum16
        );

    }

}

control process_int_sink (
    inout headers hdr) {

    action restore_header () {
        hdr.ipv4.dscp = hdr.intl4_shim.original_dscp;
        bit<16> len_bytes = (((bit<16>)hdr.intl4_shim.len) << 2) + INT_SHIM_HEADER_SIZE;
        hdr.ipv4.len = hdr.ipv4.len - len_bytes;
        if(hdr.udp.isValid()) {
            hdr.udp.length_ = hdr.udp.length_ - len_bytes;
        }
    }


    action int_sink() {

// remove all the INT information from the packet
        hdr.intl4_shim.setInvalid();
        hdr.int_header.setInvalid();
        hdr.int_node_id.setInvalid();
        hdr.int_level1_port_ids.setInvalid();
        hdr.int_hop_latency.setInvalid();
        hdr.int_q_occupancy.setInvalid();
        hdr.int_ingress_tstamp.setInvalid();
        hdr.int_egress_tstamp.setInvalid();
        hdr.int_level2_port_ids.setInvalid();
        hdr.int_egress_tx_util.setInvalid();
        hdr.int_data.setInvalid();
    }

    apply {
        restore_header();
        int_sink();
    }
}


// Action for the INT telemetry report, as it is encapsulated with new Ethernet, IP and UDP headers
control process_int_report (inout headers hdr,
                            inout local_metadata_t local_metadata,
                            inout standard_metadata_t standard_metadata) {


// Register for sequence number
    register<bit<22>>(1) seq_number;

    action increment_counter() {
        bit<22> tmp;
        seq_number.read(tmp, 0);
        tmp = tmp + 1;
        seq_number.write(0, tmp);
    }

    action do_report_encapsulation(mac_t src_mac,
                                mac_t mon_mac, 
                                ip_address_t src_ip,
                                ip_address_t mon_ip, 
                                l4_port_t src_port, 
                                l4_port_t mon_port) {


// Report Ethernet Header
        hdr.report_ethernet.setValid();
        hdr.report_ethernet.dst_addr = mon_mac;
        hdr.report_ethernet.src_addr = src_mac;
        hdr.report_ethernet.ether_type = 0x0800;


// Report IPV4 Header
        hdr.report_ipv4.setValid();
        hdr.report_ipv4.version = 4w4;
        hdr.report_ipv4.ihl = 4w5;
        hdr.report_ipv4.dscp = 6w0;
        hdr.report_ipv4.ecn = 2w0;

        if (hdr.udp.isValid()) {
            hdr.report_ipv4.len = (bit<16>) IPV4_MIN_HEAD_LEN + (bit<16>) UDP_HEADER_LEN + (bit<16>) REPORT_GROUP_HEADER_LEN + (bit<16>) REPORT_INDIVIDUAL_HEADER_LEN + 
            local_metadata.int_meta.new_bytes + (bit<16>) IPV4_MIN_HEAD_LEN + (bit<16>) UDP_HEADER_LEN + (bit<16>) INT_SHIM_HEADER_SIZE + (((bit<16>) hdr.intl4_shim.len) << 2);
        } else if (hdr.tcp.isValid()) {
            hdr.report_ipv4.len = (bit<16>) IPV4_MIN_HEAD_LEN + (bit<16>) UDP_HEADER_LEN + (bit<16>) REPORT_GROUP_HEADER_LEN + (bit<16>) REPORT_INDIVIDUAL_HEADER_LEN + 
            local_metadata.int_meta.new_bytes + (bit<16>) IPV4_MIN_HEAD_LEN + (bit<16>) TCP_HEADER_LEN + (bit<16>) INT_SHIM_HEADER_SIZE + (((bit<16>) hdr.intl4_shim.len) << 2);
        }

        hdr.report_ipv4.identification = 0;
        hdr.report_ipv4.flags = 0;
        hdr.report_ipv4.frag_offset = 0;
        hdr.report_ipv4.ttl = 64;
        hdr.report_ipv4.protocol = IP_PROTO_UDP;
        hdr.report_ipv4.src_addr = src_ip;
        hdr.report_ipv4.dst_addr = mon_ip;


//Report UDP Header
        hdr.report_udp.setValid();
        hdr.report_udp.src_port = src_port;
        hdr.report_udp.dst_port = mon_port;

        if (hdr.udp.isValid()) {
            hdr.report_udp.length_ = (bit<16>) UDP_HEADER_LEN + (bit<16>) REPORT_GROUP_HEADER_LEN + (bit<16>) REPORT_INDIVIDUAL_HEADER_LEN + 
            local_metadata.int_meta.new_bytes + (bit<16>) IPV4_MIN_HEAD_LEN + (bit<16>) UDP_HEADER_LEN + (bit<16>) INT_SHIM_HEADER_SIZE + (((bit<16>) hdr.intl4_shim.len) << 2);
        } else if (hdr.tcp.isValid()) {
            hdr.report_udp.length_ = (bit<16>) UDP_HEADER_LEN + (bit<16>) REPORT_GROUP_HEADER_LEN + (bit<16>) REPORT_INDIVIDUAL_HEADER_LEN + 
            local_metadata.int_meta.new_bytes + (bit<16>) IPV4_MIN_HEAD_LEN + (bit<16>) TCP_HEADER_LEN + (bit<16>) INT_SHIM_HEADER_SIZE + (((bit<16>) hdr.intl4_shim.len) << 2);
        }


// Telemetry Group Header
        hdr.report_group_header.setValid();
        hdr.report_group_header.ver = 2;

// Version 2.0
        hdr.report_group_header.hw_id = HW_ID;

// Default Value 1
        seq_number.read(hdr.report_group_header.seq_no, 0);
        increment_counter();
        hdr.report_group_header.node_id = local_metadata.int_meta.node_id;



// Telemetry Report Individual Header
        hdr.report_individual_header.setValid();
        hdr.report_individual_header.rep_type = 1;

// INT Report
        hdr.report_individual_header.in_type = 4;

// Individual Report Inner Content is an IPv4 packet
        if (hdr.udp.isValid()) {
            hdr.report_individual_header.len = 2 + local_metadata.int_meta.new_words + 5 + 2 + 4;
        } else if (hdr.tcp.isValid()) {
            hdr.report_individual_header.len = 2 + local_metadata.int_meta.new_words + 5 + 5 + 4;
        }
        hdr.report_individual_header.rep_md_len = local_metadata.int_meta.new_words;
        hdr.report_individual_header.d = 0;
        hdr.report_individual_header.q = 0;
        hdr.report_individual_header.f = 1;
        hdr.report_individual_header.i = 0;
        hdr.report_individual_header.rsvd = 0;


// Individual report main contents
        hdr.report_individual_header.rep_md_bits = hdr.int_header.instruction_mask_0003 ++ hdr.int_header.instruction_mask_0407 ++ 
                                                    hdr.int_header.instruction_mask_0811 ++ hdr.int_header.instruction_mask_1215;
        hdr.report_individual_header.domain_specific_id = 0;
        hdr.report_individual_header.domain_specific_md_bits = 0;
        hdr.report_individual_header.domain_specific_md_status = 0;

        hdr.ethernet.setInvalid();
    }

    table tb_generate_report {
        actions = {
            do_report_encapsulation;
            NoAction();
        }
        default_action = do_report_encapsulation(0, 0, 0, 0, 0, 0);
    }

    apply {
        tb_generate_report.apply();
    }
}

control process_int_transit (
    inout headers hdr,
    inout local_metadata_t local_metadata,
    inout standard_metadata_t standard_metadata) {

    action init_metadata(node_id_t node_id) {
        local_metadata.int_meta.node_id = node_id;
    }


// Node ID
    action int_set_header_0() { 
        hdr.int_node_id.setValid();
        hdr.int_node_id.node_id = local_metadata.int_meta.node_id;
    }


// Level 1 ingress interface ID + Egress interface ID
    action int_set_header_1() { 
        hdr.int_level1_port_ids.setValid();
        hdr.int_level1_port_ids.ingress_port_id = (bit<16>) standard_metadata.ingress_port;
        hdr.int_level1_port_ids.egress_port_id = (bit<16>) standard_metadata.egress_port;
    }


// Hop latency
    action int_set_header_2() { 
        hdr.int_hop_latency.setValid();
        hdr.int_hop_latency.hop_latency = (bit<32>) standard_metadata.egress_global_timestamp - (bit<32>) standard_metadata.ingress_global_timestamp;
    }


// Queue ID and queue occupancy
    action int_set_header_3() { 
        hdr.int_q_occupancy.setValid();

        hdr.int_q_occupancy.q_id = 0;
        hdr.int_q_occupancy.q_occupancy = (bit<24>) standard_metadata.deq_qdepth;
