        hdr.int_egress_tx_util.egress_port_tx_util = (bit<32>) standard_metadata.deq_timedelta;
    }


// Actions to keep track of the new metadata added
    action add_1() {
        local_metadata.int_meta.new_words = local_metadata.int_meta.new_words + 1;
