        add_2();
    }

    action int_set_header_0003_i11() {
        int_set_header_3();
        int_set_header_2();
        int_set_header_0();
        add_3();
    }

    action int_set_header_0003_i12() {
        int_set_header_1();
        int_set_header_0();
        add_2();
    }

    action int_set_header_0003_i13() {
        int_set_header_3();
        int_set_header_1();
        int_set_header_0();
        add_3();
    }

    action int_set_header_0003_i14() {
        int_set_header_2();
        int_set_header_1();
        int_set_header_0();
        add_3();
    }

    action int_set_header_0003_i15() {
        int_set_header_3();
        int_set_header_2();
        int_set_header_1();
        int_set_header_0();
        add_4();
    }


// Action to process instruction bits 4-7
    action int_set_header_0407_i0() {
    }

    action int_set_header_0407_i1() {
        int_set_header_7();
        add_1();
    }

    action int_set_header_0407_i2() {
        int_set_header_6();
        add_2();
    }

    action int_set_header_0407_i3() {
        int_set_header_7();
        int_set_header_6();
        add_3();
    }

    action int_set_header_0407_i4() {
        int_set_header_5();
        add_2();
    }

    action int_set_header_0407_i5() {
        int_set_header_7();
        int_set_header_5();
        add_3();
    }

    action int_set_header_0407_i6() {
        int_set_header_6();
        int_set_header_5();
        add_4();
    }

    action int_set_header_0407_i7() {
        int_set_header_7();
        int_set_header_6();
        int_set_header_5();
        add_5();
