const bit<16> P4CALC_ETYPE = 0x1234;
const bit<8>  P4CALC_P     = 0x4B;

// K - KYBER
const bit<8>  GEN  = 0x47;

// 'G'
const bit<8>  ENC = 0x45;

// 'E'
const bit<8>  DEC   = 0x44;

// 'D'
const bit<32> PARAM_Q = 3329;

header p4calc_t {
    bit<8>  p;
    bit<8>  op;

    bit<32> t_0;
    bit<32> t_1;
    bit<32> t_2;
    bit<32> t_3;
    bit<32> t_4;
    bit<32> t_5;
    bit<32> t_6;
    bit<32> t_7;
    bit<32> t_8;
    bit<32> t_9;

    bit<32> seed;
}


struct headers {
    ethernet_t   ethernet;
    p4calc_t     p4calc;
}


struct metadata {

/* In our case it is empty */
}


parser MyParser(packet_in packet,
                out headers hdr,
                inout metadata meta,
                inout standard_metadata_t standard_metadata) {

    state start {
        packet.extract(hdr.ethernet);
        transition select(hdr.ethernet.etherType) {
            P4CALC_ETYPE : check_p4calc;
            default      : accept;
        }
    }

    state check_p4calc {
        transition select(packet.lookahead<p4calc_t>().p) {
            (P4CALC_P) : parse_p4calc;
            default    : accept;
        }
    }

    state parse_p4calc {
        packet.extract(hdr.p4calc);
        transition accept;
    }
}


control MyVerifyChecksum(inout headers hdr,
                         inout metadata meta) {
    apply { }
}


