#include <core.p4>
#include <v1model.p4>


#ifndef _CONFIG_P4_
#define _CONFIG_P4_

#define SRC_ENABLE true
#define SINK_ENABLE false
#define SWITCH_ID 0

#endif




#ifndef _HEADERS_P4_
#define _HEADERS_P4_

header ethernet_t {
    bit<48> dstAddr;
    bit<48> srcAddr;
    bit<16> etherType;
}

header ipv4_t {
    bit<4>  version;
    bit<4>  ihl;
    bit<6>  dscp;
    bit<2>  ecn;
    bit<16> totalLen;
    bit<16> id;
    bit<3>  flags;
    bit<13> fragOffset;
    bit<8>  ttl;
    bit<8>  protocol;
    bit<16> checksum;
    bit<32> srcAddr;
    bit<32> dstAddr;
}

header udp_t {
    bit<16> srcPort;
    bit<16> dstPort;
    bit<16> len;
    bit<16> csum;
}

header tcp_t {
    bit<16> srcPort;
    bit<16> dstPort;
    bit<32> seqNum;
    bit<32> ackNum;
    bit<4>  dataOffset;
    bit<3>  reserved;
    bit<9>  flags;
    bit<16> winSize;
    bit<16> csum;
    bit<16> urgPoint;
}

const bit<6> IPv4_DSCP_INT = 0x20;

// indicates that INT header in the packet
const bit<16> INT_SHIM_HEADER_LEN_BYTES = 4;
const bit<8> INT_TYPE_HOP_BY_HOP = 1;

header intl4_shim_t {
    bit<8> int_type;
    bit<8> rsvd1;
    bit<8> len;

// the length of all INT headers in 4-byte words
    bit<6> dscp;

// copy DSCP here
    bit<2> rsvd3;
}

const bit<16> INT_HEADER_LEN_BYTES = 8;
const bit<4> INT_VERSION = 1;

header int_header_t {
    bit<4>  ver;
    bit<2>  rep;
    bit<1>  c;
    bit<1>  e;
    bit<1>  m;
    bit<7>  rsvd1;
    bit<3>  rsvd2;
    bit<5>  hop_metadata_len;

// the length of the metadata added by a single INT node (4-byte words)
    bit<8>  remaining_hop_cnt;

// how many switches can still add INT metadata
    bit<16> instruction_mask;
    bit<16>  seq;
}

const bit<16> INT_ALL_HEADER_LEN_BYTES = INT_SHIM_HEADER_LEN_BYTES + INT_HEADER_LEN_BYTES;

header int_switch_id_t {
    bit<32> switch_id;
}

header int_port_ids_t {
    bit<16> ingress_port_id;
    bit<16> egress_port_id;
}

header int_hop_latency_t {
    bit<32> hop_latency;
}

header int_q_occupancy_t {
    bit<8>  q_id;
    bit<24> q_occupancy;
}

header int_ingress_tstamp_t {
    bit<32> ingress_tstamp_h;
    bit<32> ingress_tstamp_l;
}

header int_egress_tstamp_t {
    bit<32> egress_tstamp_h;
    bit<32> egress_tstamp_l;
}

header int_level2_port_ids_t {
    bit<16> ingress_port_id;
    bit<16> egress_port_id;
}

header int_egress_port_tx_util_t {
    bit<32> egress_port_tx_util;
}

header influx_t {
    bit<32> srcAddr;
    bit<32> dstAddr;
    bit<16> ingress_port_id;
    bit<16> egress_port_id;
    bit<8>  meta_len;
    bit<3>  resv1;
    bit<5>  hop_meta_len;
    bit<16> rsvd2;
    bit<32> ndk_tstamp_h;
    bit<32> ndk_tstamp_l;
    bit<32> delay_h;
    bit<32> delay_l;
    bit<32> seq;
}


struct layer34_metadata_t {
    bit<16> l4_src;
    bit<16> l4_dst;
    bit<6> dscp;
}

struct metadata {
    bit<7>  padding;
    bit<32> ingress_tstamp_system_h;
    bit<32> ingress_tstamp_system_l;
    bit<32> egress_tstamp_system_h;
    bit<32> egress_tstamp_system_l;
    layer34_metadata_t layer34_metadata;
}

struct headers {

// normal headers
    ethernet_t ethernet;
    ipv4_t     ipv4;
    tcp_t      tcp;
    udp_t      udp;


// INT headers
    intl4_shim_t int_shim;
    int_header_t int_header;


// local INT node metadata
    int_egress_port_tx_util_t int_egress_port_tx_util;
    int_egress_tstamp_t       int_egress_tstamp;
    int_hop_latency_t         int_hop_latency;
    int_ingress_tstamp_t      int_ingress_tstamp;
    int_port_ids_t            int_port_ids;
    int_level2_port_ids_t     int_level2_port_ids;
    int_q_occupancy_t         int_q_occupancy;
    int_switch_id_t           int_switch_id;


// INT Sink export header
    influx_t                  influx;
}

#endif



error
{
    INTShimLenTooShort,
    INTVersionNotSupported
}

parser ParserImpl(packet_in packet, out headers hdr, inout metadata meta, inout standard_metadata_t standard_metadata) {
    state start {
        transition parse_ethernet;
    }
    state parse_ethernet {
        packet.extract(hdr.ethernet);
        transition select(hdr.ethernet.etherType) {
            16w0x800: parse_ipv4;
            default: accept;
        }
    }
    state parse_ipv4 {
        packet.extract(hdr.ipv4);
        meta.layer34_metadata.dscp = hdr.ipv4.dscp;
        transition select(hdr.ipv4.protocol) {
            8w0x11: parse_udp;
            8w0x6: parse_tcp;
            default: accept;
        }
    }
    state parse_tcp {
        packet.extract(hdr.tcp);
        meta.layer34_metadata.l4_src = hdr.tcp.srcPort;
        meta.layer34_metadata.l4_dst = hdr.tcp.dstPort;
        transition select(meta.layer34_metadata.dscp) {
            IPv4_DSCP_INT: parse_int_shim;
            default: accept;
        }
    }
    state parse_udp {
        packet.extract(hdr.udp);
        meta.layer34_metadata.l4_src = hdr.udp.srcPort;
        meta.layer34_metadata.l4_dst = hdr.udp.dstPort;
        transition select(meta.layer34_metadata.dscp) {
            IPv4_DSCP_INT: parse_int_shim;
            default: accept;
        }
    }
    state parse_int_shim {
        packet.extract(hdr.int_shim);
        verify(hdr.int_shim.len >= 3, error.INTShimLenTooShort);
        transition parse_int_header;
    }
    state parse_int_header {
        packet.extract(hdr.int_header);
        verify(hdr.int_header.ver == INT_VERSION, error.INTVersionNotSupported);
        transition accept;
    }
}


control DeparserImpl(packet_out packet, in headers hdr) {
    apply {

// original headers
        packet.emit(hdr.ethernet);
        packet.emit(hdr.ipv4);
        packet.emit(hdr.udp);
        packet.emit(hdr.tcp);


// INT headers
        packet.emit(hdr.int_shim);
        packet.emit(hdr.int_header);


// local INT node metadata
        packet.emit(hdr.int_switch_id);

// bit 1
        packet.emit(hdr.int_port_ids);

// bit 2
        packet.emit(hdr.int_hop_latency);

// bit 3
        packet.emit(hdr.int_q_occupancy);

// bit 4
        packet.emit(hdr.int_ingress_tstamp);

// bit 5
        packet.emit(hdr.int_egress_tstamp);

// bit 6
        packet.emit(hdr.int_level2_port_ids);

// bit 7
        packet.emit(hdr.int_egress_port_tx_util);

// bit 8

        packet.emit(hdr.influx);
    }
}

control verifyChecksum(inout headers hdr, inout metadata meta) {
    apply {
    }
}

control computeChecksum(inout headers hdr, inout metadata meta) {
    apply {
    }
}




control Int_source(inout headers hdr, inout metadata meta, inout standard_metadata_t standard_metadata) {

    register<bit<16>>(1) reg1;

    action configure_source() {
        hdr.int_shim.setValid();
        hdr.int_shim.int_type = INT_TYPE_HOP_BY_HOP;
        hdr.int_shim.len = (bit<8>)INT_ALL_HEADER_LEN_BYTES>>2;

        hdr.int_header.setValid();
        hdr.int_header.ver = INT_VERSION;
        hdr.int_header.rep = 0;
        hdr.int_header.c = 0;
        hdr.int_header.e = 0;
        hdr.int_header.rsvd1 = 1;
        hdr.int_header.rsvd2 = 0;
        hdr.int_header.hop_metadata_len = 0x06;
        hdr.int_header.remaining_hop_cnt = 0xff;

// will be decreased immediately by 1 within transit process
        hdr.int_header.instruction_mask = 0x00cc; 


        reg1.read(hdr.int_header.seq, 0);
        reg1.write(0, hdr.int_header.seq);

        reg1.read(hdr.int_header.seq, 0);
        hdr.int_header.seq = hdr.int_header.seq + 1;
        reg1.write(0, hdr.int_header.seq);

        hdr.int_shim.dscp = hdr.ipv4.dscp;

        hdr.ipv4.dscp = IPv4_DSCP_INT;

// indicates that INT header in the packet
        hdr.ipv4.totalLen = hdr.ipv4.totalLen + INT_ALL_HEADER_LEN_BYTES;

// adding size of INT headers

        hdr.udp.len = hdr.udp.len + INT_ALL_HEADER_LEN_BYTES;
        hdr.udp.csum = 0;
        hdr.tcp.csum = 0;
   }


    table tb_int_source {
        actions = {
            configure_source;
        }
        key = {
            hdr.ipv4.srcAddr     : ternary;
            hdr.ipv4.dstAddr     : ternary;
            meta.layer34_metadata.l4_src: ternary;
            meta.layer34_metadata.l4_dst: ternary;
        }
        size = 128;
        default_action = configure_source();

    }

    apply {
        if (SRC_ENABLE)      
            tb_int_source.apply();
    }
}




control Int_transit(inout headers hdr, inout metadata meta, inout standard_metadata_t standard_metadata) {
    action int_set_header_0() {
        hdr.int_switch_id.setValid();
        hdr.int_switch_id.switch_id = SWITCH_ID;
    }
    action int_set_header_1() {
        hdr.int_port_ids.setValid();
        hdr.int_port_ids.ingress_port_id = (bit<16>)standard_metadata.ingress_port;
        hdr.int_port_ids.egress_port_id = (bit<16>)standard_metadata.egress_port;
    }
    action int_set_header_2() {
        hdr.int_hop_latency.setValid();
        hdr.int_hop_latency.hop_latency = 0;

    }
    action int_set_header_3() {
        hdr.int_q_occupancy.setValid();
        hdr.int_q_occupancy.q_id = 0;

// qid not defined in v1model
        hdr.int_q_occupancy.q_occupancy = (bit<24>)standard_metadata.enq_qdepth;
    }
    action int_set_header_4() {
        hdr.int_ingress_tstamp.setValid();
        hdr.int_ingress_tstamp.ingress_tstamp_h = meta.ingress_tstamp_system_h;
        hdr.int_ingress_tstamp.ingress_tstamp_l = meta.ingress_tstamp_system_l;
    }
    action int_set_header_5() {
        hdr.int_egress_tstamp.setValid();
        hdr.int_egress_tstamp.egress_tstamp_h = meta.egress_tstamp_system_h;
        hdr.int_egress_tstamp.egress_tstamp_l = meta.egress_tstamp_system_l;
    }
    action int_set_header_6() {
        hdr.int_level2_port_ids.setValid();
        hdr.int_level2_port_ids.ingress_port_id = 0;
        hdr.int_level2_port_ids.egress_port_id = 0;
    }
    action int_set_header_7() {
        hdr.int_egress_port_tx_util.setValid();
        hdr.int_egress_port_tx_util.egress_port_tx_util = 0;
    }

    action int_hop_cnt_increment() {
        hdr.int_header.remaining_hop_cnt = hdr.int_header.remaining_hop_cnt - 1;
    }
    action int_hop_exceeded() {
        hdr.int_header.e = 1w1;
    }



    apply {
        if (!SINK_ENABLE) {

// INT transit must process only INT packets
            if (!hdr.int_header.isValid())
                return;

            int_set_header_0();
            int_set_header_1();
            int_set_header_4();
            int_set_header_5();

            hdr.ipv4.totalLen = hdr.ipv4.totalLen + 24;

            hdr.udp.len = hdr.udp.len + 24;
            hdr.int_shim.len = hdr.int_shim.len + 6;

            int_hop_cnt_increment();
        }
    }
}



control Int_sink(inout headers hdr, inout metadata meta, inout standard_metadata_t standard_metadata) {
    action fill_influx() {
        hdr.influx.srcAddr = hdr.ipv4.srcAddr;
        hdr.influx.dstAddr = hdr.ipv4.dstAddr;
        hdr.influx.ndk_tstamp_h = meta.ingress_tstamp_system_h;
        hdr.influx.ndk_tstamp_l = meta.ingress_tstamp_system_l;
        hdr.influx.delay_h = meta.ingress_tstamp_system_h;
        hdr.influx.delay_l = meta.ingress_tstamp_system_l;
        hdr.influx.hop_meta_len = hdr.int_header.hop_metadata_len;
        hdr.influx.meta_len = hdr.int_shim.len - 3;

        hdr.ethernet.etherType = 0xffff;
        hdr.ipv4.setInvalid();
        hdr.int_shim.setInvalid();
        hdr.int_header.setInvalid();
    }

    action remove_tcp() {
        hdr.influx.setValid();
        hdr.influx.seq = hdr.tcp.seqNum;
        hdr.influx.ingress_port_id = hdr.tcp.srcPort;
        hdr.influx.egress_port_id = hdr.tcp.dstPort;
        hdr.tcp.setInvalid();
    }

    action remove_udp() {
        hdr.influx.setValid();
        hdr.influx.seq = 0;
        hdr.influx.ingress_port_id = hdr.udp.srcPort;
        hdr.influx.egress_port_id = hdr.udp.dstPort;
        hdr.udp.setInvalid();
    }

    action drop() {
        mark_to_drop(standard_metadata);
    }

    apply {
        if (SINK_ENABLE) {
            if (hdr.tcp.isValid())
                remove_tcp();
            else if (hdr.udp.isValid())
                remove_udp();
            else
                drop();

            fill_influx();
        }
    }
}



control ingress(inout headers hdr, inout metadata meta, inout standard_metadata_t ig_intr_md) {
    action ip_checksum_sub(bit<16> value) {
        hdr.ipv4.checksum = ~hdr.ipv4.checksum;
        if (hdr.ipv4.checksum < value)
            hdr.ipv4.checksum = hdr.ipv4.checksum - 1;
        hdr.ipv4.checksum = hdr.ipv4.checksum - value;
        hdr.ipv4.checksum = ~hdr.ipv4.checksum;
    }

    action ip_checksum_add(bit<16> value) {
        hdr.ipv4.checksum = ~hdr.ipv4.checksum;
        hdr.ipv4.checksum = hdr.ipv4.checksum + value;
        if (hdr.ipv4.checksum < value)
            hdr.ipv4.checksum = hdr.ipv4.checksum + 1;
        hdr.ipv4.checksum = ~hdr.ipv4.checksum;
    }

    apply {
        if (!hdr.udp.isValid() && !hdr.tcp.isValid())
            exit;

        ip_checksum_sub(hdr.ipv4.totalLen);
        ip_checksum_sub(hdr.ipv4.version ++ hdr.ipv4.ihl ++ hdr.ipv4.dscp ++ hdr.ipv4.ecn);

        Int_source.apply(hdr, meta, ig_intr_md);
        Int_transit.apply(hdr, meta, ig_intr_md);

        ip_checksum_add(hdr.ipv4.totalLen);
        ip_checksum_add(hdr.ipv4.version ++ hdr.ipv4.ihl ++ hdr.ipv4.dscp ++ hdr.ipv4.ecn);

        Int_sink.apply(hdr, meta, ig_intr_md);
   }
}

control egress(inout headers hdr, inout metadata meta, inout standard_metadata_t eg_intr_md) {
    apply {
        hdr.int_egress_tstamp.egress_tstamp_h = meta.egress_tstamp_system_h;
        hdr.int_egress_tstamp.egress_tstamp_l = meta.egress_tstamp_system_l;
    }
}

V1Switch(ParserImpl(), verifyChecksum(), ingress(), egress(), computeChecksum(), DeparserImpl()) main;

