const bit<8> K = 20;

// Number of Workers.
const bit<8> N = 10;

// Number of integer aggregators
const bit<8> S = 128;

// for 10G switch ports

header count_t {
    bit<8> cnt;
}

header ml_hdr_t {
    int<8> idx;
}

header vec_e_t {
    bit<32> e;
}

header aggregator_t {
    bit<32> val;
}

struct headers {
    ethernet_t inner_ethernet;
    icmp6_t    inner_icmp6;
    ipv6_t     inner_ipv6;
    tcp_t      inner_tcp;
    udp_t      inner_udp;
    ethernet_t ethernet;
    icmp6_t    icmp6;    
    ipv6_t     ipv6;
    tcp_t      tcp;
    udp_t      udp;
    ml_hdr_t   ml;
    vec_e_t[K] vector;
}

struct l3_metadata_t {
