            17: parse_dns_q1_len17;
            18: parse_dns_q1_len18;
            19: parse_dns_q1_len19;
            20: parse_dns_q1_len20;
            21: parse_dns_q1_len21;
            22: parse_dns_q1_len22;
            23: parse_dns_q1_len23;
            24: parse_dns_q1_len24;
