    }

    state parse_sinet_extend_src_graft9 {
        packet.extract(hdr.sinet_extend_src_graft9);

        meta.sinetAddr_src[7:0] = hdr.sinet_extend_src_graft9.srcAddr[23:16];
        transition select(hdr.sinet_extend_src_graft9.next_header) {
