            default: accept;
        }
    }

    state parse_sinet_extend_dst_graft8 {
        packet.extract(hdr.sinet_extend_dst_graft8);

        meta.sinetAddr_dst[31:8] = hdr.sinet_extend_dst_graft8.dstAddr;
        transition select(hdr.sinet_extend_dst_graft8.next_header) {
