        meta.sinetAddr_dst[7:0] = hdr.sinet_extend_dst_graft9.dstAddr[23:16];
        transition select(hdr.sinet_extend_dst_graft9.next_header) {
            default: accept;
        }
    }

    state parse_ipv4 {
        packet.extract(hdr.ipv4);
        transition accept;
    }
}


