         /* removing header */

        hdr.inner1_tcp.setInvalid();
        hdr.inner1_ipv4.setInvalid();
        hdr.gtp.setInvalid();
        hdr.inner_udp.setInvalid();
        hdr.inner_ipv4.setInvalid();
        hdr.inner_ethernet.setInvalid();
        hdr.vxlan.setInvalid();
        hdr.udp.setInvalid();
