        hdr.inn_ipv4.ttl              		    = meta.meta_inner1_ipv4.ttl             ;
        hdr.inn_ipv4.protocol         		    = IPPROTO_TCP                           ;
        hdr.inn_ipv4.hdrChecksum      		    = meta.meta_inner1_ipv4.hdrChecksum     ;
