        hdr.ipv4_outer.srcAddr        		    = GW_IP                                 ;
        hdr.ipv4_outer.dstAddr       		    = DCGW_IP_UL                            ;

        hdr.outer_udp.srcPort 	                    = meta.meta_udp.srcPort                 ;
        hdr.outer_udp.dstPort 			    = meta.meta_udp.dstPort                 ;
        hdr.outer_udp.plength 			    = meta.meta_udp.plength - 36            ;
