        bool dummy;
    #endif

    bit<16> size_growth;
    bit<16> size_loss;
    bit<8>  postprocessing;

    bit<32> parsed_bytes;
    bit<32> truncated_to;
}

parser MyParser(packet_in pkt,
                out headers hdr,
                inout metadata meta,
                inout standard_metadata_t standard_metadata) {

    state start {
        meta.size_growth = 0;
        meta.size_loss = 0;
        meta.postprocessing = SKIP;
        meta.parsed_bytes = 0;
        meta.truncated_to = 0;

        #ifndef USE_DUMMY_PARSER
            transition parse_ethernet;
        #else
            transition select(meta.dummy || (!meta.dummy) ){
                true : parse_ethernet;
                default : dummy;
            }
        #endif
    }

    #ifdef USE_DUMMY_PARSER
        #include "dummy.p4"
    #endif

    state parse_ethernet {
        pkt.extract(hdr.ethernet);
        meta.parsed_bytes = meta.parsed_bytes + 14;
        transition select(hdr.ethernet.etherType) {
            16w0x800: parse_ipv4;
            default: accept;
        }
    }

    state parse_ipv4 {
        pkt.extract(hdr.ipv4);
        meta.parsed_bytes = meta.parsed_bytes + 20;
        transition select(hdr.ipv4.protocol){
            17 : parse_udp;
            6  : parse_tcp;
            default: chain_ipv4_raw;
        }
    }

    state parse_udp{
        pkt.extract(hdr.udp);
        meta.parsed_bytes = meta.parsed_bytes + 8;
        transition chain_ipv4_udp;
    }

    state parse_tcp{
        pkt.extract(hdr.tcp);
        meta.parsed_bytes = meta.parsed_bytes + 20;
        transition chain_ipv4_tcp;
    }

    #include "a_chains.p4"

    #ifndef CHAIN_IPV4_UDP
    state chain_ipv4_udp{
        transition accept;
    }
    #endif

    #ifndef CHAIN_IPV4_TCP
    state chain_ipv4_tcp{
        transition accept;
    }
    #endif

    #ifndef CHAIN_IPV4_RAW
    state chain_ipv4_raw{
        transition accept;
    }
    #endif

}


