parser MyParser(packet_in pkt,
                out headers hdr,
                inout metadata meta,
                inout standard_metadata_t standard_metadata) {

    state start {
        meta.size_growth = 0;
        meta.size_loss = 0;
        meta.postprocessing = SKIP;
        meta.parsed_bytes = 0;
        meta.truncated_to = 0;

        #ifndef USE_DUMMY_PARSER
            transition parse_ethernet;
        #else
            transition select(meta.dummy || (!meta.dummy) ){
                true : parse_ethernet;
                default : dummy;
            }
        #endif
    }

    #ifdef USE_DUMMY_PARSER

    #endif

    state parse_ethernet {
        pkt.extract(hdr.ethernet);
        meta.parsed_bytes = meta.parsed_bytes + 14;
        transition select(hdr.ethernet.etherType) {
            16w0x800: parse_ipv4;
            default: accept;
        }
    }

    state parse_ipv4 {
        pkt.extract(hdr.ipv4);
        meta.parsed_bytes = meta.parsed_bytes + 20;
        transition select(hdr.ipv4.protocol){
            17 : parse_udp;
            6  : parse_tcp;
            default: chain_ipv4_raw;
        }
    }

    state parse_udp{
        pkt.extract(hdr.udp);
        meta.parsed_bytes = meta.parsed_bytes + 8;
        transition chain_ipv4_udp;
    }

    state parse_tcp{
        pkt.extract(hdr.tcp);
        meta.parsed_bytes = meta.parsed_bytes + 20;
        transition chain_ipv4_tcp;
    }


state parse_genhdr_uid1{
	pkt.extract(hdr.genhdr_uid1);
	transition accept;
}

state parse_genhdr_uid3{
	pkt.extract(hdr.genhdr_uid3);
	transition accept;
}

state check_uid3{
	transition select(hdr.udp.dstPort,hdr.udp.len){

		(5555,16) : parse_genhdr_uid1;
		default: check_uid4;
	}	
}

state check_uid4{
	transition select(hdr.udp.srcPort,hdr.udp.len){

		(5555,16) : parse_genhdr_uid3;
		default: accept;
	}	
}


#define CHAIN_IPV4_UDP
state chain_ipv4_udp{
	transition check_uid3;
}


    #ifndef CHAIN_IPV4_UDP
    state chain_ipv4_udp{
        transition accept;
    }
    #endif

    #ifndef CHAIN_IPV4_TCP
    state chain_ipv4_tcp{
        transition accept;
    }
    #endif

    #ifndef CHAIN_IPV4_RAW
    state chain_ipv4_raw{
        transition accept;
    }
    #endif

}


