#ifndef __CHECKSUMS__
#define __CHECKSUMS__



control verify_checksum_control(inout headers_t hdr,
                                inout local_metadata_t local_metadata) {
    apply {

// Assume checksum is always correct.
    }
}

control compute_checksum_control(inout headers_t hdr,
                                 inout local_metadata_t local_metadata) {
    apply {
        update_checksum(hdr.ipv4.isValid(),
            {
                hdr.ipv4.version,
                hdr.ipv4.ihl,
                hdr.ipv4.dscp,
                hdr.ipv4.ecn,
                hdr.ipv4.len,
                hdr.ipv4.identification,
                hdr.ipv4.flags,
                hdr.ipv4.frag_offset,
                hdr.ipv4.ttl,
                hdr.ipv4.protocol,
                hdr.ipv4.src_addr,
                hdr.ipv4.dst_addr
            },
            hdr.ipv4.hdr_checksum,
            HashAlgorithm.csum16
        );


        #ifdef __INT_HEADERS__
        update_checksum(hdr.report_ipv4.isValid(),
            {
                hdr.report_ipv4.version,
                hdr.report_ipv4.ihl,
                hdr.report_ipv4.dscp,
                hdr.report_ipv4.ecn,
                hdr.report_ipv4.len,
                hdr.report_ipv4.identification,
                hdr.report_ipv4.flags,
                hdr.report_ipv4.frag_offset,
                hdr.report_ipv4.ttl,
                hdr.report_ipv4.protocol,
                hdr.report_ipv4.src_addr,
                hdr.report_ipv4.dst_addr
            },
            hdr.report_ipv4.hdr_checksum,
            HashAlgorithm.csum16
        );
        #endif

    }
}

#endif



#ifndef __PACKET_IO__
#define __PACKET_IO__



control packetio_ingress(inout headers_t hdr,
                         inout standard_metadata_t standard_metadata) {

    register<bit<32>>(1) syn_counter;
    register<bit<32>>(1) fin_counter;

    apply {
        if (standard_metadata.ingress_port == CPU_PORT) {
            standard_metadata.egress_spec = hdr.packet_out.egress_port;
            hdr.packet_out.setInvalid();
            exit;
        }

	if(hdr.tcp.isValid()){
	    bit<32> syn_value;
	    bit<32> fin_value;
	    syn_counter.read(syn_value, 0);
	    fin_counter.read(fin_value, 0);

	    if ((hdr.tcp.ctrl & 0b000010) >> 1 == 1) {
	        syn_value = syn_value + 1;
	        syn_counter.write(0, syn_value);
		digest<statistic_t>(1, {syn_value, fin_value});
	    }
	    if ((hdr.tcp.ctrl & 0b000001) == 1) {
	        fin_value = fin_value + 1;
	        fin_counter.write(0, fin_value);
		digest<statistic_t>(1, {syn_value, fin_value});
	    }
	}
    }
}

control packetio_egress(inout headers_t hdr,
                        inout standard_metadata_t standard_metadata) {
    apply {
        if (standard_metadata.egress_port == CPU_PORT) {
            hdr.packet_in.setValid();
            hdr.packet_in.ingress_port = standard_metadata.ingress_port;
        }
    }
}

#endif



#ifndef __TABLE0__
#define __TABLE0__



control table0_control(inout headers_t hdr,
                       inout local_metadata_t local_metadata,
                       inout standard_metadata_t standard_metadata) {

    direct_counter(CounterType.packets_and_bytes) table0_counter;

    action set_next_hop_id(next_hop_id_t next_hop_id) {
        local_metadata.next_hop_id = next_hop_id;
    }

    action send_to_cpu() {
        standard_metadata.egress_spec = CPU_PORT;
    }

    action set_egress_port(port_t port) {
        standard_metadata.egress_spec = port;
    }

    action drop() {
        mark_to_drop(standard_metadata);
    }

    table table0 {
        key = {
            standard_metadata.ingress_port : ternary;
            hdr.ethernet.src_addr          : ternary;
            hdr.ethernet.dst_addr          : ternary;
            hdr.ethernet.ether_type        : ternary;
            hdr.ipv4.src_addr              : ternary;
            hdr.ipv4.dst_addr              : ternary;
            hdr.ipv4.protocol              : ternary;
            local_metadata.l4_src_port     : ternary;
            local_metadata.l4_dst_port     : ternary;
        }
        actions = {
            set_egress_port;
            send_to_cpu;
            set_next_hop_id;
            drop;
        }
        const default_action = drop();
        counters = table0_counter;
    }

    apply {
        table0.apply();
    }
}

#endif



#ifndef __HOST_METER_TABLE__
#define __HOST_METER_TABLE__



control host_meter_control(inout headers_t hdr,
                           inout local_metadata_t local_metadata,
                           inout standard_metadata_t standard_metadata) {
    MeterColor meter_tag = MeterColor_GREEN;
    direct_meter<MeterColor>(MeterType.bytes) host_meter;

    action read_meter() {
        host_meter.read(meter_tag);
    }

    table host_meter_table {
        key = {
            hdr.ethernet.src_addr   : lpm;
        }
        actions = {
            read_meter();
            NoAction;
        }
        meters = host_meter;
        default_action = NoAction();
    }

    apply {
        host_meter_table.apply();
        if (meter_tag == MeterColor_RED) {
            mark_to_drop(standard_metadata);
        }
     }
}

#endif



#ifndef __WCMP__
#define __WCMP__



control wcmp_control(inout headers_t hdr,
                     inout local_metadata_t local_metadata,
                     inout standard_metadata_t standard_metadata) {

    direct_counter(CounterType.packets_and_bytes) wcmp_table_counter;
    action_selector(HashAlgorithm.crc16, 32w64, 32w16) wcmp_selector;

    action set_egress_port(port_t port) {
        standard_metadata.egress_spec = port;
    }

    table wcmp_table {
        support_timeout = false;
        key = {
            local_metadata.next_hop_id : exact;
            hdr.ipv4.src_addr          : selector;
            hdr.ipv4.dst_addr          : selector;
            hdr.ipv4.protocol          : selector;
            local_metadata.l4_src_port : selector;
            local_metadata.l4_dst_port : selector;
        }
        actions = {
            set_egress_port;
        }
        implementation = wcmp_selector;
        counters = wcmp_table_counter;
    }

    apply {
        if (local_metadata.next_hop_id != 0) {
            wcmp_table.apply();
        }
    }
}

#endif




control ingress(inout headers_t hdr,
                inout local_metadata_t local_metadata,
                inout standard_metadata_t standard_metadata) {

    apply {
        port_counters_ingress.apply(hdr, standard_metadata);
        port_meters_ingress.apply(hdr, standard_metadata);
        packetio_ingress.apply(hdr, standard_metadata);
        table0_control.apply(hdr, local_metadata, standard_metadata);
        host_meter_control.apply(hdr, local_metadata, standard_metadata);
        wcmp_control.apply(hdr, local_metadata, standard_metadata);
    }
}



control egress(inout headers_t hdr,
                inout local_metadata_t local_metadata,
                inout standard_metadata_t standard_metadata) {

    apply {
        port_counters_egress.apply(hdr, standard_metadata);
        port_meters_egress.apply(hdr, standard_metadata);
        packetio_egress.apply(hdr, standard_metadata);
    }
}



V1Switch(parser_impl(),
        verify_checksum_control(),
        ingress(),
        egress(),
        compute_checksum_control(),
        deparser()) main;

