	    6            : parse_ipv6;
	    default : accept;
	}
    }
    state parse_ipv6 {
        pkt.extract(hdr.ipv6);
        transition select(hdr.ipv6.nh) {
	    1            : parse_icmp;
	    2            : parse_icmp6;
	    3            : parse_tcp;
	    4            : parse_udp;
            5            : parse_ipv4;
	    default : accept;
        }
    }
    state parse_ipv4 {
        pkt.extract(hdr.ipv4);
        transition select(hdr.ipv4.protocol) {
	    1            : parse_icmp;
	    2            : parse_icmp6;
	    3            : parse_tcp;
	    4            : parse_udp;
	    default : accept;
        }
    }
    state parse_icmp{
	pkt.extract(hdr.icmp);
	transition select(hdr.icmp.code) {
	    2            : parse_icmp6;
	    3            : parse_tcp;
	    4            : parse_udp;
	    default : accept;
