struct headers {
    ethernet_t  ethernet;
    custom_t    custom;
    ipv4_t      ipv4;
    tcp_t       tcp;
    udp_t	udp;
}

/*************************************************************************
*********************** P A R S E R  ***********************************
*************************************************************************/

parser MyParser(packet_in packet,
                out headers hdr,
                inout metadata meta,
                inout standard_metadata_t standard_metadata) {

    state start {
        transition parse_ethernet;
    }

    state parse_ethernet {
        packet.extract(hdr.ethernet);
        log_msg("Protocol: {}", {hdr.ethernet.etherType}); //custom_header
        transition select(hdr.ethernet.etherType) {
            TYPE_IPV4: parse_ipv4;
            1234: infer;  //custom_header
            default: accept;
        }
    }

   // parse different types of packets ARP, ICMP etc.
   state parse_ipv4 {
        packet.extract(hdr.ipv4);
        transition select(hdr.ipv4.protocol) {
            6: parse_tcp;
	    17: parse_udp;
            default: accept;
    }
    }
    state parse_tcp {
        packet.extract(hdr.tcp);
        transition accept;
    }

    state parse_udp {
        packet.extract(hdr.udp);
        transition accept;
    }


   state infer { //custom_header
       packet.extract(hdr.custom);
       transition parse_ipv4;	
    }

}

