    action compute_shift(in bit<8> packets, out bit<8> bit_shifting) {
        if (packets == 0) {
            bit_shifting = 0;
        } else if (packets <= 2) {
            bit_shifting = 1;
        } else if (packets <= 4) {
            bit_shifting = 2;
        } else if (packets <= 8) {
            bit_shifting = 3;
        } else if (packets <= 16) {
            bit_shifting = 4;
        } else if (packets <= 32) {
            bit_shifting = 5;
        } else if (packets <= 64) {
            bit_shifting = 6;
        } else {
            bit_shifting = 7;
        }
    }



    action calculate_mean(in bit<32> value, in bit<8> packets, out bit<32> mean) {
        bit<8> bit_shifting;
        if (packets == 1) {
            mean = value;
        } else {
            // Calculate bit length of packets
            compute_shift(packets, bit_shifting);
            // Subtract 1 from bit length for correct shift amount
            mean = value >> bit_shifting;
        }
    }





