}

control ComputeChecksumImpl(inout headers_t hdr,
                            inout metadata meta) {
    apply {
        update_checksum(hdr.ipv4.isValid(), {
                hdr.ipv4.version,
                hdr.ipv4.ihl,
                hdr.ipv4.dscp,
                hdr.ipv4.ecn,
                hdr.ipv4.totalLen,
                hdr.ipv4.identification,
