                hdr.ipv4.ttl,
                hdr.ipv4.protocol,
                hdr.ipv4.srcAddr,
                hdr.ipv4.dstAddr
            }, hdr.ipv4.hdrChecksum, HashAlgorithm.csum16);

       }
}


control Forward(inout headers_t hdr,
                            inout metadata meta,
                              inout standard_metadata_t standard_metadata) {



    action drop() {
        mark_to_drop(standard_metadata);
    }

    action ipv4_forward(macAddr_t dstAddr, egressSpec_t port) {
        standard_metadata.egress_spec = port;
        hdr.ethernet.srcAddr = hdr.ethernet.dstAddr;
        hdr.ethernet.dstAddr = dstAddr;
        hdr.ipv4.ttl = hdr.ipv4.ttl - 1;
    }

    table fwd_tb {
        key = {
            hdr.ipv4.dstAddr : lpm;
        }
        actions = {
            ipv4_forward;
            drop;
            NoAction;
        }
        default_action = drop;
    }

    apply {
        if (hdr.ipv4.isValid()) {
            fwd_tb.apply();
        }
    }
}


control Monitor_Packet(inout headers_t hdr,
                       inout metadata meta,
                       inout standard_metadata_t standard_metadata) {


    action mark_to_monitor(){
        clone(CloneType.I2E, REPORT_MIRROR_SESSION_ID);
    }

    action send_to_cpu(){
        standard_metadata.egress_spec = CPU_PORT;
        hdr.packet_in.setValid();
        hdr.packet_in.ingress_port = standard_metadata.ingress_port;
        hdr.packet_in._padding = 0;
    }


    action send_digest(){
        digest<monitor_digest>(1,
            {standard_metadata.ingress_port,
             0,
             hdr.ipv4.srcAddr,
             hdr.ipv4.dstAddr,
             hdr.ipv4.protocol,
             hdr.l4_ports.l4_srcPort,
             hdr.l4_ports.l4_dstPort,
             hdr.digest_count.tcp_pkt_num,
             hdr.digest_count.tcp_syn_num,
             hdr.digest_count.tcp_rst_num,
             hdr.digest_count.udp_pkt_num,
             hdr.digest_count.pkt_num,
             hdr.digest_count.unique_port_pairs_num
             });
    }

    table packet_check {
        key = {
            hdr.l4_ports.l4_dstPort: exact;

        }
        actions = {
            mark_to_monitor;
            send_to_cpu;
            send_digest;
            NoAction;
        }
        default_action = NoAction;
    }


    apply {
        if (hdr.ipv4.isValid()) {

            packet_check.apply();
        }
    }
}


control Clone_Type(inout headers_t hdr,
                     inout metadata meta,
                     inout standard_metadata_t standard_metadata) {



    action clone_packet(macAddr_t mac,
                        ip4Addr_t ip,
                        l4_port_t udp_port){
        hdr.rep_ethernet.setValid();
        hdr.rep_ipv4.setValid();
        hdr.rep_l4_ports.setValid();
        hdr.rep_udp.setValid();

        hdr.rep_ethernet.srcAddr = SRC_MAC;
        hdr.rep_ethernet.dstAddr = mac;
        hdr.rep_ethernet.etherType = TYPE_IPV4;

        hdr.rep_ipv4.version = 4;
        hdr.rep_ipv4.ihl = 5;
        hdr.rep_ipv4.dscp = 0;
        hdr.rep_ipv4.ecn = 0;
        hdr.rep_ipv4.identification = 0;
        hdr.rep_ipv4.flags = 0;
        hdr.rep_ipv4.fragOffset = 0;
        hdr.rep_ipv4.ttl = 0xFF;
        hdr.rep_ipv4.protocol = TYPE_UDP;
        hdr.rep_ipv4.srcAddr = SRC_IP;
        hdr.rep_ipv4.dstAddr = ip;

        hdr.rep_l4_ports.l4_srcPort = UDP_SRC;
        hdr.rep_l4_ports.l4_dstPort = udp_port;




        hdr.rep_udp.len =
            UDP_LEN +
            ETH_LEN +

// original packet ethernet
            hdr.ipv4.totalLen;

        hdr.rep_ipv4.totalLen =
            hdr.rep_udp.len +
            IPV4_LEN;
    }


    action key_field_summary(macAddr_t mac,
                             ip4Addr_t ip,
                             l4_port_t udp_port){

        clone_packet(mac, ip, udp_port);

        hdr.sum.setValid();
        hdr.sum.l3_srcAddr = hdr.ipv4.srcAddr;
        hdr.sum.l3_dstAddr = hdr.ipv4.dstAddr;
        hdr.sum.l3_proto = hdr.ipv4.protocol;
        hdr.sum.l4_srcPort = hdr.l4_ports.l4_srcPort;
        hdr.sum.l4_dstPort = hdr.l4_ports.l4_dstPort;
        hdr.sum.tcp_pkt_num = hdr.digest_count.tcp_pkt_num;
        hdr.sum.tcp_syn_num = hdr.digest_count.tcp_syn_num;
        hdr.sum.tcp_rst_num = hdr.digest_count.tcp_rst_num;
        hdr.sum.udp_pkt_num = hdr.digest_count.udp_pkt_num;
        hdr.sum.pkt_num = hdr.digest_count.pkt_num;
        hdr.sum.unique_port_pairs_num = hdr.digest_count.unique_port_pairs_num;

        hdr.rep_udp.len = hdr.rep_udp.len + KFS_LEN;
        hdr.rep_ipv4.totalLen = hdr.rep_ipv4.totalLen + KFS_LEN;
    }


    table clone_type_tb {
        key = {
            hdr.l4_ports.l4_dstPort: exact;
        }
        actions = {
            clone_packet;
            key_field_summary;
            NoAction;
        }
        default_action = NoAction;
    }

    apply {
        if(hdr.tcp.isValid()){
            meta.kf.l4_flag = hdr.tcp.ctrl;
        }else{
            meta.kf.l4_flag = 0;
        }

        if (standard_metadata.instance_type == PKT_INSTANCE_TYPE_INGRESS_CLONE) {


/* send to ML */
            clone_type_tb.apply();

        }


        if(hdr.rep_ipv4.isValid() && meta.ct.is_summary){
            if(hdr.rep_ipv4.totalLen >= MAX_IPV4){
                hdr.ethernet.setInvalid();
                hdr.ipv4.setInvalid();
                hdr.udp.setInvalid();

                hdr.rep_ipv4.totalLen =
                    hdr.rep_ipv4.totalLen-ETH_LEN-IPV4_LEN-UDP_LEN;

                hdr.rep_udp.len =
                    hdr.rep_udp.len-ETH_LEN-IPV4_LEN-UDP_LEN;
            }
        }
    }
}


control Port_counters_ingress(inout headers_t hdr,
                              inout standard_metadata_t standard_metadata) {

    counter(MAX_PORTS, CounterType.packets) ingress_port_counter;

    apply {
        ingress_port_counter.count((bit<32>) standard_metadata.ingress_port);
    }
}

control Port_counters_egress(inout headers_t hdr,
                             inout standard_metadata_t standard_metadata) {

    counter(MAX_PORTS, CounterType.packets) egress_port_counter;

    apply {
        egress_port_counter.count((bit<32>) standard_metadata.egress_port);
    }
}



control IngressImpl(inout headers_t hdr,
                    inout metadata meta,
                    inout standard_metadata_t standard_metadata)
{

    Port_counters_ingress() port_counters_ingress;
    Forward() forward;
    Monitor_Packet() mon_packet;


// Bloom filter

    register<bit<BLOOM_FILTER_BIT_WIDTH>>(BLOOM_FILTER_ENTRIES) bloom_filter;
    bit<32> reg_pos;
    bit<1> reg_val_one;


    action compute_hashes(ip4Addr_t ipAddr1, ip4Addr_t ipAddr2, bit<16> port1, bit<16> port2,  bit<8>protocol){

//Get register position
       hash(reg_pos, HashAlgorithm.crc32, (bit<32>)0, {ipAddr1,
                                                           ipAddr2,
                                                           port1,
                                                           port2,
                                                           protocol},
                                                           (bit<32>)BLOOM_FILTER_ENTRIES);
    }

    apply{

        port_counters_ingress.apply(hdr, standard_metadata);


// Packet Count
        pkt_counter.read(hdr.digest_count.pkt_num, meta.pkt_num);
        tcp_pkt_counter.read(hdr.digest_count.tcp_pkt_num, meta.tcp_pkt_num);
        udp_pkt_counter.read(hdr.digest_count.udp_pkt_num, meta.udp_pkt_num);
        tcp_syn_counter.read(hdr.digest_count.tcp_syn_num, meta.tcp_syn_num);
        tcp_rst_counter.read(hdr.digest_count.tcp_rst_num, meta.tcp_rst_num);

// port counter
        unique_port_pairs_counter.read(hdr.digest_count.unique_port_pairs_num, meta.unique_port_pairs_num);

        hdr.digest_count.pkt_num = hdr.digest_count.pkt_num + 1;
        pkt_counter.write(meta.pkt_num, hdr.digest_count.pkt_num);

            if (hdr.tcp.isValid()) {
                compute_hashes(hdr.ipv4.srcAddr, hdr.ipv4.dstAddr, hdr.l4_ports.l4_srcPort, hdr.l4_ports.l4_dstPort, hdr.ipv4.protocol);

// bloom filter
                bloom_filter.read(reg_val_one, reg_pos);
                if (reg_val_one != 1){
                    hdr.digest_count.unique_port_pairs_num = hdr.digest_count.unique_port_pairs_num + 1;
                    unique_port_pairs_counter.write(meta.unique_port_pairs_num, hdr.digest_count.unique_port_pairs_num);

                    bloom_filter.write(reg_pos, 1);
                }



                hdr.digest_count.tcp_pkt_num = hdr.digest_count.tcp_pkt_num + 1;
                tcp_pkt_counter.write(meta.tcp_pkt_num, hdr.digest_count.tcp_pkt_num);

                if (hdr.tcp.ctrl == SYN) {
                    hdr.digest_count.tcp_syn_num = hdr.digest_count.tcp_syn_num + 1;
                    tcp_syn_counter.write(meta.tcp_syn_num, hdr.digest_count.tcp_syn_num);
                }

                if (hdr.tcp.ctrl == RST) {
                    hdr.digest_count.tcp_rst_num = hdr.digest_count.tcp_rst_num + 1;
                    tcp_rst_counter.write(meta.tcp_rst_num, hdr.digest_count.tcp_rst_num);
                }
            }
            if (hdr.udp.isValid()) {
                hdr.digest_count.udp_pkt_num = hdr.digest_count.udp_pkt_num + 1;
                udp_pkt_counter.write(meta.udp_pkt_num, hdr.digest_count.udp_pkt_num);
            }





// count time
            bit<2> time_flag;
            TIME_FLAG.read(time_flag, 0);
            time_flag = 0;
            TIME_FLAG.write(0, time_flag);


            time_t last_time;
            time_t cur_time = standard_metadata.ingress_global_timestamp;
            time_t delta_time;



            last_time_reg.read(last_time, (bit<32>)standard_metadata.ingress_port);
            delta_time = cur_time - last_time;


            if (hdr.digest_count.pkt_num > 1){
                if (delta_time > 1000000) {
                    delta_time = 0;
                    last_time_reg.write((bit<32>)standard_metadata.ingress_port, cur_time);
                    time_flag = 2;
                    TIME_FLAG.write(0, time_flag);

                    mon_packet.apply(hdr, meta, standard_metadata);

                    pkt_counter.write(0, 0);
                    tcp_pkt_counter.write(0, 0);
                    udp_pkt_counter.write(0, 0);
                    tcp_syn_counter.write(0, 0);
                    tcp_rst_counter.write(0, 0);
                    bloom_filter.write(0,0);
                    unique_port_pairs_counter.write(0, 0);
                }
            }

            forward.apply(hdr, meta, standard_metadata);



    }
}

control EgressImpl(inout headers_t hdr,
                   inout metadata meta,
                   inout standard_metadata_t standard_metadata)
{

    Port_counters_egress() port_counters_egress;
    Clone_Type() clone_type;

    apply{
        port_counters_egress.apply(hdr, standard_metadata);
        bit<2> time_flag;
        TIME_FLAG.read(time_flag, 0);

        if(time_flag == 2){
            clone_type.apply(hdr, meta, standard_metadata);
        }
        time_flag = 0;
        TIME_FLAG.write(0, time_flag);
    }
}

V1Switch(
    ParserImpl(),
    VerifyChecksumImpl(),
    IngressImpl(),
    EgressImpl(),
    ComputeChecksumImpl(),
    DeparserImpl()
) main;

