/* -*- P4_16 -*- */
#include <core.p4>
#include <v1model.p4>

#include "int.p4"

/*
 * This P4 code implements a simple switch to count number of packets for each source IP.
 * The counter of an IP will be reported via in-band network telemetry 
 *  not for every single packet, but each 128 packets. 
 *  After being reported, the counter is reseted to 0.
 *
 * The implementation uses a simple bloom filter to check 
 *  if a comming packet is a part of an already initialized counter.
 *
 * Created on: Nov 07, 2023
 *			by: Huu Nghia
 */

/*************************************************************************
 *********************** H E A D E R S  ***********************************
 *************************************************************************/

// number of counters
#define BLOOM_FILTER_ENTRIES 4096
// bit size of a counter: 8bit == 255 packets max
#define BLOOM_FILTER_BIT_WIDTH 8
//frequency of report: a report each 128 packets
#define REPORT_FREQ 128

typedef bit<9>  egressSpec_t;
typedef bit<48> macAddr_t;
typedef bit<32> ip4Addr_t;

header ethernet_t {
	macAddr_t dstAddr;
	macAddr_t srcAddr;
	bit<16>	etherType;
}

header ipv4_t {
	bit<4>	 version;
	bit<4>	 ihl;
	bit<6>	 dscp;
	bit<2>	 ecn;
	bit<16>	totalLen;
	bit<16>	identification;
	bit<3>	 flags;
	bit<13>	fragOffset;
	bit<8>	 ttl;
	bit<8>	 protocol;
	bit<16>	hdrChecksum;
	ip4Addr_t srcAddr;
	ip4Addr_t dstAddr;
}

header tcp_t{
	bit<16> srcPort;
	bit<16> dstPort;
	bit<32> seqNo;
	bit<32> ackNo;
	bit<4>  dataOffset;
	bit<4>  res;
	bit<1>  cwr;
	bit<1>  ece;
	bit<1>  urg;
	bit<1>  ack;
	bit<1>  psh;
	bit<1>  rst;
	bit<1>  syn;
	bit<1>  fin;
	bit<16> window;
	bit<16> checksum;
	bit<16> urgentPtr;
}


#define MAX_TCP_OPTION_WORD 10
header tcp_option_t{
	bit<32> data;
}

header udp_t {
	bit<16> srcPort;
	bit<16> dstPort;
	bit<16> length;
	bit<16> checksum;
}

struct metadata {
	/* empty */
	int_metadata _int;
}

struct headers {
	ethernet_t  ethernet;
	ipv4_t		ipv4;
	udp_t		 udp;
	tcp_t		 tcp;

	tcp_option_t[MAX_TCP_OPTION_WORD] tcp_opt;
	int_headers _int;
}

/*************************************************************************
 *********************** P A R S E R  ***********************************
 *************************************************************************/

parser MyParser(packet_in packet,
		out headers hdr,
		inout metadata meta,
		inout standard_metadata_t standard_metadata) {

	//local variable to count TCP options in number of words
	bit<4> tcp_opt_cnt = 0;

	state start {
		transition parse_ethernet;
	}

	state parse_ethernet {
		packet.extract(hdr.ethernet);
		transition select(hdr.ethernet.etherType) {
			0x800  : parse_ipv4;
			default: accept;
		}
	}
	state parse_ipv4 {
		packet.extract(hdr.ipv4);
		transition select(hdr.ipv4.protocol){
			0x006  : parse_tcp;
			0x011  : parse_udp;
			default: accept;
		}
	}

	state parse_tcp {
		packet.extract(hdr.tcp);

		 //HN: jump over TCP options
		tcp_opt_cnt = hdr.tcp.dataOffset;
		//exclude 5 words (=20 bytes) of the fixed tcp header that is defined in tcp_t
		if( tcp_opt_cnt > 5 )
			tcp_opt_cnt = tcp_opt_cnt - 5;
		else
			tcp_opt_cnt = 0;
		log_msg("====TCP data offset = {}", {tcp_opt_cnt});
		transition select( tcp_opt_cnt ){
			0		 : parse_int_over_tcp;
			default : parse_tcp_option;
		}
	}

	state parse_int_over_tcp {
		int_parser.apply( packet, hdr.ipv4.dscp, hdr.ipv4.srcAddr, hdr.tcp.srcPort, hdr.ipv4.dstAddr, hdr.tcp.dstPort, hdr._int, meta._int, standard_metadata, false );
		transition accept;
	}

	state parse_tcp_option {
		packet.extract( hdr.tcp_opt.next );
		tcp_opt_cnt = tcp_opt_cnt - 1;
		transition select( tcp_opt_cnt ){
			0		: parse_int_over_tcp;
			default: parse_tcp_option;
		}
	}


	state parse_udp {
		packet.extract(hdr.udp);
		int_parser.apply( packet, hdr.ipv4.dscp, hdr.ipv4.srcAddr, hdr.udp.srcPort, hdr.ipv4.dstAddr, hdr.udp.dstPort, hdr._int, meta._int, standard_metadata, false );
		transition accept;
	}
}

