// number of counters
#define BLOOM_FILTER_ENTRIES 4096

#define BLOOM_FILTER_BIT_WIDTH 8

//frequency of report: a report each 128 packets
#define REPORT_FREQ 128

typedef bit<9>  egressSpec_t;
typedef bit<48> macAddr_t;
typedef bit<32> ip4Addr_t;

header ethernet_t {
	macAddr_t dstAddr;
	macAddr_t srcAddr;
	bit<16>	etherType;
}

header ipv4_t {
	bit<4>	 version;
	bit<4>	 ihl;
	bit<6>	 dscp;
	bit<2>	 ecn;
	bit<16>	totalLen;
	bit<16>	identification;
	bit<3>	 flags;
	bit<13>	fragOffset;
	bit<8>	 ttl;
	bit<8>	 protocol;
	bit<16>	hdrChecksum;
	ip4Addr_t srcAddr;
	ip4Addr_t dstAddr;
}

header tcp_t{
	bit<16> srcPort;
	bit<16> dstPort;
	bit<32> seqNo;
	bit<32> ackNo;
	bit<4>  dataOffset;
	bit<4>  res;
	bit<1>  cwr;
	bit<1>  ece;
	bit<1>  urg;
	bit<1>  ack;
	bit<1>  psh;
	bit<1>  rst;
	bit<1>  syn;
	bit<1>  fin;
	bit<16> window;
	bit<16> checksum;
	bit<16> urgentPtr;
}


#define MAX_TCP_OPTION_WORD 10
header tcp_option_t{
	bit<32> data;
}

header udp_t {
	bit<16> srcPort;
	bit<16> dstPort;
	bit<16> length;
	bit<16> checksum;
}

struct metadata {

/* empty */
	int_metadata _int;
}

struct headers {
	ethernet_t  ethernet;
	ipv4_t		ipv4;
	udp_t		 udp;
	tcp_t		 tcp;

	tcp_option_t[MAX_TCP_OPTION_WORD] tcp_opt;
	int_headers _int;
}



parser MyParser(packet_in packet,
		out headers hdr,
		inout metadata meta,
		inout standard_metadata_t standard_metadata) {


//local variable to count TCP options in number of words
	bit<4> tcp_opt_cnt = 0;

	state start {
		transition parse_ethernet;
	}

	state parse_ethernet {
		packet.extract(hdr.ethernet);
		transition select(hdr.ethernet.etherType) {
			0x800  : parse_ipv4;
			default: accept;
		}
	}
	state parse_ipv4 {
		packet.extract(hdr.ipv4);
		transition select(hdr.ipv4.protocol){
			0x006  : parse_tcp;
			0x011  : parse_udp;
			default: accept;
		}
	}

	state parse_tcp {
		packet.extract(hdr.tcp);


//HN: jump over TCP options
		tcp_opt_cnt = hdr.tcp.dataOffset;

		if( tcp_opt_cnt > 5 )
			tcp_opt_cnt = tcp_opt_cnt - 5;
		else
			tcp_opt_cnt = 0;
		log_msg("====TCP data offset = {}", {tcp_opt_cnt});
		transition select( tcp_opt_cnt ){
			0		 : parse_int_over_tcp;
			default : parse_tcp_option;
		}
	}

	state parse_int_over_tcp {
		int_parser.apply( packet, hdr.ipv4.dscp, hdr.ipv4.srcAddr, hdr.tcp.srcPort, hdr.ipv4.dstAddr, hdr.tcp.dstPort, hdr._int, meta._int, standard_metadata, false );
		transition accept;
	}

	state parse_tcp_option {
		packet.extract( hdr.tcp_opt.next );
		tcp_opt_cnt = tcp_opt_cnt - 1;
		transition select( tcp_opt_cnt ){
			0		: parse_int_over_tcp;
			default: parse_tcp_option;
		}
	}


	state parse_udp {
		packet.extract(hdr.udp);
		int_parser.apply( packet, hdr.ipv4.dscp, hdr.ipv4.srcAddr, hdr.udp.srcPort, hdr.ipv4.dstAddr, hdr.udp.dstPort, hdr._int, meta._int, standard_metadata, false );
		transition accept;
	}
}



control MyVerifyChecksum(inout headers hdr, inout metadata meta) {
	apply {  }
}




control MyIngress(inout headers hdr,
		inout metadata meta,
		inout standard_metadata_t standard_metadata) {
	register<bit<BLOOM_FILTER_BIT_WIDTH>>(BLOOM_FILTER_ENTRIES) bloom_filter;
	bit<BLOOM_FILTER_BIT_WIDTH> counter_val;
	bit<32> counter_pos;

//get register position of corresponding counter
	action compute_hash(ip4Addr_t srcIp){
		hash( counter_pos, HashAlgorithm.crc16, (bit<16>)0, {srcIp}, (bit<32>)BLOOM_FILTER_ENTRIES);
	}

	action drop() {
		mark_to_drop(standard_metadata);
	}

	action ipv4_forward(macAddr_t srcAddr, macAddr_t dstAddr, egressSpec_t port) {
		standard_metadata.egress_spec = port;
		hdr.ethernet.srcAddr = srcAddr;
		hdr.ethernet.dstAddr = dstAddr;
		hdr.ipv4.ttl = hdr.ipv4.ttl - 1;
	}

	table ipv4_lpm {
		key = {
			hdr.ipv4.dstAddr: exact;
		}
		actions = {
			ipv4_forward;
			drop;
			NoAction;
		}
		size = 256;
		default_action = drop();
	}

	apply {
		if (hdr.ipv4.isValid()) {
			ipv4_lpm.apply();


//get number of packets comming from srcAddr
			compute_hash( hdr.ipv4.srcAddr );
			bloom_filter.read(counter_val, counter_pos);

			if( counter_val >= REPORT_FREQ ){

//reset the counter
				bloom_filter.write(counter_pos, 0);


//rember this value tobe able to embed it into INT
				int_mark_packets( meta._int, (bit<16>)counter_val );

//INT work over IP so we put here its ingress
				int_ingress.apply( hdr._int, meta._int, standard_metadata );
			}
		}
	}
}



control MyEgress(inout headers hdr,
		inout metadata meta,
		inout standard_metadata_t standard_metadata) {
	apply {



		int_egress.apply( hdr._int, meta._int, standard_metadata );
		if( meta._int.int_node & INT_NODE_SOURCE != 0 ){

//modify dscp to mark the presence of INT in this packet
			hdr.ipv4.dscp = INT_IPv4_DSCP;

//add size of INT headers
			hdr.ipv4.totalLen = hdr.ipv4.totalLen + INT_ALL_HEADER_LEN_BYTES;
		} 
		if( meta._int.int_node & INT_NODE_SINK != 0 ){

//restor original dscp
			hdr.ipv4.dscp = hdr._int.shim.dscp;

//remove INT headers and its data
			bit<16> len_bytes = ((bit<16>)hdr._int.shim.len) << 2;
			hdr.ipv4.totalLen = hdr.ipv4.totalLen - len_bytes;
		}
		if( meta._int.int_node & INT_NODE_TRANSIT != 0 ){
			hdr.ipv4.totalLen = hdr.ipv4.totalLen + (bit<16>)meta._int.insert_byte_cnt;
		}

	}
}



control MyComputeChecksum(inout headers  hdr, inout metadata meta) {
	apply {
		update_checksum(
				hdr.ipv4.isValid(),
				{ hdr.ipv4.version,
				hdr.ipv4.ihl,
				hdr.ipv4.dscp,
				hdr.ipv4.ecn,
				hdr.ipv4.totalLen,
				hdr.ipv4.identification,
				hdr.ipv4.flags,
				hdr.ipv4.fragOffset,
				hdr.ipv4.ttl,
				hdr.ipv4.protocol,
				hdr.ipv4.srcAddr,
				hdr.ipv4.dstAddr },
				hdr.ipv4.hdrChecksum,
				HashAlgorithm.csum16);
	}
}



control MyDeparser(packet_out packet, in headers hdr) {
	apply {
		packet.emit(hdr.ethernet);
		packet.emit(hdr.ipv4);
		packet.emit(hdr.tcp);
		packet.emit(hdr.udp);

		packet.emit(hdr.tcp_opt);
		int_deparser.apply( packet, hdr._int );
	}
}



V1Switch(
	MyParser(),
	MyVerifyChecksum(),
	MyIngress(),
	MyEgress(),
	MyComputeChecksum(),
	MyDeparser()
) main;

