        hash(ix1, HashAlgorithm.crc16, 32w0x0, {fingerprint}, 32w0xFF);
        hash(ix2, HashAlgorithm.csum16, 32w0x0, {fingerprint}, 32w0xFF);
        hash(ix3, HashAlgorithm.identity, 32w0x0, {fingerprint}, 32w0xFF);

        bloom.read(val1, ix1);
        bloom.read(val2, ix2);
        bloom.read(val3, ix3);

        if(polarity == 1){
            val1 = val1 + 1;
            val2 = val2 + 1;
            val3 = val3 + 1;
        }
        else {

// if statements prevent wraparound
            if(val1 != 0){
                val1 = val1 - 1;
            }
            if(val2 != 0){
                val2 = val2 - 1;
            }
            if(val3 != 0){
                val3 = val3 - 1;
            }
        }

        bloom.write(ix1, val1);
        bloom.write(ix2, val2);
        bloom.write(ix3, val3);
    }


    table apip_lpm {
        actions = {
            _drop;
            set_nhop;
            NoAction;
        }
        key = {
            hdr.apip.dstAddr: lpm;
        }
        size = 1024;
        default_action = _drop();
    }
    table forward {
        actions = {
            set_mac;
            _drop;
            NoAction;
        }
        key = {
            meta.ingress_metadata.nhop_apip: exact;
        }
        size = 512;
        default_action = _drop();
    }

    table brief {
        actions = {
            _drop;
            fwd_delegate;
            NoAction;
        }
        key = {
            hdr.brief.host_id : exact;
        }
        size = 1024;
        default_action = _drop();
    }

    table shutoff {
        actions = {
            _drop;
            fwd_delegate;
            NoAction;
        }
        key = {
            hdr.brief.host_id : exact;
        }
        size = 1024;
        default_action = _drop();
    }

    apply {
        if (hdr.apip.isValid()) {

// normal apip message
            calculate_fingerprint();
            check_bloom();
            if(contains){

// either forward
                translate_ret();
                untranslate_dst();
                apip_lpm.apply();
                forward.apply();
            }
            else{

// or request a verification
                get_signature();
                send_verification_request();
            }
        }
        else if (hdr.verify.isValid()){

// receiving verify request
            fingerprint = hdr.verify.fingerprint;
            update_bloom(1);
        }
        else if (hdr.brief.isValid()){

// forwarding a briefing
            brief.apply();
        }
        else if (hdr.timeout.isValid()){

// timeout a flow
            fingerprint = hdr.timeout.fingerprint;
            update_bloom(0);
        }
        else if (hdr.shutoff.isValid()){

// shutoff a flow
            fingerprint = hdr.shutoff.fingerprint;
            update_bloom(0);
            shutoff.apply();
        }
    }
}

control MyEgress(inout headers hdr, inout metadata meta, inout standard_metadata_t standard_metadata) {
    action rewrite_mac(bit<48> smac) {
        hdr.ethernet.srcAddr = smac;
    }
    action _drop() {
        mark_to_drop(standard_metadata);
    }
    table send_frame {
        actions = {
            rewrite_mac;
            _drop;
            NoAction;
        }
        key = {
            standard_metadata.egress_port: exact;
        }
        size = 256;
        default_action = _drop();
    }
    apply {

//Range 1-3 are forwarded (4 and 5 are never sent)
        if ((hdr.apip_flag.flag >= 1) && (hdr.apip_flag.flag <= 3)) {
          send_frame.apply();
        }
    }
}

control MyComputeChecksum(inout headers hdr, inout metadata meta) {
    apply { }
}

control MyDeparser(packet_out packet, in headers hdr) {
    apply { 
        packet.emit(hdr.ethernet);
        packet.emit(hdr.apip_flag);

        packet.emit(hdr.apip);
        packet.emit(hdr.verify);
        packet.emit(hdr.brief);
        packet.emit(hdr.shutoff);
    }
}

V1Switch(
  MyParser(),
  MyVerifyChecksum(),
  MyIngress(),
  MyEgress(),
  MyComputeChecksum(),
  MyDeparser()
) main;

