/* -*- P4_16 -*- */
#include <core.p4>
#include <v1model.p4>

/*************************************************************************
*********************** H E A D E R S  ***********************************
*************************************************************************/

const bit<16> TYPE_VLAN = 0x8100;
const bit<16> TYPE_RTAG = 0xF1C1;

const int<32> FRER_SEQ_RCVY_HISTORY_LENGTH = 16;

typedef bit<48> macAddr_t;
header ethernet_t {
    macAddr_t dstAddr;
    macAddr_t srcAddr;
    bit<16>   etherType;
}

header vlan_tag_h {
    bit<3> pcp; // Priority Code Point
    bit<1> dei; // Drop Eligible Indicator
    bit<12> vid; // Vlan ID
    bit<16> etherType;
}

header rtag_h {
    bit<16> seq;
    bit<16> reserved;
    bit<16> etherType;
}

struct metadata {
    /* empty */
}

struct headers {
    ethernet_t   ethernet;
    vlan_tag_h   vlan;
    rtag_h       rtag;
}

/*************************************************************************
*********************** P A R S E R  ***********************************
*************************************************************************/

parser MyParser(packet_in packet,
                out headers hdr,
                inout metadata meta,
                inout standard_metadata_t standard_metadata) {
    state start{
        transition parse_ethernet;
    }

    state parse_ethernet {
        packet.extract(hdr.ethernet);
        transition select(hdr.ethernet.etherType) {
            TYPE_VLAN: parse_vlan;
            default: accept;
        }
    }

    state parse_vlan {
        packet.extract(hdr.vlan);
        transition select(hdr.vlan.etherType) {
            TYPE_RTAG: parse_rtag;
            default: accept;
        }

    }

    state parse_rtag {
        packet.extract(hdr.rtag);
        transition accept;
    }
}

/*************************************************************************
************   C H E C K S U M    V E R I F I C A T I O N   *************
*************************************************************************/

control MyVerifyChecksum(inout headers hdr, inout metadata meta) {
    apply {  }
}


/*************************************************************************
**************  I N G R E S S   P R O C E S S I N G   *******************
*************************************************************************/

control MyIngress(inout headers hdr,
                  inout metadata meta,
                  inout standard_metadata_t standard_metadata) {
    register<bit<16>>(1) sequence_num;
    register<bit<1>>(1) take_any;
    register<bit<16>>(1) recov_seq_num;
    register<bit<16>>(1) sequence_history; // TODO bit<16> should be bit<FRER_SEQ_RCVY_HISTORY_LENGTH>

    counter(1, CounterType.packets) passed_packets;
    counter(1, CounterType.packets) rogue_packets;
    counter(1, CounterType.packets) discarded_packets;
    counter(1, CounterType.packets) out_of_order_packets;

    action drop() {
        mark_to_drop(standard_metadata);
    }

    action set_mcast_grp(bit<16> mcast_grp) {
        standard_metadata.mcast_grp = mcast_grp;
    }

    table broadcast {
        actions = {
            set_mcast_grp;
            NoAction;
        }
        key = {
            standard_metadata.ingress_port: exact;
        }
        size = 32;
        default_action = NoAction();
    }

    apply {
        if (standard_metadata.ingress_port == 1) { // Replication

            bit<16> iphdr = hdr.vlan.etherType;

            hdr.vlan.etherType = TYPE_RTAG;
            hdr.rtag.setValid();
            sequence_num.read(hdr.rtag.seq, 0);
            sequence_num.write(0, (bit<16>)(hdr.rtag.seq + 1));
            hdr.rtag.etherType = iphdr;

        } else { // Elimination

            hdr.vlan.etherType = hdr.rtag.etherType;

            // count delta distance
            bit<16> recov_seq_num_tmp = 0;
            recov_seq_num.read(recov_seq_num_tmp, 0);
            int<32> delta = (int<32>)(bit<32>)((hdr.rtag.seq - recov_seq_num_tmp) & (65535));
            if (0 != (delta & 32768))
                delta = delta - 65536;

            // read the value of take_any
            bit<1> take_any_tmp = 0;
            take_any.read(take_any_tmp, 0);

            if (take_any_tmp == 1) {
                take_any.write(0, (bit<1>)0); // set it false

                bit<16> sequence_history_tmp = 0;
                sequence_history.read(sequence_history_tmp, 0);
                sequence_history_tmp = sequence_history_tmp | 32768;
                sequence_history.write(0, sequence_history_tmp);

                recov_seq_num.write(0, hdr.rtag.seq);
                passed_packets.count(0);

            } else if (delta >= FRER_SEQ_RCVY_HISTORY_LENGTH || delta <= -FRER_SEQ_RCVY_HISTORY_LENGTH) {
                // Packet is out-of-order. Count and discard it.
                rogue_packets.count(0);
                discarded_packets.count(0);
                drop();
                return;

            } else if (delta <= 0) {
                // Packet is old and in SequenceHistory; have we seen it before?
                bit<16> neg_idx_helper = 0;
                neg_idx_helper = neg_idx_helper | 32768;
                neg_idx_helper = neg_idx_helper >> (bit<8>)((bit<32>)-delta);
                bit<16> sequence_history_tmp = 0;
                sequence_history.read(sequence_history_tmp, 0);

                if (neg_idx_helper & sequence_history_tmp == 0) {
                    sequence_history.write(0, neg_idx_helper | sequence_history_tmp);
                    out_of_order_packets.count(0);
                    passed_packets.count(0);

                } else {
                    discarded_packets.count(0);
                    drop();
                    return;
                }

            } else {
                // Packet is not too far ahead of the one we want.
                // Packet is out-of-order unless it directly follows recov_seq_num
                if (delta != 1)
                    out_of_order_packets.count(0);

                bit<16> sequence_history_tmp = 0;
                sequence_history.read(sequence_history_tmp, 0);
                sequence_history_tmp = sequence_history_tmp << (bit<8>)((bit<32>)delta);
                sequence_history_tmp = sequence_history_tmp | 32768; // set the first bit to 1

                recov_seq_num.write(0, hdr.rtag.seq);
                passed_packets.count(0);
            }

            hdr.rtag.setInvalid();
        }

        broadcast.apply();
    }
}

/*************************************************************************
****************  E G R E S S   P R O C E S S I N G   *******************
*************************************************************************/

control MyEgress(inout headers hdr,
                 inout metadata meta,
                 inout standard_metadata_t standard_metadata) {

    action set_vlan(bit<12> vid) {
        hdr.vlan.vid = vid;
    }

    table vlan {
        actions = {
            set_vlan;
            NoAction;
        }
        key = {
            standard_metadata.egress_port: exact;
        }
        size = 32;
        default_action = NoAction();
    }

    apply {
        vlan.apply();
    }
}

/*************************************************************************
*************   C H E C K S U M    C O M P U T A T I O N   **************
*************************************************************************/

control MyComputeChecksum(inout headers  hdr, inout metadata meta) {
    apply { }
}

/*************************************************************************
***********************  D E P A R S E R  *******************************
*************************************************************************/

control MyDeparser(packet_out packet, in headers hdr) {
    apply {
        packet.emit(hdr);
    }
}

/*************************************************************************
***********************  S W I T C H  *******************************
*************************************************************************/

V1Switch(
	MyParser(),
	MyVerifyChecksum(),
	MyIngress(),
	MyEgress(),
	MyComputeChecksum(),
	MyDeparser()
) main;

