            dbgPacketOutHdr.apply();
            switch (hdr.packet_out.opcode) {
                ControllerOpcode_t.SEND_TO_PORT_IN_OPERAND0: {
                    stdmeta.egress_spec = (bit<9>) hdr.packet_out.operand0;
                    hdr.packet_out.setInvalid();
