typedef bit<48> macAddr_t;
typedef bit<32> ip4Addr_t;

#define PORTS 4


register<bit<9>>(1) ports_status_r;
register<bit<1>>(PORTS) failed_port;

header ethernet_t {
    macAddr_t dstAddr;
    macAddr_t srcAddr;
    bit<16>   etherType;
}

header ipv4_t {
    bit<4>    version;
    bit<4>    ihl;
    bit<8>    diffserv;
    bit<16>   totalLen;
    bit<16>   identification;
    bit<3>    flags;
    bit<13>   fragOffset;
    bit<8>    ttl;
    bit<8>    protocol;
    bit<16>   hdrChecksum;
    ip4Addr_t srcAddr;
    ip4Addr_t dstAddr;
}

header myTunnel_t {
    bit<16> hops; // number of hops for the packet
    bit<8>   path_length;
}

header tcp_t{
    bit<16> srcPort;
    bit<16> dstPort;
    bit<32> seqNo;
    bit<32> ackNo;
    bit<4>  dataOffset;
    bit<4>  res;
    bit<1>  cwr;
    bit<1>  ece;
    bit<1>  urg;
    bit<1>  ack;
    bit<1>  psh;
    bit<1>  rst;
    bit<1>  syn;
    bit<1>  fin;
    bit<16> window;
    bit<16> checksum;
    bit<16> urgentPtr;
}

struct metadata {
    bit<9>   starting_port;
    bit<9>   out_port; // this is to check the egress port
    bit<9>   all_ports; //all ports 
    bit<9>   out_port_xor; 
    bit<9>   mod_counter;
    bit<9>   check_failure;  //to check if the link failed if(0b111 ^ port_status_r != 0) => failure

    bit<14> ecmp_hash;
    bit<14> ecmp_group_id;
    bit<1>  final_dst;
    bit<4>  dst_id;
    bit<9>  TEL_rnd;


    /* empty */
}

struct headers {
    ethernet_t   ethernet;
    myTunnel_t   myTunnel;
    ipv4_t       ipv4;
    tcp_t        tcp;
}

