            direction_r.read(dir_7, 7);
            port_status_r.read(port_status_7,7);

            bit<1> dir_8;
            bit<1> port_status_8;
            direction_r.read(dir_8, 8);
            port_status_r.read(port_status_8,8);

            bit<1> dir_9;
            bit<1> port_status_9;
            direction_r.read(dir_9, 9);
            port_status_r.read(port_status_9,9);



            bit<1> direction;
            bit<1> remoteseq;
            bit<1> port_status_n;
            bit<1> dir_n;
            //bit<1> port_status_out;
            direction_r.read(direction, (bit<32>)standard_metadata.ingress_port);
            //port_status_r.read(port_status_n,(bit<32>) standard_metadata.ingress_port);
            remote_seq_r.read(remoteseq,(bit<32>) standard_metadata.ingress_port);
            //port_status_r.read(port_status_out,(bit<32>) standard_metadata.egress_spec);

            /*this if block handles packet forwarding for normal scenarios in which there is no link failure 
             It tries to find the first available outlink to send the packet depending on 
             the number of available ports we have to have if statement. Loop is not supported!
             */
            if(meta.final_dst==1){
                hops_r.write((bit<32>) hdr.myTunnel.src_id, hdr.myTunnel.hops_1);
                ipv4_lpm.apply();
            }
            else
            {
                // We check packet sequence to find if the packet comes from changed link
                // or normal
                if (hdr.myTunnel.packet_seq != remoteseq) {
                        reverse_out_to_in(standard_metadata.ingress_port);
                    }


                // Are there any outlink to send the packets?
                // if YES, we check the direction of the packet in one if-else statement
                // ELSE we reverse all IN to OUT
                direction_r.read(dir_n, 2);
                if(dir_n==0 && standard_metadata.ingress_port != 1 || port_status_2 ==0 ){

                    direction_r.read(dir_n, 3);           
                    if(dir_n==0 && standard_metadata.ingress_port != 1 || port_status_3 ==0 ){

                    direction_r.read(dir_n, 4);           
                    if(dir_n==0 && standard_metadata.ingress_port != 1 || port_status_4 ==0 ){

                    direction_r.read(dir_n, 5);           
                    if(dir_n==0 && standard_metadata.ingress_port != 1 || port_status_5 ==0 ){

                    direction_r.read(dir_n, 6);           
                    if(dir_n==0 && standard_metadata.ingress_port != 1 || port_status_6 ==0 ){

                    direction_r.read(dir_n, 7);           
                    if(dir_n==0 && standard_metadata.ingress_port != 1 || port_status_7 ==0 ){

                    direction_r.read(dir_n, 8);           
                    if(dir_n==0 && standard_metadata.ingress_port != 1 || port_status_8 ==0 ){

                    direction_r.read(dir_n, 9);           
                    if(dir_n==0 && standard_metadata.ingress_port != 1 || port_status_9 ==0 ){


                        reverse_in_to_out(2);

                        reverse_in_to_out(3);

                        reverse_in_to_out(4);

                        reverse_in_to_out(5);

                        reverse_in_to_out(6);

                        reverse_in_to_out(7);

                        reverse_in_to_out(8);

                        reverse_in_to_out(9);


                    }

                    }

                    }

                    }

                    }

                    }

                    }

                    }


                 //direction==1
                 // at this stage, we are sure that there is at least one out link
                 // we received a packet from outlink and should check packet sequence
                 // if pkt.seq!=pkt.seq we send to one of outlinks else bounce back packet   

                if(direction==1){

                        direction_r.read(dir_2, 2);
                        port_status_r.read(port_status_2,2);

                        direction_r.read(dir_3, 3);
                        port_status_r.read(port_status_3,3);

                        direction_r.read(dir_4, 4);
                        port_status_r.read(port_status_4,4);

                        direction_r.read(dir_5, 5);
                        port_status_r.read(port_status_5,5);

                        direction_r.read(dir_6, 6);
                        port_status_r.read(port_status_6,6);

                        direction_r.read(dir_7, 7);
                        port_status_r.read(port_status_7,7);

                        direction_r.read(dir_8, 8);
                        port_status_r.read(port_status_8,8);

                        direction_r.read(dir_9, 9);
                        port_status_r.read(port_status_9,9);

                        remote_seq_r.read(remoteseq,(bit<32>) standard_metadata.ingress_port);
                        if (hdr.myTunnel.packet_seq == remoteseq) {
                            //sends pkt back on the port it came from
                            send_on_outlink(standard_metadata.ingress_port);

                        }
                        //else we have to reverse all OUT to IN
                        // and send it from one of the new OUT links
                        else{

                                direction_r.read(dir_2, 2);
                                port_status_r.read(port_status_2,2);

                                direction_r.read(dir_3, 3);
                                port_status_r.read(port_status_3,3);

                                direction_r.read(dir_4, 4);
                                port_status_r.read(port_status_4,4);

                                direction_r.read(dir_5, 5);
                                port_status_r.read(port_status_5,5);

                                direction_r.read(dir_6, 6);
                                port_status_r.read(port_status_6,6);

                                direction_r.read(dir_7, 7);
                                port_status_r.read(port_status_7,7);

                                direction_r.read(dir_8, 8);
                                port_status_r.read(port_status_8,8);

                                direction_r.read(dir_9, 9);
                                port_status_r.read(port_status_9,9);

                                 if (dir_2 == 1 && port_status_2 ==1 ) {
                                        //hdr.myTunnel.packet_seq=1;
                                        send_on_outlink(2);
                                    }

                                   else if (dir_3 == 1 && port_status_3 ==1 ) {
                                        //hdr.myTunnel.packet_seq=1;
                                        send_on_outlink(3);
                                    }

                                   else if (dir_4 == 1 && port_status_4 ==1 ) {
                                        //hdr.myTunnel.packet_seq=1;
                                        send_on_outlink(4);
                                    }

                                   else if (dir_5 == 1 && port_status_5 ==1 ) {
                                        //hdr.myTunnel.packet_seq=1;
                                        send_on_outlink(5);
                                    }

                                   else if (dir_6 == 1 && port_status_6 ==1 ) {
                                        //hdr.myTunnel.packet_seq=1;
                                        send_on_outlink(6);
                                    }

                                   else if (dir_7 == 1 && port_status_7 ==1 ) {
                                        //hdr.myTunnel.packet_seq=1;
                                        send_on_outlink(7);
                                    }

                                   else if (dir_8 == 1 && port_status_8 ==1 ) {
                                        //hdr.myTunnel.packet_seq=1;
                                        send_on_outlink(8);
                                    }

                                   else if (dir_9 == 1 && port_status_9 ==1 ) {
                                        //hdr.myTunnel.packet_seq=1;
                                        send_on_outlink(9);
                                    }

                        }
                    }

                    //direction==0
                    // at this stage, we are sure that there is at least one out link
                    // and the packet should be forwarded through that link
                else
                {

                    direction_r.read(dir_2, 2);
                    port_status_r.read(port_status_2,2);

                    direction_r.read(dir_3, 3);
                    port_status_r.read(port_status_3,3);

                    direction_r.read(dir_4, 4);
                    port_status_r.read(port_status_4,4);

                    direction_r.read(dir_5, 5);
                    port_status_r.read(port_status_5,5);

                    direction_r.read(dir_6, 6);
                    port_status_r.read(port_status_6,6);

                    direction_r.read(dir_7, 7);
                    port_status_r.read(port_status_7,7);

                    direction_r.read(dir_8, 8);
                    port_status_r.read(port_status_8,8);

                    direction_r.read(dir_9, 9);
                    port_status_r.read(port_status_9,9);

                     if (dir_2 == 1 && port_status_2 ==1 ) {
                            //hdr.myTunnel.packet_seq=1;
                            send_on_outlink(2);
                        }

                       else if (dir_3 == 1 && port_status_3 ==1 ) {
                            //hdr.myTunnel.packet_seq=1;
                            send_on_outlink(3);
                        }

                       else if (dir_4 == 1 && port_status_4 ==1 ) {
                            //hdr.myTunnel.packet_seq=1;
                            send_on_outlink(4);
                        }

                       else if (dir_5 == 1 && port_status_5 ==1 ) {
                            //hdr.myTunnel.packet_seq=1;
                            send_on_outlink(5);
                        }

                       else if (dir_6 == 1 && port_status_6 ==1 ) {
                            //hdr.myTunnel.packet_seq=1;
                            send_on_outlink(6);
                        }

                       else if (dir_7 == 1 && port_status_7 ==1 ) {
                            //hdr.myTunnel.packet_seq=1;
                            send_on_outlink(7);
                        }

                       else if (dir_8 == 1 && port_status_8 ==1 ) {
                            //hdr.myTunnel.packet_seq=1;
                            send_on_outlink(8);
                        }

                       else if (dir_9 == 1 && port_status_9 ==1 ) {
                            //hdr.myTunnel.packet_seq=1;
                            send_on_outlink(9);
                        }


                }

        	}
        }
    }
}


