#define TABLE_LUT(NAME,READ,WHICH_LUT,WRITE) table NAME { \
		key= {READ:exact;}\
		actions = {WRITE;}\
		const entries = WHICH_LUT(WRITE)\
		}

#define LUT00(ROUND)	TABLE_LUT(aes_sbox_lut_00_r##ROUND, meta.aes.r0[31:24], GEN_LUT0, merge_to_t0)
