 meta.memcha=(int<32>)meta.clusterMEM##num-(int<32>)hdr.user.userMEM; \
 meta.diskcha=(int<32>)meta.clusterDISK##num-(int<32>)hdr.user.userDISK; \
 meta.netcha=(int<32>)meta.clusterNET##num-(int<32>)hdr.user.userNET; \
 if(meta.cpucha<0||meta.memcha<0||meta.diskcha<0||meta.netcha<0){ \
     meta.leastscore##num=0; \
     meta.balancescore##num=0; \
 } \
 else{ \
     meta.cpuratio=meta.cpucha*(10000/N); \
     meta.memratio=meta.memcha*(10000/N); \
     meta.diskratio=meta.diskcha*(10000/N); \
     meta.netratio=meta.netcha*(10000/N); \
     meta.leastscore##num=meta.cpuratio+meta.memratio+meta.diskratio+meta.netratio; \
     meta.leastscore##num=meta.leastscore##num*Q; \
     meta.cpu_balance=(N-meta.cpucha)*(10000/N); \
     meta.mem_balance=(N-meta.memcha)*(10000/N); \
     meta.disk_balance=(N-meta.diskcha)*(10000/N); \
     meta.net_balance=(N-meta.netcha)*(10000/N); \
     meta.cpu_membalance=meta.cpu_balance-meta.mem_balance; \
     if(meta.cpu_membalance<0){ \
         meta.cpu_membalance=0-meta.cpu_membalance; \
     } \
     meta.cpu_diskbalance=meta.cpu_balance-meta.disk_balance; \
     if(meta.cpu_diskbalance<0){ \
         meta.cpu_diskbalance=0-meta.cpu_diskbalance; \
     } \
     meta.cpu_netbalance=meta.cpu_balance-meta.net_balance; \
     if(meta.cpu_netbalance<0){ \
         meta.cpu_netbalance=0-meta.cpu_netbalance; \
     } \
     meta.mem_diskbalance=meta.mem_balance-meta.disk_balance; \
     if(meta.mem_diskbalance<0){ \
         meta.mem_diskbalance=0-meta.mem_diskbalance; \
     } \
     meta.mem_netbalance=meta.mem_balance-meta.net_balance; \
     if(meta.mem_netbalance<0){ \
         meta.mem_netbalance=0-meta.mem_netbalance; \
     } \
     meta.disk_netbalance=meta.disk_balance-meta.net_balance; \
     if(meta.disk_netbalance<0){ \
         meta.disk_netbalance=0-meta.disk_netbalance; \
     } \
     meta.balancescore##num=meta.cpu_membalance+meta.cpu_diskbalance+meta.cpu_netbalance+meta.mem_diskbalance+meta.mem_netbalance+meta.disk_netbalance; \
     meta.balancescore##num=meta.balancescore##num*P; \
     meta.balancescore##num=10000*P*Q-meta.balancescore##num; \
 } \
 cluster_ID##num.read(meta.delayratio,5); \
 meta.netscore##num=((int<32>)meta.delayratio)*(10000/1000/10); \
 meta.netscore##num=10000*P*Q-meta.netscore##num*P*Q

CLUSTER_REGISTER(1);
CLUSTER_REGISTER(2);
CLUSTER_REGISTER(3);

register<int<32>>(12) cunscore;



control MyIngress(inout headers hdr,
                  inout metadata meta,
                  inout standard_metadata_t standard_metadata) {

    action drop() {
        mark_to_drop(standard_metadata);
    }

    action ipv4_forward(macAddr_t dstAddr, egressSpec_t port) {
        hdr.ethernet.srcAddr = hdr.ethernet.dstAddr;
        hdr.ethernet.dstAddr = dstAddr;
        standard_metadata.egress_spec = port;
        hdr.ipv4.ttl = hdr.ipv4.ttl -1;
    }

    action swap_mac(){
        macAddr_t tmp;
        tmp = hdr.ethernet.srcAddr;
        hdr.ethernet.srcAddr = hdr.ethernet.dstAddr;
        hdr.ethernet.dstAddr = tmp;
        ip4Addr_t tmp1;
        tmp1 = hdr.ipv4.srcAddr;
        hdr.ipv4.srcAddr = hdr.ipv4.dstAddr;
        hdr.ipv4.dstAddr = tmp1;
        standard_metadata.egress_spec = standard_metadata.ingress_port;
        hdr.ipv4.ttl = hdr.ipv4.ttl -1;
        hdr.ipv4.totalLen=hdr.ipv4.totalLen-12;
    }

    table ipv4_lpm {
        key = {
            hdr.ipv4.dstAddr: lpm;
        }
        actions = {
            ipv4_forward;
            drop;
            NoAction;
        }
        size = 1024;
        default_action = NoAction();
    }

    table drop_table{
        actions = {
            drop;
        }
        size =1;
        default_action = drop();
    }

    apply {
        if (hdr.ipv4.isValid()&&hdr.ipv4.protocol!=251&&hdr.ipv4.protocol!=252){
            ipv4_lpm.apply();
        }
        if (hdr.ipv4.protocol==251&&hdr.cluster.isValid()){
            bit<32> ip1;
            bit<32> ip2;
            bit<32> ip3;
            cluster_ID1.read(ip1,0);
            cluster_ID2.read(ip2,0);
            cluster_ID3.read(ip3,0);
            if(hdr.ipv4.srcAddr==ip1){
                CLUSTER_WRITECHANGE(1);
            }
            else if(hdr.ipv4.srcAddr==ip2){
                CLUSTER_WRITECHANGE(2);
            }
            else if(hdr.ipv4.srcAddr==ip3){
                CLUSTER_WRITECHANGE(3);
            }
            else{
                if(ip1==0){
                    CLUSTER_WRITECHANGE(1);
                }
                else if(ip2==0){
                    CLUSTER_WRITECHANGE(2);
                }
                else{
                    CLUSTER_WRITECHANGE(3);
                }
            }
            drop_table.apply();
        }
        if (hdr.ipv4.protocol==252&&hdr.user.isValid()){
            CLUSTER_SCORE(1);
            CLUSTER_SCORE(2);
            CLUSTER_SCORE(3);
            meta.cluster1_score=meta.leastscore1+meta.balancescore1+meta.netscore1;
            meta.cluster2_score=meta.leastscore2+meta.balancescore2+meta.netscore2;
            meta.cluster3_score=meta.leastscore3+meta.balancescore3+meta.netscore3;
            cunscore.write(0,meta.leastscore1);
            cunscore.write(1,meta.leastscore2);
            cunscore.write(2,meta.leastscore3);
            cunscore.write(3,meta.balancescore1);
            cunscore.write(4,meta.balancescore2);
            cunscore.write(5,meta.balancescore3);
            cunscore.write(6,meta.netscore1);
            cunscore.write(7,meta.netscore2);
            cunscore.write(8,meta.netscore3);
            cunscore.write(9,meta.cluster1_score);
            cunscore.write(10,meta.cluster2_score);
            cunscore.write(11,meta.cluster3_score);
            meta.maxscore=meta.cluster1_score;
            cluster_ID1.read(meta.destinationIP,0);
            if(meta.cluster2_score>meta.maxscore){
                meta.maxscore=meta.cluster2_score;
                cluster_ID2.read(meta.destinationIP,0);
            }
            if(meta.cluster3_score>meta.maxscore){
                meta.maxscore=meta.cluster3_score;
                cluster_ID3.read(meta.destinationIP,0);
            }
            swap_mac();
        }
    }
}



control MyEgress(inout headers hdr,
                 inout metadata meta,
                 inout standard_metadata_t standard_metadata) {
    apply {
        if(hdr.ipv4.protocol==252){
            hdr.user.setInvalid();
            hdr.dstip.setValid();
            hdr.dstip.dstIP=meta.destinationIP;
        }
        bit<32> ip1;
        bit<32> ip2;
        bit<32> ip3;
        cluster_ID1.read(ip1,0);
        cluster_ID2.read(ip2,0);
        cluster_ID3.read(ip3,0);
        if(hdr.ipv4.dstAddr==ip1){
            cluster_ID1.write(5,standard_metadata.deq_timedelta);
        }
        if(hdr.ipv4.dstAddr==ip2){
            cluster_ID2.write(5,standard_metadata.deq_timedelta);
        }
        if(hdr.ipv4.dstAddr==ip3){
            cluster_ID3.write(5,standard_metadata.deq_timedelta);
        }
    }
}



control MyComputeChecksum(inout headers hdr, inout metadata meta) {
     apply {
        update_checksum(
            hdr.ipv4.isValid(),
            { hdr.ipv4.version,
              hdr.ipv4.ihl,
              hdr.ipv4.tos,
              hdr.ipv4.totalLen,
              hdr.ipv4.identification,
              hdr.ipv4.flags,
              hdr.ipv4.fragOffset,
              hdr.ipv4.ttl,
              hdr.ipv4.protocol,
              hdr.ipv4.srcAddr,
              hdr.ipv4.dstAddr },
            hdr.ipv4.hdrChecksum,
            HashAlgorithm.csum16);
    }
}




control MyDeparser(packet_out packet, in headers hdr) {
    apply {


//parsed headers have to be added again into the packet.
        packet.emit(hdr.ethernet);
        packet.emit(hdr.ipv4);
        packet.emit(hdr.cluster);
        packet.emit(hdr.user);
        packet.emit(hdr.dstip);
    }
}




//switch architecture
V1Switch(
MyParser(),
MyVerifyChecksum(),
MyIngress(),
MyEgress(),
MyComputeChecksum(),
MyDeparser()
) main;

raw_p4:
/* -*- P4_16 -*- */
#include <core.p4>
#include <v1model.p4>

const bit<16> TYPE_IPV4 = 0x800;

/*************************************************************************
*********************** H E A D E R S  ***********************************
*************************************************************************/

const bit<8> TYPE_TCP = 6;
const bit<8> TYPE_UDP = 17;

typedef bit<9>  egressSpec_t;
typedef bit<48> macAddr_t;
typedef bit<32> ip4Addr_t;

header cpu_header_t {
    bit<8>    flag;
}

header ethernet_t {
    macAddr_t dstAddr;
    macAddr_t srcAddr;
    bit<16>   etherType;
}

header ipv4_t {
    bit<4>    version;
    bit<4>    ihl;
    bit<8>    diffserv;
    bit<16>   totalLen;
    bit<16>   identification;
    bit<3>    flags;
    bit<13>   fragOffset;
    bit<8>    ttl;
    bit<8>    protocol;
    bit<16>   hdrChecksum;
    ip4Addr_t srcAddr;
    ip4Addr_t dstAddr;
}

header tcp_t {
    bit<16> srcPort;
    bit<16> dstPort;
    bit<32> seqNo;
    bit<32> ackNo;
    bit<4>  dataOffset;
    bit<4>  res;
    bit<8>  flags;
    bit<16> window;
    bit<16> checksum;
    bit<16> urgentPtr;
}

header udp_t {
    bit<16> srcPort;
    bit<16> dstPort;
    bit<16> udplen;
    bit<16> udpchk;
}

struct custom_metadata_t {
    bit<32> hash_val1;
    bit<32> hash_val2;
    bit<32> hash_val3;
    bit<32> hash_val4;
    bit<32> hash_val5;
    bit<32> hash_val6;
    bit<32> hash_val7;
    bit<32> hash_val8;
    bit<32> hash_val9;
    bit<32> hash_val10;

    bit<32> count_val1;
    bit<32> count_val2;
    bit<32> count_val3;
    bit<32> count_val4;
    bit<32> count_val5;
    bit<32> count_val6;
    bit<32> count_val7;
    bit<32> count_val8;
    bit<32> count_val9;
    bit<32> count_val10;

    bit<32> count_min;
    bit<32> count_tot;
    bit<32> sum;
}

enum bit<8> FieldLists {
    none = 0,
    redirect_FL = 1
}

struct metadata {
    @field_list(FieldLists.redirect_FL)
    custom_metadata_t custom_metadata;
    bit<32> current_queue_bound;
    bit<32> queue_past_count;
    bit<16>  tcpLength;
}

struct headers {
    cpu_header_t cpu_header;
    ethernet_t   ethernet;
    ipv4_t       ipv4;
    tcp_t        tcp;
    udp_t        udp;
}

/*************************************************************************
*********************** P A R S E R  ***********************************
*************************************************************************/

parser MyParser(packet_in packet,
                out headers hdr,
                inout metadata meta,
                inout standard_metadata_t standard_metadata) {

    state start {

        packet.extract(hdr.ethernet);
        transition select(hdr.ethernet.etherType){

            TYPE_IPV4: ipv4;
            default: accept;
        }
    }

    state ipv4 {
        packet.extract(hdr.ipv4);

        transition select(hdr.ipv4.protocol){
            TYPE_UDP: udp;
            TYPE_TCP: tcp;
            default: accept;
        }
    }

    state tcp {
       packet.extract(hdr.tcp);
       transition accept;
    }

    state udp {
       packet.extract(hdr.udp);
       transition accept;
    }

}

#define CPU_MIRROR_SESSION_ID 250
#define SKETCH_CELL_BIT_WIDTH 32
#define CM_ROW 100
#define K 10
#define W 3
#define SAMPLELIST_SIZE 100
#define MAXIMUM_PACKETS 10000

#define SKETCH_REGISTER(num) register<bit<SKETCH_CELL_BIT_WIDTH>>(CM_ROW) sketch##num
#define SKETCH_COUNT(num, algorithm) hash(meta.custom_metadata.hash_val##num, HashAlgorithm.algorithm, (bit<16>)0, {hdr.ipv4.srcAddr, \
 hdr.ipv4.dstAddr}, (bit<32>)CM_ROW);\
 sketch##num.read(meta.custom_metadata.count_val##num, meta.custom_metadata.hash_val##num); \
 meta.custom_metadata.count_val##num = meta.custom_metadata.count_val##num +1; \
 sketch##num.write(meta.custom_metadata.hash_val##num, meta.custom_metadata.count_val##num)

SKETCH_REGISTER(1);
SKETCH_REGISTER(2);
SKETCH_REGISTER(3);
SKETCH_REGISTER(4);
SKETCH_REGISTER(5);
SKETCH_REGISTER(6);
SKETCH_REGISTER(7);
SKETCH_REGISTER(8);
SKETCH_REGISTER(9);
SKETCH_REGISTER(10);

register<bit<32>>(1) packet_tot;

/*************************************************************************
************   C H E C K S U M    V E R I F I C A T I O N   *************
*************************************************************************/

control MyVerifyChecksum(inout headers hdr, inout metadata meta) {
    apply {  }
}

register<bit<32>>(8) queue_bound;
register<bit<32>>(8) past_count;

/*************************************************************************
**************  I N G R E S S   P R O C E S S I N G   *******************
*************************************************************************/

control MyIngress(inout headers hdr,
                  inout metadata meta,
                  inout standard_metadata_t standard_metadata) {
    action set_heavy_hitter_count() {
        SKETCH_COUNT(1, crc32_custom);
        SKETCH_COUNT(2, crc32_custom);
        SKETCH_COUNT(3, crc32_custom);
        SKETCH_COUNT(4, crc32_custom);
        SKETCH_COUNT(5, crc32_custom);
        SKETCH_COUNT(6, crc32_custom);
        SKETCH_COUNT(7, crc32_custom);
        SKETCH_COUNT(8, crc32_custom);
        SKETCH_COUNT(9, crc32_custom);
        SKETCH_COUNT(10, crc32_custom);
    }

    action do_copy_to_cpu() {
        clone_preserving_field_list(CloneType.I2E, CPU_MIRROR_SESSION_ID, FieldLists.redirect_FL);
    }

    action increment_tot() {
        packet_tot.read(meta.custom_metadata.count_tot,0);
        meta.custom_metadata.count_tot=meta.custom_metadata.count_tot+1;
        packet_tot.write(0,meta.custom_metadata.count_tot);
    }

    action do_read_tot() {
        packet_tot.read(meta.custom_metadata.sum,0);
    }

    action do_find_min1() {
        meta.custom_metadata.count_min=meta.custom_metadata.count_val1;
    }

    action do_find_min2() {
        meta.custom_metadata.count_min=meta.custom_metadata.count_val2;
    }

    action do_find_min3() {
        meta.custom_metadata.count_min=meta.custom_metadata.count_val3;
    }

    action do_find_min4() {
        meta.custom_metadata.count_min=meta.custom_metadata.count_val4;
    }

    action do_find_min5() {
        meta.custom_metadata.count_min=meta.custom_metadata.count_val5;
    }

    action do_find_min6() {
        meta.custom_metadata.count_min=meta.custom_metadata.count_val6;
    }

    action do_find_min7() {
        meta.custom_metadata.count_min=meta.custom_metadata.count_val7;
    }

    action do_find_min8() {
        meta.custom_metadata.count_min=meta.custom_metadata.count_val8;
    }

    action do_find_min9() {
        meta.custom_metadata.count_min=meta.custom_metadata.count_val9;
    }

    action do_find_min10() {
        meta.custom_metadata.count_min=meta.custom_metadata.count_val10;
    }

    action forward(bit<9> egress_spec, bit<48> dst_mac) {
        standard_metadata.egress_spec = egress_spec;
        hdr.ethernet.dstAddr = dst_mac;
    }

    table forwarding {
        actions = {
            forward;
        }
        key = {
            standard_metadata.ingress_port: exact;
            hdr.ipv4.dstAddr              : exact;
        }
    }

    apply {
        if(standard_metadata.ingress_port==1||standard_metadata.ingress_port==2){
            increment_tot();
            do_read_tot();
            set_heavy_hitter_count();
            do_find_min1();
            if(meta.custom_metadata.count_min > meta.custom_metadata.count_val2){
                    do_find_min2();
            }
            if(meta.custom_metadata.count_min > meta.custom_metadata.count_val3){
                    do_find_min3();
            }
            if(meta.custom_metadata.count_min > meta.custom_metadata.count_val4){
                    do_find_min4();
            }
            if(meta.custom_metadata.count_min > meta.custom_metadata.count_val5){
                    do_find_min5();
            }
            if(meta.custom_metadata.count_min > meta.custom_metadata.count_val6){
                    do_find_min6();
            }
            if(meta.custom_metadata.count_min > meta.custom_metadata.count_val7){
                    do_find_min7();
            }
            if(meta.custom_metadata.count_min > meta.custom_metadata.count_val8){
                    do_find_min8();
            }
            if(meta.custom_metadata.count_min > meta.custom_metadata.count_val9){
                    do_find_min9();
            }
            if(meta.custom_metadata.count_min > meta.custom_metadata.count_val10){
                    do_find_min10();
            }

            queue_bound.read(meta.current_queue_bound, 0);
            past_count.read(meta.queue_past_count,0);
            if ((meta.current_queue_bound*meta.custom_metadata.sum <= meta.custom_metadata.count_min*meta.queue_past_count)) {
                standard_metadata.priority = (bit<3>)0;
                queue_bound.write(0, meta.custom_metadata.count_min);
                past_count.write(0,meta.custom_metadata.sum);
            } else {
                queue_bound.read(meta.current_queue_bound, 1);
                past_count.read(meta.queue_past_count,1);
                if ((meta.current_queue_bound*meta.custom_metadata.sum <= meta.custom_metadata.count_min*meta.queue_past_count)) {
                    standard_metadata.priority = (bit<3>)1;
                    queue_bound.write(1, meta.custom_metadata.count_min);
                    past_count.write(1,meta.custom_metadata.sum);
                } else {
                    queue_bound.read(meta.current_queue_bound, 2);
                    past_count.read(meta.queue_past_count,2);
                    if ((meta.current_queue_bound*meta.custom_metadata.sum <= meta.custom_metadata.count_min*meta.queue_past_count)) {
                        standard_metadata.priority = (bit<3>)2;
                        queue_bound.write(2, meta.custom_metadata.count_min);
                        past_count.write(2,meta.custom_metadata.sum);
                    } else {
                        queue_bound.read(meta.current_queue_bound, 3);
                        past_count.read(meta.queue_past_count,3);
                        if ((meta.current_queue_bound*meta.custom_metadata.sum <= meta.custom_metadata.count_min*meta.queue_past_count)) {
                            standard_metadata.priority = (bit<3>)3;
                            queue_bound.write(3, meta.custom_metadata.count_min);
                            past_count.write(3,meta.custom_metadata.sum);
                        } else {
                            queue_bound.read(meta.current_queue_bound, 4);
                            past_count.read(meta.queue_past_count,4);
                            if ((meta.current_queue_bound*meta.custom_metadata.sum <= meta.custom_metadata.count_min*meta.queue_past_count)) {
                                standard_metadata.priority = (bit<3>)4;
                                queue_bound.write(4, meta.custom_metadata.count_min);
                                past_count.write(4,meta.custom_metadata.sum);
                            } else {
                                queue_bound.read(meta.current_queue_bound, 5);
                                past_count.read(meta.queue_past_count,5);
                                if ((meta.current_queue_bound*meta.custom_metadata.sum <= meta.custom_metadata.count_min*meta.queue_past_count)) {
                                    standard_metadata.priority = (bit<3>)5;
                                    queue_bound.write(5, meta.custom_metadata.count_min);
                                    past_count.write(5,meta.custom_metadata.sum);
                                } else {
                                    queue_bound.read(meta.current_queue_bound, 6);
                                    past_count.read(meta.queue_past_count,6);
                                    if ((meta.current_queue_bound*meta.custom_metadata.sum <= meta.custom_metadata.count_min*meta.queue_past_count)) {
                                        standard_metadata.priority = (bit<3>)6;
                                        queue_bound.write(6, meta.custom_metadata.count_min);
                                        past_count.write(6,meta.custom_metadata.sum);
                                    } else {
                                        standard_metadata.priority = (bit<3>)7;
                                        queue_bound.read(meta.current_queue_bound, 7);
                                        past_count.read(meta.queue_past_count,7);

                                        /*Blocking reaction*/
                                        if(meta.current_queue_bound*meta.custom_metadata.sum > meta.custom_metadata.count_min*meta.queue_past_count) {

                                            /*Decrease the bound of all the following queues a factor equal to the cost of the blocking*/

                                            queue_bound.read(meta.current_queue_bound, 1);
                                            past_count.read(meta.queue_past_count,1);			    
                                            queue_bound.write(0,meta.current_queue_bound);
                                            past_count.write(0,meta.queue_past_count);
                                            queue_bound.read(meta.current_queue_bound, 2);
                                            past_count.read(meta.queue_past_count,2);			    
                                            queue_bound.write(1,meta.current_queue_bound);
                                            past_count.write(1,meta.queue_past_count);
                                            queue_bound.read(meta.current_queue_bound, 3);
                                            past_count.read(meta.queue_past_count,3);			    
                                            queue_bound.write(2,meta.current_queue_bound);
                                            past_count.write(2,meta.queue_past_count);
                                            queue_bound.read(meta.current_queue_bound, 4);
                                            past_count.read(meta.queue_past_count,4);			    
                                            queue_bound.write(3,meta.current_queue_bound);
                                            past_count.write(3,meta.queue_past_count);
                                            queue_bound.read(meta.current_queue_bound, 5);
                                            past_count.read(meta.queue_past_count,5);			    
                                            queue_bound.write(4,meta.current_queue_bound);
                                            past_count.write(4,meta.queue_past_count);
                                            queue_bound.read(meta.current_queue_bound, 6);
                                            past_count.read(meta.queue_past_count,6);			    
                                            queue_bound.write(5,meta.current_queue_bound);
                                            past_count.write(5,meta.queue_past_count);		
                                            queue_bound.read(meta.current_queue_bound, 7);
                                            past_count.read(meta.queue_past_count,7);			    
                                            queue_bound.write(6,meta.current_queue_bound);
                                            past_count.write(6,meta.queue_past_count);	    
                                            queue_bound.write(7, meta.custom_metadata.count_min);
                                            past_count.write(7,meta.custom_metadata.sum);
                                        } else {
                                            queue_bound.write(7, meta.custom_metadata.count_min);
                                            past_count.write(7,meta.custom_metadata.sum);
                                        }
                                    }
                                }
			                }
                        }
                    }
                }
            }

            if(meta.custom_metadata.sum >= MAXIMUM_PACKETS){
                do_copy_to_cpu();
            }
        }

        forwarding.apply();
    }
}

/*************************************************************************
****************  E G R E S S   P R O C E S S I N G   *******************
*************************************************************************/

control MyEgress(inout headers hdr,
                 inout metadata meta,
                 inout standard_metadata_t standard_metadata) {
    apply {
        meta.tcpLength = hdr.ipv4.totalLen;
        meta.tcpLength = meta.tcpLength-20;

        if(standard_metadata.instance_type == 0x01) {
            hdr.cpu_header.setValid();
            hdr.cpu_header.flag=1;
        }
    }
}

/*************************************************************************
*************   C H E C K S U M    C O M P U T A T I O N   **************
*************************************************************************/

control MyComputeChecksum(inout headers hdr, inout metadata meta) {
     apply {
        update_checksum(
            hdr.ipv4.isValid(),
            { hdr.ipv4.version,
              hdr.ipv4.ihl,
              hdr.ipv4.diffserv,
              hdr.ipv4.totalLen,
              hdr.ipv4.identification,
              hdr.ipv4.flags,
              hdr.ipv4.fragOffset,
              hdr.ipv4.ttl,
              hdr.ipv4.protocol,
              hdr.ipv4.srcAddr,
              hdr.ipv4.dstAddr },
            hdr.ipv4.hdrChecksum,
            HashAlgorithm.csum16);
        update_checksum_with_payload(
            hdr.tcp.isValid(), 
            { hdr.ipv4.srcAddr, 
            hdr.ipv4.dstAddr, 
            8w0, 
            hdr.ipv4.protocol, 
            meta.tcpLength, 
            hdr.tcp.srcPort, 
            hdr.tcp.dstPort, 
            hdr.tcp.seqNo, 
            hdr.tcp.ackNo, 
            hdr.tcp.dataOffset, 
            hdr.tcp.res, 
            hdr.tcp.flags, 
            hdr.tcp.window, 
            hdr.tcp.urgentPtr}, 
            hdr.tcp.checksum, 
            HashAlgorithm.csum16);
    }
}


/*************************************************************************
***********************  D E P A R S E R  *******************************
*************************************************************************/

control MyDeparser(packet_out packet, in headers hdr) {
    apply {
        packet.emit(hdr.cpu_header);
        packet.emit(hdr.ethernet);
        packet.emit(hdr.ipv4);
        packet.emit(hdr.tcp);
        packet.emit(hdr.udp);
    }
}

