                  out headers hdr,
                  inout metadata meta,
                  inout standard_metadata_t standard_metadata) {

    state start {
        transition parse_ethernet;
    }

    state parse_ethernet {
        packet.extract(hdr.ethernet);
        transition select(hdr.ethernet.etherType) {
            TYPE_IPV4: parse_ipv4;
            default: accept;
        }
    }

    state parse_ipv4 {
        packet.extract(hdr.ipv4);
        transition select(hdr.ipv4.protocol) {
            8w17: parse_udp;
            8w6: parse_tcp;
            default: accept;
        }
    }

    state parse_tcp {
        packet.extract(hdr.tcp);
        transition accept;
    }

    state parse_udp {
        packet.extract(hdr.udp);
	    transition accept;
    }
}




control MyVerifyChecksum(inout headers hdr, inout metadata meta) {   
    apply {  }
}




control MyIngress(inout headers hdr,
                  inout metadata meta,
                  inout standard_metadata_t standard_metadata) {
    action drop() {
        mark_to_drop(standard_metadata);
    }

    action forward(bit<9> egress_spec, bit<48> dst_mac) {
        standard_metadata.egress_spec = egress_spec;
        hdr.ethernet.dst_addr = dst_mac;
    }
    table forwarding {
        actions = {
            forward;
        }
        key = {
            standard_metadata.ingress_port: exact;
            hdr.ipv4.dstAddr              : exact;
        }
    }

    apply {
        if (hdr.ipv4.isValid()) {
            forwarding.apply();
        }
    }
}

register<bit<32>>(1) count_register;



control MyEgress(inout headers hdr,
                 inout metadata meta,
                 inout standard_metadata_t standard_metadata){
    action drop() {
        mark_to_drop(standard_metadata);
    }

    action red(bit<32> min_queue, bit<32> max_queue, bit<32> max_p){
        bit<32> cha=max_queue-min_queue;
        bit<32> q=(bit<32>)standard_metadata.enq_qdepth;
        bit<32> count=0;
        count_register.read(count,0);
        int<32> panduan=(int<32>)q-(int<32>)min_queue;
        bit<32> zong=0;
        bit<32> p=0;
        if(panduan>0){
            p=max_p*(q-min_queue);
            zong=cha*10-p*count;
        }
        bit<32> rnd;
        random(rnd,0,zong);
        if(zong>0&&rnd<p){
            meta.mark_drop = 1;
            count=0;
        }
        else if(zong>0&&rnd>=p){
            count=count+1;
        }
        else{
            meta.mark_drop = 0; 
        }
        count_register.write(0,count);
        if(q>max_queue){
            meta.mark_drop = 1; 
        }
    }

    table aqm{
        key = {
            standard_metadata.egress_port: exact;
        }    
        actions = {
            red();
            NoAction;
        }
        default_action = NoAction; 
    }


    apply {
        meta.tcpLength = hdr.ipv4.totalLen;
        meta.tcpLength = meta.tcpLength-20;
        aqm.apply();    
        if (meta.mark_drop == 1) {
            drop();
        } 
    }

}



control MyComputeChecksum(inout headers hdr, inout metadata meta) {
    apply {
        update_checksum(
            hdr.ipv4.isValid(), 
            { hdr.ipv4.version, 
            hdr.ipv4.ihl, 
            hdr.ipv4.diffserv, 
            hdr.ipv4.totalLen, 
            hdr.ipv4.identification, 
            hdr.ipv4.flags, 
            hdr.ipv4.fragOffset, 
            hdr.ipv4.ttl, 
            hdr.ipv4.protocol, 
            hdr.ipv4.srcAddr, 
            hdr.ipv4.dstAddr }, 
            hdr.ipv4.hdrChecksum, 
            HashAlgorithm.csum16);
        update_checksum_with_payload(
            hdr.tcp.isValid(), 
            { hdr.ipv4.srcAddr, 
            hdr.ipv4.dstAddr, 
            8w0, 
            hdr.ipv4.protocol, 
            meta.tcpLength, 
            hdr.tcp.srcPort, 
            hdr.tcp.dstPort, 
            hdr.tcp.seqNo, 
            hdr.tcp.ackNo, 
            hdr.tcp.dataOffset, 
            hdr.tcp.res, 
            hdr.tcp.flags, 
            hdr.tcp.window, 
            hdr.tcp.urgentPtr}, 
            hdr.tcp.checksum, 
            HashAlgorithm.csum16);
    }
}



control MyDeparser(packet_out packet, in headers hdr) {
    apply {
        packet.emit(hdr.ethernet);
        packet.emit(hdr.ipv4);
        packet.emit(hdr.tcp);
        packet.emit(hdr.udp);
    }
}



V1Switch(
MyParser(),
MyVerifyChecksum(),
MyIngress(),
MyEgress(),
MyComputeChecksum(),
MyDeparser()
) main;

