struct routing_metadata_t {
    bit<16> tcpLength;
}

struct codel_t {
    bit<48> drop_time;

    bit<48> time_now;

    bit<1>  ok_to_drop;

    bit<1>  state_dropping;

    bit<32> delta;

    bit<48> time_since_last_dropping;

    bit<48> drop_next;

    bit<32> drop_cnt;

    bit<32> last_drop_cnt;

    bit<1>  reset_drop_time;

    bit<48> new_drop_time;

    bit<48> new_drop_time_helper;
    bit<9>  queue_id;
}

header ethernet_t {
    bit<48> dst_addr;
    bit<48> src_addr;
    bit<16> ethertype;
}

header ipv4_t {
    bit<4>  version;
    bit<4>  ihl;
    bit<8>  diffserv;
    bit<16> totalLen;
    bit<16> identification;
    bit<3>  flags;
    bit<13> fragOffset;
    bit<8>  ttl;
    bit<8>  protocol;
    bit<16> hdrChecksum;
    bit<32> srcAddr;
    bit<32> dstAddr;
}

header udp_t {
