        {hdr.ipv6.srcAddr, hdr.ipv6.dstAddr, hdr.udp.srcPort, hdr.udp.dstPort, hdr.ipv6.nextHeader}, (bit<32>)SKETCH_BUCKET_LENGTH); \
    sketch##num.read(meta.value_sketch##num, meta.index_sketch##num); \
