#define isClone() standard_metadata.instance_type == 1

const bit<16> ETHERTYPE_ARP  = 0x0806;
const bit<16> ETHERTYPE_VLAN = 0x8100;
const bit<16> ETHERTYPE_IPV4 = 0x0800;
const bit<16> ETHERTYPE_IPV6 = 0x86dd;
const bit<16> ETHERTYPE_ELEPHANTV4 = 0x8822;
const bit<16> ETHERTYPE_ELEPHANTV6 = 0x8823;

const bit<8>  IPPROTO_ICMP  = 0x01;
const bit<8>  IPPROTO_TCP   = 0x06;
const bit<8>  IPPROTO_UDP   = 0x11;

/*************************************************************************
*********************** H E A D E R S  ***********************************
*************************************************************************/

typedef bit<9>   egressSpec_t;
typedef bit<48>  macAddr_t;
typedef bit<32>  ip4Addr_t;
typedef bit<128> ip6Addr_t;

header ethernet_t {
    macAddr_t dstAddr;
    macAddr_t srcAddr;
    bit<16>   etherType;
}

header elephantv4_t {
    bit<1>    flow_addition;  // +
    bit<1>    flow_eviction;  // +
    bit<6>    reserved;       // = 1
    ip4Addr_t srcAddr;        // 4
    ip4Addr_t dstAddr;        // 4
    bit<8>    protocol;       // 1
    bit<16>   srcPort;        // 2
    bit<16>   dstPort;        // 2
}

header elephantv6_t {
    bit<1>    flow_addition;
    bit<1>    flow_eviction;
    bit<6>    reserved;
    ip6Addr_t srcAddr;
    ip6Addr_t dstAddr;
    bit<8>    protocol;
    bit<16>   srcPort;
    bit<16>   dstPort;
}

header ipv4_t {
    bit<4>    version;
    bit<4>    ihl;
    bit<8>    diffserv;
    bit<16>   totalLen;
    bit<16>   identification;
    bit<3>    flags;
    bit<13>   fragOffset;
    bit<8>    ttl;
    bit<8>    protocol;
    bit<16>   hdrChecksum;
    ip4Addr_t srcAddr;
    ip4Addr_t dstAddr;
}

header ipv6_t {
    bit<4>    version;
    bit<8>    trafficClass;
    bit<20>   flowLabel;
    bit<16>   payloadLength;
    bit<8>    nextHeader;
    bit<8>    hopLimit;
    ip6Addr_t srcAddr;
    ip6Addr_t dstAddr;
}

header tcp_t {
    bit<16> srcPort;
    bit<16> dstPort;
    bit<32> seqNo;
    bit<32> ackNo;
    bit<4>  dataOffset;
    bit<4>  res;
    bit<8>  flags;
    bit<16> window;
    bit<16> checksum;
    bit<16> urgentPtr;
}
// Probably accomodate the variable OPTIONS header for a complete implementation
// otherwise it will appear as part of the payload of the program

header udp_t {
    bit<16> srcPort;
    bit<16> dstPort;
    bit<16> plength;
    bit<16> checksum;
}

struct metadata {
    bit<32> index_sketch0;
    bit<32> index_sketch1;
    bit<32> index_sketch2;
    bit<32> index_sketch3;
    bit<32> index_sketch4;
    bit<32> index_sketch5;
    bit<32> index_sketch6;
    bit<32> index_sketch7;

    bit<SKETCH_CELL_BIT_WIDTH> value_sketch0;
    bit<SKETCH_CELL_BIT_WIDTH> value_sketch1;
    bit<SKETCH_CELL_BIT_WIDTH> value_sketch2;
    bit<SKETCH_CELL_BIT_WIDTH> value_sketch3;
    bit<SKETCH_CELL_BIT_WIDTH> value_sketch4;
    bit<SKETCH_CELL_BIT_WIDTH> value_sketch5;
    bit<SKETCH_CELL_BIT_WIDTH> value_sketch6;
    bit<SKETCH_CELL_BIT_WIDTH> value_sketch7;
}


struct headers {
    ethernet_t     ethernet;
    elephantv4_t   elephantv4;
    elephantv6_t   elephantv6;
    ipv4_t         ipv4;
    ipv6_t         ipv6;
    udp_t          udp;
    tcp_t          tcp;
}


/*************************************************************************
*********************** P A R S E R  ***********************************
*************************************************************************/

parser MyParser(packet_in packet,
                out headers hdr,
                inout metadata meta,
                inout standard_metadata_t standard_metadata) {

    state start {
        packet.extract(hdr.ethernet);
        transition select(hdr.ethernet.etherType) {
            ETHERTYPE_IPV4: parse_ipv4;
            ETHERTYPE_IPV6: parse_ipv6;
            default: accept;
        }
    }

    state parse_ipv4 {
        packet.extract(hdr.ipv4);
        transition select(hdr.ipv4.protocol) {
            IPPROTO_UDP  : parse_udp;
            IPPROTO_TCP  : parse_tcp;
            default      : accept;
        }
    }

    state parse_ipv6 {
        packet.extract(hdr.ipv6);
        transition select(hdr.ipv6.nextHeader) {
            IPPROTO_UDP  : parse_udp;
            IPPROTO_TCP  : parse_tcp;
            default      : accept;
        }
    }

    state parse_tcp {
        packet.extract(hdr.tcp);
        transition accept;
    }

    state parse_udp {
        packet.extract(hdr.udp);
        transition accept; 
    }
}


/*************************************************************************
************   C H E C K S U M    V E R I F I C A T I O N   *************
*************************************************************************/

control MyVerifyChecksum(inout headers hdr, inout metadata meta) {
