                    hdr.elephantv6.dstPort = hdr.tcp.dstPort;
                    hdr.tcp.setInvalid();
                }
                hdr.ethernet.etherType = ETHERTYPE_ELEPHANTV6;
            }
        }
    }
}



control MyComputeChecksum(inout headers hdr, inout metadata meta) {
