        packet.emit(hdr.ethernet);
        packet.emit(hdr.elephantv4);
        packet.emit(hdr.elephantv6);
        packet.emit(hdr.ipv4);
        packet.emit(hdr.ipv6);
        packet.emit(hdr.tcp);
        packet.emit(hdr.udp);
    }
}





//switch architecture
V1Switch(
