#define FLOW_TABLE_SIZE_EACH 64
#define HASH_BASE 6w0
#define HASH_MAX 6w63
#define FIELD_LIST_ID 1



#include <core.p4>
#include <v1model.p4>

const bit<16> TYPE_IPV4 = 0x800;

// Additional constants
const bit<16> ETHERTYPE_IPV4        = 0x0800;  // same as TYPE_IPV4, but rename for clarity
const bit<16> ETHERTYPE_IPV6        = 0x86dd;
const bit<16> ETHERTYPE_ELEPHANTV4  = 0x8822;
const bit<16> ETHERTYPE_ELEPHANTV6  = 0x8823;

const bit<8>  IPPROTO_TCP   = 0x06;
const bit<8>  IPPROTO_UDP   = 0x11;

// Headers and Metadata definitions

typedef bit<9>  egressSpec_t;
typedef bit<48> macAddr_t;
typedef bit<32> ip4Addr_t;

header ethernet_t {
    macAddr_t dstAddr;
    macAddr_t srcAddr;
    bit<16>   etherType;
}

header ipv4_t {
    bit<4>    version;
    bit<4>    ihl;
    bit<8>    diffserv;
    bit<16>   totalLen;
    bit<16>   identification;
    bit<3>    flags;
    bit<13>   fragOffset;
    bit<8>    ttl;
    bit<8>    protocol;
    bit<16>   hdrChecksum;
    ip4Addr_t srcAddr;
    ip4Addr_t dstAddr;
}

header ipv6_t {
    bit<4>    version;
    bit<8>    trafficClass;
    bit<20>   flowLabel;
    bit<16>   payloadLength;
    bit<8>    nextHeader;
    bit<8>    hopLimit;
    bit<128>  srcAddr;
    bit<128>  dstAddr;
}

header tcp_t {
    bit<16> srcPort;
    bit<16> dstPort;
    bit<32> seqNo;
    bit<32> ackNo;
    bit<4>  dataOffset;
    bit<4>  res;
    bit<1>  cwr;
    bit<1>  ece;
    bit<1>  urg;
    bit<1>  ack;
    bit<1>  psh;
    bit<1>  rst;
    bit<1>  syn;
    bit<1>  fin;
    bit<16> window;
    bit<16> checksum;
    bit<16> urgentPtr;
}

header udp_t {
    bit<16> srcPort;
    bit<16> dstPort;
    bit<16> plength;
    bit<16> checksum;
}

header elephantv4_t {
    bit<32> srcAddr;
    bit<32> dstAddr;
    bit<8>  protocol;
    bit<16> srcPort;
    bit<16> dstPort;
}

header elephantv6_t {
    bit<128> srcAddr;
    bit<128> dstAddr;
    bit<8>   protocol;
    bit<16>  srcPort;
    bit<16>  dstPort;
}


struct custom_metadata_t {
	bit<32> my_flowID_src;
	bit<32> my_flowID_dst;
	bit<64> my_estimated_count;
	bit<1> already_matched;

  @field_list(FIELD_LIST_ID)
	bit<64> carry_min;
	bit<64> carry_min_plus_one;

  @field_list(FIELD_LIST_ID)
	bit<8> min_stage;
	bit<1> do_recirculate;
	bit<9> orig_egr_port;

	bit<32> hashed_address_s1;
	bit<32> hashed_address_s2;
	bit<32> hashed_address_s3;

	bit<64> random_bits;
	bit<12> random_bits_short;
}

struct headers {
    ethernet_t   ethernet;
    elephantv4_t elephantv4;
    elephantv6_t elephantv6;
    ipv4_t       ipv4;
    ipv6_t       ipv6;
    udp_t        udp;
    tcp_t        tcp;
}

// Standard IPv4 parser, dummy ingress processing

parser MyParser(
    packet_in packet,
    out headers hdr,
    inout custom_metadata_t meta,
    inout standard_metadata_t standard_metadata)
{
  state start {
    packet.extract(hdr.ethernet);
    transition select(hdr.ethernet.etherType) {
        ETHERTYPE_IPV4: parse_ipv4;
        ETHERTYPE_IPV6: parse_ipv6;
        default: accept;
    }
  }

  state parse_ipv4 {
    packet.extract(hdr.ipv4);
    transition select(hdr.ipv4.protocol) {
        IPPROTO_UDP : parse_udp;
        IPPROTO_TCP : parse_tcp;
        default: accept;
    }
  }

  state parse_ipv6 {
    packet.extract(hdr.ipv6);
    transition select(hdr.ipv6.nextHeader) {
      IPPROTO_UDP : parse_udp;
      IPPROTO_TCP : parse_tcp;
      default: accept;
    }
  }

  state parse_tcp {
    packet.extract(hdr.tcp);
    transition accept;
  }

  state parse_udp {
    packet.extract(hdr.udp);
    transition accept;
  }
}


control MyVerifyChecksum(inout headers hdr, inout custom_metadata_t meta) {
  apply {  }
}


control MyIngress(
    inout headers hdr,
    inout custom_metadata_t meta,
    inout standard_metadata_t standard_metadata)
{

  action forward(bit<9> egress_port){
    standard_metadata.egress_spec = egress_port;
  }

  action drop() {
    mark_to_drop(standard_metadata);
  }

  table port {
    key = {
      standard_metadata.ingress_port: exact;
    }
    actions = {
      forward;
      drop;
      NoAction;
    }
    size = 64;
    default_action = drop;
  }

  apply {
    port.apply();
  }
}


// =========== Start implementation of PRECISION ============
// A brief introduction to Precision algorithm:
// 1. We maintain many (flow ID, packet count) tuples
// 2. When new packet comes and a tuple already exist for this flow, we increment the counter.
//    Otherwise, we simulate Space-Saving/RAP algorithm, find the approximate minimum counter and evict.
// 3. We use recirculation to evict entry and evict with probability 1/(min+1).
// In this example, we implement d=3 version of PRECISON, which maintain 3 pairs of flow tables.

control MyEgress(inout headers hdr,
                 inout custom_metadata_t meta,
				 inout standard_metadata_t standard_metadata) {
	register<bit<32> >(FLOW_TABLE_SIZE_EACH)  flow_table_ids_1_src;
	register<bit<32> >(FLOW_TABLE_SIZE_EACH)  flow_table_ids_1_dst;
	register<bit<64> >(FLOW_TABLE_SIZE_EACH)  flow_table_ctrs_1;
	register<bit<32> >(FLOW_TABLE_SIZE_EACH)  flow_table_ids_2_src;
	register<bit<32> >(FLOW_TABLE_SIZE_EACH)  flow_table_ids_2_dst;
	register<bit<64> >(FLOW_TABLE_SIZE_EACH)  flow_table_ctrs_2;
	register<bit<32> >(FLOW_TABLE_SIZE_EACH)  flow_table_ids_3_src;
	register<bit<32> >(FLOW_TABLE_SIZE_EACH)  flow_table_ids_3_dst;
	register<bit<64> >(FLOW_TABLE_SIZE_EACH)  flow_table_ctrs_3;


  action compute_flow_id() {
    meta.my_flowID_src=hdr.ipv4.srcAddr;
    meta.my_flowID_dst=hdr.ipv4.dstAddr;
  }

  action compute_reg_index() {
		// Each flow ID is hashed into d=3 different locations
		hash(meta.hashed_address_s1, HashAlgorithm.crc16, HASH_BASE,
			 	{hdr.ipv4.srcAddr, 7w11, hdr.ipv4.dstAddr}, (bit<16>)FLOW_TABLE_SIZE_EACH);

		hash(meta.hashed_address_s2, HashAlgorithm.crc16, HASH_BASE,
			 	{3w5, hdr.ipv4.srcAddr, 5w3, hdr.ipv4.dstAddr}, (bit<16>)FLOW_TABLE_SIZE_EACH);

		hash(meta.hashed_address_s3, HashAlgorithm.crc16, HASH_BASE,
			 	{2w0, hdr.ipv4.dstAddr, 1w1, hdr.ipv4.srcAddr}, (bit<16>)FLOW_TABLE_SIZE_EACH);
	}

  action clone_and_recirc_replace_entry(){
    // We need to set up a mirror ID in order to make this work.
    // Use simple_switch_CLI: mirroring_add 400 0
    #define MIRROR_ID 400
    // clone3<custom_metadata_t>(CloneType.E2E, MIRROR_ID, meta);
    clone_preserving_field_list(CloneType.E2E, MIRROR_ID, FIELD_LIST_ID);
    // Recirculated packets carried meta.min_stage and meta.count_min, so they themselves know what to do.
  }

  table naive_approximation {
    // Goal: recirculate using probability 1/2^x nearest to 1/(carry_min+1), x between [1..63]
    actions = {
      NoAction();
      clone_and_recirc_replace_entry();
    }
    key = {
      meta.carry_min: ternary;
      meta.random_bits: ternary;
    }
    size = 128;
    default_action = NoAction();
    const entries = {
      #include "include/entries_naive.p4"
    }
  }

	table better_approximation {
		// Goal: recirculate using probability 1/(2^x*T) nearest to 1/(carry_min+1), x between [1..63], T between [8..15]
		actions = {
      NoAction();
      clone_and_recirc_replace_entry();
    }
    key = {
      meta.carry_min_plus_one: ternary;
			meta.random_bits: ternary;
			meta.random_bits_short: range;
    }
    size = 128;
		default_action = NoAction();
		const entries = {
      #include "include/entries_better.p4"
		}
	}

	apply {
    if (!hdr.ipv4.isValid()) {
      return;
    }

    compute_flow_id();
    compute_reg_index();
		// if (hdr.ipv4.isValid()) {
		// 	compute_flow_id_ipv4();
		// 	compute_reg_index_ipv4();
		// } else if (hdr.ipv6.isValid()) {
		// 	compute_flow_id_ipv6();
		// 	compute_reg_index_ipv6();
    // }



		bit<32> tmp_existing_flow_id_src;
		bit<32> tmp_existing_flow_id_dst;
		bit<64> tmp_existing_flow_count;

		meta.my_estimated_count=0;

		if(standard_metadata.instance_type==0){
			// Regular incoming packets.
			// We check if the flow ID is already in the flow table.
			// If not, we remember the minimum counter we've seen so far.

			// access table 1
			flow_table_ids_1_src.read(tmp_existing_flow_id_src, meta.hashed_address_s1);
			flow_table_ids_1_dst.read(tmp_existing_flow_id_dst, meta.hashed_address_s1);
			flow_table_ctrs_1.read(tmp_existing_flow_count, meta.hashed_address_s1);
			if(tmp_existing_flow_count==0 || (tmp_existing_flow_id_src==meta.my_flowID_src && tmp_existing_flow_id_dst==meta.my_flowID_dst)){
				flow_table_ids_1_src.write(meta.hashed_address_s1, meta.my_flowID_src);
				flow_table_ids_1_dst.write(meta.hashed_address_s1, meta.my_flowID_dst);
				flow_table_ctrs_1.write(meta.hashed_address_s1, tmp_existing_flow_count+1);

				meta.my_estimated_count=tmp_existing_flow_count+1;
				meta.already_matched=1;

			}else{
				//save min_stage
				//special case for first stage: always min
				meta.carry_min=tmp_existing_flow_count;
				meta.min_stage=1;
			}

			// access table 2
			if(meta.already_matched==0){
			flow_table_ids_2_src.read(tmp_existing_flow_id_src, meta.hashed_address_s2);
			flow_table_ids_2_dst.read(tmp_existing_flow_id_dst, meta.hashed_address_s2);
			flow_table_ctrs_2.read(tmp_existing_flow_count, meta.hashed_address_s2);
			if(tmp_existing_flow_count==0 || (tmp_existing_flow_id_src==meta.my_flowID_src && tmp_existing_flow_id_dst==meta.my_flowID_dst)){
				flow_table_ids_2_src.write(meta.hashed_address_s2, meta.my_flowID_src);
				flow_table_ids_2_dst.write(meta.hashed_address_s2, meta.my_flowID_dst);
				flow_table_ctrs_2.write(meta.hashed_address_s2, tmp_existing_flow_count+1);

				meta.my_estimated_count=tmp_existing_flow_count+1;
				meta.already_matched=1;

			} else{
					//save min_stage
					if(meta.carry_min>tmp_existing_flow_count){
						meta.carry_min=tmp_existing_flow_count;
						meta.min_stage=2;
					}
				}
			}

			// access table 3
			if(meta.already_matched==0){
				flow_table_ids_3_src.read(tmp_existing_flow_id_src, meta.hashed_address_s3);
				flow_table_ids_3_dst.read(tmp_existing_flow_id_dst, meta.hashed_address_s3);
				flow_table_ctrs_3.read(tmp_existing_flow_count, meta.hashed_address_s3);
				if(tmp_existing_flow_count==0 || (tmp_existing_flow_id_src==meta.my_flowID_src && tmp_existing_flow_id_dst==meta.my_flowID_dst)){
					flow_table_ids_3_src.write(meta.hashed_address_s3, meta.my_flowID_src);
					flow_table_ids_3_dst.write(meta.hashed_address_s3, meta.my_flowID_dst);
					flow_table_ctrs_3.write(meta.hashed_address_s3, tmp_existing_flow_count+1);

					meta.my_estimated_count=tmp_existing_flow_count+1;
					meta.already_matched=1;


				} else {
					//save min_stage
					if(meta.carry_min>tmp_existing_flow_count){
						meta.carry_min=tmp_existing_flow_count;
						meta.min_stage=3;
					}
				}
			}

			// decide to recirculate or not...
			if(meta.already_matched==0){
				// Ideally, we need to recirculate with probability 1/(carry_min+1).
				// There are three options for probabilistic recircuation.
				// 1. Perfect probability: use precisely 1/(carry_min+1) probabilty. May not be supported by all hardware.
				// 2. Better (9/8)-approximation: use a 4-bit floating point to approximate carry_min. Require range match.
				// 3. Naive 2-approximation: approximate 1/(carry_min+1) to the nearest power of 2. Require only ternary match.
				// See paper for more detail.

				#define PERFECT_PROBABILITY
				//#define BETTER_APPROXIMATE
				#if defined(PERFECT_PROBABILITY)
				{
					bit<64> rnd;
					random<bit<64> >(rnd,64w0,meta.carry_min);
					if(rnd==0){
						clone_and_recirc_replace_entry();
					}

				}
				#elif defined(BETTER_APPROXIMATE)
				{
					random<bit<64> >(meta.random_bits,64w0,64w0-1);
					random<bit<12> >(meta.random_bits_short,12w0,12w0-1);
					meta.carry_min_plus_one=meta.carry_min+1;
					better_approximation.apply();

				}
				#else
				{
					random<bit<64> >(meta.random_bits,64w0,64w0-1);
					naive_approximation.apply();
				}
				#endif
			}



		} else {
			// This packet is a recirculated packet.
			// Since we use Clone and Recirculate / Clone and Resubmit, we always drop them.
			mark_to_drop(standard_metadata);

			// We replace the flow ID in the flow tables, and increment the counter.
			if(meta.min_stage==1){
				flow_table_ids_1_src.write(meta.hashed_address_s1, meta.my_flowID_src);
				flow_table_ids_1_dst.write(meta.hashed_address_s1, meta.my_flowID_dst);
				flow_table_ctrs_1.write(meta.hashed_address_s1, meta.carry_min+1);
			}
			if(meta.min_stage==2){
				flow_table_ids_2_src.write(meta.hashed_address_s2, meta.my_flowID_src);
				flow_table_ids_2_dst.write(meta.hashed_address_s2, meta.my_flowID_dst);
				flow_table_ctrs_2.write(meta.hashed_address_s2, meta.carry_min+1);
			}
			if(meta.min_stage==3){
				flow_table_ids_3_src.write(meta.hashed_address_s3, meta.my_flowID_src);
				flow_table_ids_3_dst.write(meta.hashed_address_s3, meta.my_flowID_dst);
				flow_table_ctrs_3.write(meta.hashed_address_s3, meta.carry_min+1);
			}

		}

	}
}

// =========== End implementation of PRECISION ===========

// We did not change header, no need to recompute checksum
control MyComputeChecksum(inout headers hdr, inout custom_metadata_t meta) {
  apply { }
}


// Minimal deparser etc.
control MyDeparser(packet_out packet, in headers hdr) {
  apply {
    packet.emit(hdr.ethernet);
    packet.emit(hdr.ipv4);
    packet.emit(hdr.ipv6);
    packet.emit(hdr.tcp);
    packet.emit(hdr.udp);
  }
}

V1Switch(
  MyParser(),
  MyVerifyChecksum(),
  MyIngress(),
  MyEgress(),
  MyComputeChecksum(),
  MyDeparser()
) main;

/* -*- P4_16 -*- */
#include <core.p4>
#include <v1model.p4>

/*************************************************************************
*********************** H E A D E R S  ***********************************
*************************************************************************/

typedef bit<9>  egressSpec_t;
typedef bit<48> macAddr_t;
typedef bit<32> ip4Addr_t;

const macAddr_t MCAST_MASK = 0xFF_FF_00_00_00_00;
const macAddr_t IPV6_MCAST = 0x33_33_00_00_00_00;

header ethernet_t {
    macAddr_t dstAddr;
    macAddr_t srcAddr;
    bit<16>   etherType;
}

struct metadata {
    bool       is_multicast;
}

struct headers {
    ethernet_t   ethernet;
}

/*************************************************************************
*********************** P A R S E R  ***********************************
*************************************************************************/

parser MyParser(packet_in packet,
                out headers hdr,
                inout metadata meta,
                inout standard_metadata_t standard_metadata) {

    state start {
        packet.extract(hdr.ethernet);
        transition accept;
    }
}


/*************************************************************************
************   C H E C K S U M    V E R I F I C A T I O N   *************
*************************************************************************/

control MyVerifyChecksum(inout headers hdr, inout metadata meta) {
    apply {  }
}


/*************************************************************************
**************  I N G R E S S   P R O C E S S I N G   *******************
*************************************************************************/

control MyIngress(inout headers hdr,
                  inout metadata meta,
                  inout standard_metadata_t standard_metadata) {

    action drop() {

        mark_to_drop(standard_metadata);
    }

    action forward(bit<9> egress_port) {
        standard_metadata.egress_spec = egress_port;
    }

    table dmac {
        key = {
            hdr.ethernet.dstAddr: exact;
        }

        actions = {
            forward;
            NoAction;
        }
        size = 256;
        default_action = NoAction;
    }


    action set_mcast_grp(bit<16> mcast_grp) {
        standard_metadata.mcast_grp = mcast_grp;
        meta.is_multicast = true;
    }

    table multicast {

        key = {
            standard_metadata.ingress_port : exact;
        }
        actions = {
            set_mcast_grp;
            NoAction;
        }
        size = 32;
        default_action =  NoAction;

    }

    apply {
        if ((hdr.ethernet.dstAddr & MCAST_MASK) == IPV6_MCAST) {
            multicast.apply();
        }
        else {
            dmac.apply();
        }

    }
}

/*************************************************************************
****************  E G R E S S   P R O C E S S I N G   *******************
*************************************************************************/

control MyEgress(inout headers hdr,
                 inout metadata meta,
                 inout standard_metadata_t standard_metadata) {


    apply {
        if (meta.is_multicast == true && standard_metadata.ingress_port == standard_metadata.egress_port) {
            mark_to_drop(standard_metadata);
        }
    }
}

/*************************************************************************
*************   C H E C K S U M    C O M P U T A T I O N   **************
*************************************************************************/

control MyComputeChecksum(inout headers hdr, inout metadata meta) {
     apply {

    }
}


/*************************************************************************
***********************  D E P A R S E R  *******************************
*************************************************************************/

control MyDeparser(packet_out packet, in headers hdr) {
    apply {
        //parsed headers have to be added again into the packet.
        packet.emit(hdr.ethernet);
    }
}

/*************************************************************************
***********************  S W I T C H  *******************************
*************************************************************************/

//switch architecture
V1Switch(
MyParser(),
MyVerifyChecksum(),
MyIngress(),
MyEgress(),
MyComputeChecksum(),
MyDeparser()
) main;

