    bit<8>    next_hdr;
    bit<8>    reserved;
    bit<13>   offset; // Offset, in 8B units, relative to the start of the fragmentable part of the original packet.
    bit<2>    res;
    bit<1>    m_flag; // m=0: last fragment
    bit<32>   identification;
}

