    routing_t[MAX_HEADER]      routing;
    fragment_t[MAX_HEADER]     fragment;
    dest_options_t[MAX_HEADER] dest_options;
    icmpv6_t       icmpv6;
    ndp_ra_t       ndp_ra;
    ndp_ll_addr_t  ndp_ll_source;
    ndp_ll_addr_t  ndp_ll_target;
