        packet.extract(hdr.ndp_prefix);
        transition parse_ndp_options;
    }

    state parse_ndp_redirect {
        packet.extract(hdr.ndp_redirect);
        transition parse_ndp_options;
    }

    state parse_ndp_mtu {
        packet.extract(hdr.ndp_mtu);
        transition parse_ndp_options;
    }

}




