#ifndef _IG_CTL_VLAN_IN_P4_
#define _IG_CTL_VLAN_IN_P4_

control IngressControlVlanIn(inout headers hdr,
                             inout ingress_metadata_t ig_md,
                             in standard_metadata_t  ig_intr_md) {

    counter((MAX_PORT+1), CounterType.packets_and_bytes) stats;

    action act_set_vlan_iface(SubIntId_t src) {
        ig_md.source_id = src;
        ig_md.ethertype = hdr.vlan.ethertype;
        ig_md.vlan_size = ig_md.vlan_size + 4;
    }

    action act_set_qinq_iface(SubIntId_t src) {
        ig_md.source_id = src;
        ig_md.ethertype = hdr.vlanq.ethertype;
        ig_md.vlan_size = ig_md.vlan_size + 8;
    }

    action act_set_def_iface() {
        ig_md.source_id = ig_md.ingress_id;
        ig_md.ethertype = hdr.ethernet.ethertype;
    }

    table tbl_vlan_in {
        key = {
ig_md.ingress_id:
            exact;
hdr.vlan.vid:
            exact;
hdr.vlanq.vid:
            exact;
        }
        actions = {
            act_set_vlan_iface;
            act_set_qinq_iface;
            act_set_def_iface;
        }
        size = VLAN_TABLE_SIZE;
        default_action = act_set_def_iface();
    }

    apply {
        tbl_vlan_in.apply();
        stats.count((bit<32>)ig_md.source_id);
    }
}

#endif





#ifndef _IG_CTL_SGT_P4_
#define _IG_CTL_SGT_P4_

control IngressControlSgt(inout headers hdr,
                          inout ingress_metadata_t ig_md,
                          in standard_metadata_t  ig_intr_md) {

    counter((MAX_PORT+1), CounterType.packets_and_bytes) stats;


    action act_need_tag() {
        ig_md.dropping = 0;
        if (ig_md.sgt_valid == 0) ig_md.dropping = 1;
        ig_md.vlan_size = ig_md.vlan_size + 8;
        ig_md.sgt_remove = 1;
        ig_md.sec_grp_id = hdr.sgt.groupid;
        ig_md.ethertype = hdr.sgt.ethertype;
    }

    action act_noned_tag() {
        ig_md.dropping = 0;
        if (ig_md.sgt_valid == 1) ig_md.dropping = 1;
    }


    table tbl_sgt_in {
        key = {
ig_md.source_id:
            exact;
        }
        actions = {
            act_need_tag;
            act_noned_tag;
        }
        size = VLAN_TABLE_SIZE;
        default_action = act_noned_tag();
    }


    action act_set_tag(bit<16> group) {
        ig_md.sec_grp_id = group;
    }

    action act_leave_tag() {
    }


    table tbl_sgt_set {
        key = {
ig_md.source_id:
            exact;
        }
        actions = {
            act_set_tag;
            act_leave_tag;
        }
        size = VLAN_TABLE_SIZE;
        default_action = act_leave_tag();
    }

    apply {
        tbl_sgt_in.apply();
        tbl_sgt_set.apply();
        stats.count((bit<32>)ig_md.source_id);
    }
}

#endif



#ifndef _IG_CTL_VRF_P4_
#define _IG_CTL_VRF_P4_

control IngressControlVRF(inout headers hdr,
                          inout ingress_metadata_t ig_md,
                          inout standard_metadata_t ig_intr_md) {

    action act_set_vrf (switch_vrf_t vrf) {
        ig_md.vrf = vrf;
    }

    action act_set_default_vrf () {
        ig_md.vrf = 0;
    }

    action act_set_mpls_xconn_encap(NextHopId_t target, label_t tunlab, label_t svclab) {
        ig_md.vrf = 0;
        ig_md.nsh_remove = 0;
        ig_md.polka_remove = 0;
        ig_md.mpls0_remove = 0;
        ig_md.mpls1_remove = 0;
        ig_md.arp_valid = 0;
        ig_md.llc_valid = 0;
        ig_md.ipv4_valid = 0;
        ig_md.ipv6_valid = 0;
        hdr.eth2.setValid();
        hdr.eth2.dst_mac_addr = hdr.ethernet.dst_mac_addr;
        hdr.eth2.src_mac_addr = hdr.ethernet.src_mac_addr;
        hdr.eth2.ethertype = ig_md.ethertype;
        ig_md.nexthop_id = target;
        ig_md.ethertype = ETHERTYPE_MPLS_UCAST;
        hdr.mpls0.setValid();
        hdr.mpls0.label = tunlab;
        hdr.mpls0.ttl = 255;
        hdr.mpls0.bos = 0;
        hdr.mpls1.setValid();
        hdr.mpls1.label = svclab;
        hdr.mpls1.ttl = 255;
        hdr.mpls1.bos = 1;
    }

    action act_set_nshconn(bit<24> sp, bit<8> si) {
        ig_md.vrf = 0;
        ig_md.nsh_remove = 0;
        ig_md.polka_remove = 0;
        ig_md.mpls0_remove = 0;
        ig_md.mpls1_remove = 0;
        ig_md.arp_valid = 0;
        ig_md.llc_valid = 0;
        ig_md.ipv4_valid = 0;
        ig_md.ipv6_valid = 0;
        ig_md.nsh_valid = 1;
        hdr.eth2.setValid();
        hdr.eth2.dst_mac_addr = hdr.ethernet.dst_mac_addr;
        hdr.eth2.src_mac_addr = hdr.ethernet.src_mac_addr;
        hdr.eth2.ethertype = ig_md.ethertype;
        ig_md.ethertype = ETHERTYPE_NSH;
        hdr.nsh.setValid();
        hdr.nsh.version = 0;
        hdr.nsh.oam = 0;
        hdr.nsh.res1 = 0;
        hdr.nsh.ttl = 63;
        hdr.nsh.length = 2;
        hdr.nsh.res2 = 0;
        hdr.nsh.md_type = 2;
        hdr.nsh.next_proto = 3;
        hdr.nsh.sp = sp;
        hdr.nsh.si = si;
    }

    action act_set_loconn_ifc (SubIntId_t port) {
        ig_md.vrf = 0;
        ig_md.mpls0_valid = 0;
        ig_md.mpls1_valid = 0;
        ig_md.arp_valid = 0;
        ig_md.llc_valid = 0;
        ig_md.ipv4_valid = 0;
        ig_md.ipv6_valid = 0;
        ig_md.bridge_id = 0;
        ig_md.target_id = port;
        ig_md.nexthop_id = 0;
    }

    action act_set_loconn_nei (NextHopId_t nhop) {
        ig_md.vrf = 0;
        ig_md.mpls0_valid = 0;
        ig_md.mpls1_valid = 0;
        ig_md.arp_valid = 0;
        ig_md.llc_valid = 0;
        ig_md.ipv4_valid = 0;
        ig_md.ipv6_valid = 0;
        ig_md.bridge_id = 0;
        ig_md.target_id = 0;
        ig_md.nexthop_id = nhop;
    }

    action act_set_bridge (SubIntId_t bridge) {
        ig_md.vrf = 0;
        ig_md.mpls0_valid = 0;
        ig_md.mpls1_valid = 0;
        ig_md.arp_valid = 0;
        ig_md.llc_valid = 0;
        ig_md.ipv4_valid = 0;
        ig_md.ipv6_valid = 0;
        ig_md.bridge_id = bridge;
    }

    table tbl_vrf {
        key = {
ig_md.source_id:
            exact;
        }
        actions = {
            act_set_vrf;
            act_set_mpls_xconn_encap;
            act_set_nshconn;
            act_set_loconn_ifc;
            act_set_loconn_nei;
            act_set_bridge;
            act_set_default_vrf;
        }
        size = PORT_TABLE_SIZE;
        default_action = act_set_default_vrf();
    }

    apply {
        tbl_vrf.apply();
    }

}
