#ifndef _IG_CTL_NSH_P4_
#define _IG_CTL_NSH_P4_

control IngressControlNSH(inout headers hdr,
                          inout ingress_metadata_t ig_md,
                          inout standard_metadata_t ig_intr_md) {

    direct_counter(CounterType.packets_and_bytes) stats;

    action act_route(switch_vrf_t vrf) {
        ig_md.vrf = vrf;
        ig_md.nsh_remove = 1;
        if (hdr.nsh.next_proto == 1) ig_md.ethertype = ETHERTYPE_IPV4;
        if (hdr.nsh.next_proto == 2) ig_md.ethertype = ETHERTYPE_IPV6;
        if (hdr.nsh.next_proto == 5) ig_md.ethertype = ETHERTYPE_MPLS_UCAST;
        if (hdr.nsh.next_proto == 3) ig_md.ethertype = ETHERTYPE_ROUTEDMAC;
    }

    action act_fwd_ifc(SubIntId_t port, mac_addr_t src, mac_addr_t dst, bit<24> sp, bit<8> si) {
        ig_md.nsh_remove = 0;
        ig_md.nexthop_id = 0;
        ig_md.target_id = port;
        ig_md.mpls0_valid = 0;
        ig_md.mpls1_valid = 0;
        ig_md.ipv4_valid = 0;
        ig_md.ipv6_valid = 0;
        hdr.ethernet.dst_mac_addr = dst;
        hdr.ethernet.src_mac_addr = src;
        hdr.nsh.sp = sp;
        hdr.nsh.si = si;
    }


    action act_fwd_nei(NextHopId_t nei, bit<24> sp, bit<8> si) {
        ig_md.nsh_remove = 0;
        ig_md.nexthop_id = nei;
        ig_md.target_id = 0;
        ig_md.mpls0_valid = 0;
        ig_md.mpls1_valid = 0;
        ig_md.ipv4_valid = 0;
        ig_md.ipv6_valid = 0;
        hdr.nsh.sp = sp;
        hdr.nsh.si = si;
    }

    table tbl_nsh {
        key = {
hdr.nsh.sp:
            exact;
hdr.nsh.si:
            exact;
        }
        actions = {
            act_fwd_ifc;
            act_fwd_nei;
            act_route;
            @defaultonly NoAction;
        }
        size = NSH_TABLE_SIZE;
        default_action = NoAction();
        counters = stats;
    }

    apply {
        if (ig_md.nsh_valid==1)  {
            tbl_nsh.apply();
        }
    }
}

#endif





#ifndef _IG_CTL_POLKA_P4_
#define _IG_CTL_POLKA_P4_

control IngressControlPOLKA(inout headers hdr,
                            inout ingress_metadata_t ig_md,
                            inout standard_metadata_t ig_intr_md) {

    direct_counter(CounterType.packets_and_bytes) stats;

    action act_forward(NextHopId_t nexthop_id) {
        ig_md.nexthop_id = nexthop_id;
        ig_md.ipv4_valid = 0;
        ig_md.ipv6_valid = 0;
        ig_md.mpls0_valid = 0;
        ig_md.mpls1_valid = 0;
    }

    action act_route() {
        ig_md.polka_remove = 1;
        ig_md.ethertype = hdr.polka.proto;
    }

    table tbl_polka {
        key = {
ig_md.vrf:
            exact;
ig_md.polka_next:
            exact;
        }
        actions = {
            act_forward;
            act_route;
            NoAction;
        }
        size = POLKA_TABLE_SIZE;
        default_action = NoAction();
        counters = stats;
    }

    apply {
        if (ig_md.polka_valid == 1) {
            bit<112> ndata = (bit<112>) (hdr.polka.routeid >> 16);
            bit<16> diff = (bit<16>) hdr.polka.routeid;
            bit<16> nres = 0;
            hash(nres, HashAlgorithm.crc16, 16w0, { ndata }, 16w65535);
            ig_md.polka_next = nres ^ diff;
            tbl_polka.apply();
        }
    }
}

