#ifndef _IG_CTL_PPPOE_P4_
#define _IG_CTL_PPPOE_P4_


control IngressControlPPPOE(inout headers hdr,
                            inout ingress_metadata_t ig_md,
                            inout standard_metadata_t ig_intr_md) {

    action send_to_cpu() {

        ig_md.nexthop_id = CPU_PORT;
    }


    action act_drop() {
        mark_to_drop(ig_intr_md);
    }

    action act_pppoe_data(SubIntId_t port) {
        ig_md.source_id = port;
        if (hdr.pppoeD.ppptyp == PPPTYPE_SGT) ig_md.ethertype = ETHERTYPE_SGT;
        if (hdr.pppoeD.ppptyp == PPPTYPE_NSH) ig_md.ethertype = ETHERTYPE_NSH;
        if (hdr.pppoeD.ppptyp == PPPTYPE_IPV4) ig_md.ethertype = ETHERTYPE_IPV4;
        if (hdr.pppoeD.ppptyp == PPPTYPE_IPV6) ig_md.ethertype = ETHERTYPE_IPV6;
        if (hdr.pppoeD.ppptyp == PPPTYPE_MPLS_UCAST) ig_md.ethertype = ETHERTYPE_MPLS_UCAST;
        if (hdr.pppoeD.ppptyp == PPPTYPE_ROUTEDMAC) ig_md.ethertype = ETHERTYPE_ROUTEDMAC;
    }



    table tbl_pppoe {
        key = {
ig_md.source_id:
            exact;
hdr.pppoeD.session:
            exact;
        }
        actions = {
            act_drop;
            act_pppoe_data;
        }
        size = PPPOE_TABLE_SIZE;
        default_action = act_drop();
    }



    apply {

        if (ig_md.pppoe_ctrl_valid==1)  {
            send_to_cpu();
            return;
        }
        if (ig_md.pppoe_data_valid!=1) return;

        tbl_pppoe.apply();

        if (ig_md.ethertype != ETHERTYPE_ROUTEDMAC) return;

        hdr.eth5.setValid();
        hdr.eth5 = hdr.ethernet;

    }


}


#endif





#ifndef _IG_CTL_TUNNEL_P4_
#define _IG_CTL_TUNNEL_P4_


control IngressControlTunnel(inout headers hdr,
                             inout ingress_metadata_t ig_md,
                             inout standard_metadata_t ig_intr_md) {



    action act_tunnel_gre(SubIntId_t port) {
        hdr.ethernet.ethertype = hdr.gre.gretyp;
        ig_intr_md.egress_spec = (PortId_t)port;
        ig_md.need_recir = 1;
        ig_md.source_id = port;
    }


    action act_tunnel_tmux(SubIntId_t port) {
        if (hdr.tmux.proto == IP_PROTOCOL_SKIP) hdr.ethernet.ethertype = ETHERTYPE_SGT;
        if (hdr.tmux.proto == IP_PROTOCOL_NSH) hdr.ethernet.ethertype = ETHERTYPE_NSH;
        if (hdr.tmux.proto == IP_PROTOCOL_IPV4) hdr.ethernet.ethertype = ETHERTYPE_IPV4;
        if (hdr.tmux.proto == IP_PROTOCOL_IPV6) hdr.ethernet.ethertype = ETHERTYPE_IPV6;
        if (hdr.tmux.proto == IP_PROTOCOL_MPLS_IN_IP) hdr.ethernet.ethertype = ETHERTYPE_MPLS_UCAST;
        if (hdr.tmux.proto == IP_PROTOCOL_SRL2) hdr.ethernet.ethertype = ETHERTYPE_ROUTEDMAC;
        ig_intr_md.egress_spec = (PortId_t)port;
        ig_md.need_recir = 1;
        ig_md.source_id = port;
    }


    action act_tunnel_ipip(SubIntId_t port, ethertype_t ethtyp) {
        hdr.ethernet.ethertype = ethtyp;
        ig_intr_md.egress_spec = (PortId_t)port;
        ig_md.need_recir = 1;
        ig_md.source_id = port;
    }


    action act_tunnel_l2tp(SubIntId_t port) {
        if ((hdr.l2tp.flags & 0x8000) != 0) return;
        if ((hdr.l2tp.ppptyp & 0x8000) != 0) return;
        if (hdr.l2tp.ppptyp == PPPTYPE_SGT) hdr.ethernet.ethertype = ETHERTYPE_SGT;
        if (hdr.l2tp.ppptyp == PPPTYPE_NSH) hdr.ethernet.ethertype = ETHERTYPE_NSH;
        if (hdr.l2tp.ppptyp == PPPTYPE_IPV4) hdr.ethernet.ethertype = ETHERTYPE_IPV4;
        if (hdr.l2tp.ppptyp == PPPTYPE_IPV6) hdr.ethernet.ethertype = ETHERTYPE_IPV6;
        if (hdr.l2tp.ppptyp == PPPTYPE_MPLS_UCAST) hdr.ethernet.ethertype = ETHERTYPE_MPLS_UCAST;
        if (hdr.l2tp.ppptyp == PPPTYPE_ROUTEDMAC) hdr.ethernet.ethertype = ETHERTYPE_ROUTEDMAC;
        ig_intr_md.egress_spec = (PortId_t)port;
        ig_md.need_recir = 1;
        ig_md.source_id = port;
    }


    action act_tunnel_l3tp(SubIntId_t port) {
        if (hdr.l3tp.tidsid == 0) return;
        if ((hdr.l3tp.ppptyp & 0x8000) != 0) return;
        if (hdr.l3tp.ppptyp == PPPTYPE_SGT) hdr.ethernet.ethertype = ETHERTYPE_SGT;
        if (hdr.l3tp.ppptyp == PPPTYPE_NSH) hdr.ethernet.ethertype = ETHERTYPE_NSH;
        if (hdr.l3tp.ppptyp == PPPTYPE_IPV4) hdr.ethernet.ethertype = ETHERTYPE_IPV4;
        if (hdr.l3tp.ppptyp == PPPTYPE_IPV6) hdr.ethernet.ethertype = ETHERTYPE_IPV6;
        if (hdr.l3tp.ppptyp == PPPTYPE_MPLS_UCAST) hdr.ethernet.ethertype = ETHERTYPE_MPLS_UCAST;
        if (hdr.l3tp.ppptyp == PPPTYPE_ROUTEDMAC) hdr.ethernet.ethertype = ETHERTYPE_ROUTEDMAC;
        ig_intr_md.egress_spec = (PortId_t)port;
        ig_md.need_recir = 1;
        ig_md.source_id = port;
    }


    action act_tunnel_vxlan(SubIntId_t port) {
        ig_intr_md.egress_spec = (PortId_t)port;
        ig_md.need_recir = 1;
        ig_md.source_id = port;
    }


    action act_tunnel_etherip(SubIntId_t port) {
        ig_intr_md.egress_spec = (PortId_t)port;
        ig_md.need_recir = 1;
        ig_md.source_id = port;
    }

    action act_tunnel_pckoudp(SubIntId_t port) {
        ig_intr_md.egress_spec = (PortId_t)port;
        ig_md.need_recir = 1;
        ig_md.source_id = port;
    }


    action act_tunnel_amt(SubIntId_t port) {
        if (ig_md.amt_type == 4) hdr.ethernet.ethertype = ETHERTYPE_IPV4;
        if (ig_md.amt_type == 6) hdr.ethernet.ethertype = ETHERTYPE_IPV6;
        ig_intr_md.egress_spec = (PortId_t)port;
        ig_md.need_recir = 1;
        ig_md.source_id = port;
        if (hdr.amt.type != 6) ig_md.need_recir = 0;
    }


    action act_tunnel_gtp(SubIntId_t port) {
        if (ig_md.gtp_type == 4) hdr.ethernet.ethertype = ETHERTYPE_IPV4;
        if (ig_md.gtp_type == 6) hdr.ethernet.ethertype = ETHERTYPE_IPV6;
        ig_intr_md.egress_spec = (PortId_t)port;
        ig_md.need_recir = 1;
        ig_md.source_id = port;
    }



    table tbl_tunnel4 {
        key = {
ig_md.vrf:
            exact;
hdr.ipv4.protocol:
            exact;
hdr.ipv4.src_addr:
            exact;
hdr.ipv4.dst_addr:
            exact;
ig_md.layer4_srcprt:
            exact;
ig_md.layer4_dstprt:
            exact;
        }
        actions = {
            act_tunnel_gre;
            act_tunnel_tmux;
            act_tunnel_ipip;
            act_tunnel_l2tp;
            act_tunnel_l3tp;
            act_tunnel_vxlan;
            act_tunnel_etherip;
            act_tunnel_pckoudp;
            act_tunnel_amt;
            act_tunnel_gtp;
            @defaultonly NoAction;
        }
        size = IPV4_TUNNEL_TABLE_SIZE;
        const default_action = NoAction();
    }


    table tbl_tunnel6 {
        key = {
ig_md.vrf:
            exact;
hdr.ipv6.next_hdr:
            exact;
hdr.ipv6.src_addr:
            exact;
hdr.ipv6.dst_addr:
            exact;
ig_md.layer4_srcprt:
            exact;
ig_md.layer4_dstprt:
            exact;
        }
        actions = {
            act_tunnel_gre;
            act_tunnel_tmux;
            act_tunnel_ipip;
            act_tunnel_l2tp;
            act_tunnel_l3tp;
            act_tunnel_vxlan;
            act_tunnel_etherip;
            act_tunnel_pckoudp;
            act_tunnel_amt;
            act_tunnel_gtp;
            @defaultonly NoAction;
        }
        size = IPV6_TUNNEL_TABLE_SIZE;
        const default_action = NoAction();
    }


    apply {

        ig_md.need_recir = 0;

        if (hdr.ipv4.isValid()) {
            tbl_tunnel4.apply();
        }
        if (hdr.ipv6.isValid()) {
            tbl_tunnel6.apply();
        }

        if (ig_md.need_recir == 0) return;

        if (ig_md.layer3_frag != 0) {
            ig_md.dropping = 1;
        }

        hdr.vxlan.setInvalid();
        hdr.etherip.setInvalid();
        hdr.l2tp.setInvalid();
        hdr.l3tp.setInvalid();
        hdr.amt.setInvalid();
        hdr.gtp.setInvalid();
        hdr.udp.setInvalid();
        hdr.gre.setInvalid();
        hdr.tmux.setInvalid();
        hdr.ipv4.setInvalid();
        hdr.ipv6.setInvalid();
        if (hdr.eth5.isValid()) {
            hdr.eth6.setValid();
            hdr.eth6 = hdr.eth5;
            hdr.eth5.setInvalid();
            hdr.ethernet.ethertype = ETHERTYPE_ROUTEDMAC;
        }
        hdr.cpu.setValid();
        hdr.cpu.port = ig_md.source_id;

    }


}


#endif



#ifndef _IG_CTL_MPLS_P4_
#define _IG_CTL_MPLS_P4_

control IngressControlMPLS(inout headers hdr,
                           inout ingress_metadata_t ig_md,
                           inout standard_metadata_t ig_intr_md) {

    direct_counter(CounterType.packets_and_bytes) stats;

    action act_mpls_cpulabel() {
        ig_md.nexthop_id = CPU_PORT;
        ig_md.mpls_op_type = 0;
        ig_md.nsh_remove = 0;
        ig_md.polka_remove = 0;
        ig_md.mpls0_remove = 0;
        ig_md.mpls1_remove = 0;
        ig_md.nsh_valid = 0;
        ig_md.polka_valid = 0;
        ig_md.mpls0_valid = 0;
        ig_md.mpls1_valid = 0;
        ig_md.ipv4_valid = 0;
        ig_md.ipv6_valid = 0;
    }


    action act_mpls_bcast_label(bit<16> sess) {
        ig_md.clone_session = sess;
        ig_md.need_clone = 1;
        ig_md.mpls0_remove = 0;
        ig_md.mpls1_remove = 0;
        ig_md.mpls_op_type = 0;
        ig_md.ipv4_valid = 0;
        ig_md.ipv6_valid = 0;
        ig_intr_md.mcast_grp = sess;
    }


    action act_mpls_bier_label(bit<16> sess) {
        ig_md.clone_session = sess;
        ig_md.need_clone = 1;
        ig_md.mpls0_remove = 0;
        ig_md.mpls1_remove = 0;
        ig_md.mpls_op_type = 0;
        ig_md.ipv4_valid = 0;
        ig_md.ipv6_valid = 0;
        ig_intr_md.mcast_grp = sess;
    }


    action act_mpls_swap0_set_nexthop(label_t egress_label, NextHopId_t nexthop_id) {

        hdr.mpls0.label = egress_label;

        ig_md.nexthop_id = nexthop_id;
        ig_md.mpls_op_type = 0;
        ig_md.ipv4_valid = 0;
        ig_md.ipv6_valid = 0;
    }


    action act_mpls_swap1_set_nexthop(label_t egress_label, NextHopId_t nexthop_id) {

        hdr.mpls1.label = egress_label;

        ig_md.nexthop_id = nexthop_id;
        hdr.mpls0.setInvalid();
        ig_md.mpls0_remove = 0;
        ig_md.mpls1_remove = 0;
        ig_md.mpls_op_type = 0;
        ig_md.ipv4_valid = 0;
        ig_md.ipv6_valid = 0;
    }

    action act_mpls_swap2_set_nexthop(label_t egress_label1, label_t egress_label2, NextHopId_t nexthop_id) {

        hdr.mpls1.setValid();
        hdr.mpls1 = hdr.mpls0;
        hdr.mpls0.bos = 0;
        hdr.mpls0.label = egress_label1;
        hdr.mpls1.label = egress_label2;

        ig_md.nexthop_id = nexthop_id;
        ig_md.mpls0_remove = 0;
        ig_md.mpls1_remove = 0;
        ig_md.mpls_op_type = 0;
        ig_md.ipv4_valid = 0;
        ig_md.ipv6_valid = 0;
    }

    action act_mpls_decap_set_nexthop(NextHopId_t nexthop_id) {

        ig_md.nexthop_id = nexthop_id;
        ig_md.mpls_op_type = 0;
        ig_md.vrf = 0;
        ig_md.mpls0_remove = 1;
        ig_md.mpls1_remove = 1;
    }

    action act_mpls_decap_ipv4(switch_vrf_t vrf) {


        ig_md.vrf = vrf;
        ig_md.mpls_op_type = 1;
        ig_md.mpls0_remove = 1;
        ig_md.mpls1_remove = 1;

    }

    action act_mpls_decap_l3vpn(switch_vrf_t vrf) {


        ig_md.vrf = vrf;
        ig_md.mpls_op_type = 1;
        ig_md.mpls0_remove = 1;
        ig_md.mpls1_remove = 1;

    }

    action act_mpls_decap_l2vpn(SubIntId_t port) {

        ig_md.ethertype = hdr.eth2.ethertype;
        hdr.ethernet.dst_mac_addr = hdr.eth2.dst_mac_addr;
        hdr.ethernet.src_mac_addr = hdr.eth2.src_mac_addr;
        hdr.eth2.setInvalid();
        hdr.mpls1.setInvalid();
        hdr.mpls0.setInvalid();
        hdr.vlan.setInvalid();
        hdr.vlanq.setInvalid();
        ig_md.target_id = port;

        ig_md.mpls0_remove = 0;
        ig_md.mpls1_remove = 0;
        ig_md.mpls_op_type = 2;
        ig_md.ipv4_valid = 0;
        ig_md.ipv6_valid = 0;
    }

    action act_mpls_decap_vpls(SubIntId_t bridge) {

        ig_md.bridge_id = bridge;
        ig_md.bridge_src = bridge;
        ig_md.ethertype = hdr.eth2.ethertype;
        hdr.ethernet.dst_mac_addr = hdr.eth2.dst_mac_addr;
        hdr.ethernet.src_mac_addr = hdr.eth2.src_mac_addr;

        ig_md.mpls_op_type = 2;
        ig_md.ipv4_valid = 0;
        ig_md.ipv6_valid = 0;
    }


    action act_mpls_decap_pwhe(SubIntId_t port) {

        ig_md.ethertype = hdr.eth2.ethertype;
        hdr.ethernet = hdr.eth2;
        hdr.eth2.setInvalid();
        hdr.mpls1.setInvalid();
        hdr.mpls0.setInvalid();
        ig_md.target_id = port;

        ig_md.mpls_op_type = 2;
        ig_md.ipv4_valid = 0;
        ig_md.ipv6_valid = 0;
        ig_intr_md.egress_spec = (PortId_t)port;
        ig_md.need_recir = 1;
        ig_md.source_id = port;
        ig_md.target_id = port;
        hdr.cpu.setValid();
        hdr.cpu.port = port;
    }




    table tbl_mpls_fib {
        key = {
hdr.mpls0.label:
            exact;
        }
        actions = {


            act_mpls_cpulabel;


            act_mpls_swap0_set_nexthop;


            act_mpls_swap2_set_nexthop;


            act_mpls_decap_set_nexthop;


            act_mpls_decap_ipv4;


            act_mpls_decap_l2vpn;


            act_mpls_decap_vpls;


            act_mpls_decap_pwhe;


            act_mpls_bcast_label;


            act_mpls_bier_label;


            @defaultonly NoAction;
        }
        size = MPLS_TABLE_SIZE;
        default_action = NoAction();
        counters = stats;
    }


    table tbl_mpls_fib_decap {
        key = {
hdr.mpls1.label:
            exact;
        }
        actions = {


            act_mpls_cpulabel;


            act_mpls_swap1_set_nexthop;


            act_mpls_swap2_set_nexthop;


            act_mpls_decap_set_nexthop;


            act_mpls_decap_l3vpn;


            act_mpls_decap_l2vpn;


            act_mpls_decap_vpls;


            act_mpls_decap_pwhe;


            act_mpls_bcast_label;


            act_mpls_bier_label;


            @defaultonly NoAction;
        }
        size = MPLS_TABLE_SIZE;
        default_action = NoAction();
    }



    apply {
        if (ig_md.mpls0_valid == 1) {
            tbl_mpls_fib.apply();
            if ((ig_md.mpls_op_type == 1) && (ig_md.mpls1_valid == 1)) {
                tbl_mpls_fib_decap.apply();
            }
        }
    }
}

#endif





#ifndef _IG_CTL_OUTPORT_P4_
#define _IG_CTL_OUTPORT_P4_

control IngressControlOutPort(inout headers hdr,
                              inout ingress_metadata_t ig_md,
                              inout standard_metadata_t ig_intr_md) {


    action act_set_port_vlan(SubIntId_t port) {
        ig_md.outport_id = port;
        ig_md.aclport_id = ig_md.target_id;
    }

    action act_set_port_novlan() {
        ig_md.outport_id = ig_md.target_id;
        ig_md.aclport_id = ig_md.target_id;
    }

    action act_set_port_nexthop(SubIntId_t port, SubIntId_t subif) {
        ig_md.outport_id = port;
        ig_md.aclport_id = subif;
    }

    action act_set_drop() {
        mark_to_drop(ig_intr_md);
    }



    table tbl_vlan_out {
        key = {
ig_md.target_id:
            exact;
        }
        actions = {
            act_set_port_novlan;
            act_set_port_vlan;
        }
        size = VLAN_TABLE_SIZE;
        default_action = act_set_port_novlan();
    }


    table tbl_nexthop {
        key = {
ig_md.nexthop_id:
            exact;
        }
        actions = {
            act_set_port_nexthop;
            act_set_drop;
        }
        size = NEXTHOP_TABLE_SIZE;
        default_action = act_set_drop();
    }



    apply {

        if (ig_md.target_id != 0) {
            tbl_vlan_out.apply();
            return;
        }

        tbl_nexthop.apply();

    }
}

