#ifndef _IG_CTL_MCAST_P4_
#define _IG_CTL_MCAST_P4_


control IngressControlMcast(inout headers hdr,
                            inout ingress_metadata_t ig_md,
                            inout standard_metadata_t ig_intr_md) {

    direct_counter(CounterType.packets_and_bytes) stats4;
    direct_counter(CounterType.packets_and_bytes) stats6;

    action act_local(SubIntId_t ingr, bit<16> sess) {
        ig_md.clone_session = sess;
        ig_md.need_clone = 0;
        if (ingr != ig_md.source_id) {
            ig_md.dropping = 1;
            return;
        }
    }

    action act_flood(SubIntId_t ingr, bit<16> sess) {
        ig_md.clone_session = sess;
        if (ingr != ig_md.source_id) {
            ig_md.need_clone = 0;
            ig_md.dropping = 1;
            return;
        }
        ig_md.need_clone = 1;
    }


    table tbl_mcast4 {
        key = {
ig_md.vrf:
            exact;
hdr.ipv4.src_addr:
            exact;
hdr.ipv4.dst_addr:
            exact;
        }
        actions = {
            act_local;
            act_flood;
            @defaultonly NoAction;
        }
        size = IPV4_MCAST_TABLE_SIZE;
        const default_action = NoAction();
        counters = stats4;
    }


    table tbl_mcast6 {
        key = {
ig_md.vrf:
            exact;
hdr.ipv6.src_addr:
            exact;
hdr.ipv6.dst_addr:
            exact;
        }
        actions = {
            act_local;
            act_flood;
            @defaultonly NoAction;
        }
        size = IPV6_MCAST_TABLE_SIZE;
        const default_action = NoAction();
        counters = stats6;
    }


    apply {

        ig_md.need_clone = 0;

        if (hdr.ipv4.isValid()) {
            tbl_mcast4.apply();
        }
        if (hdr.ipv6.isValid()) {
            tbl_mcast6.apply();
        }

        if (ig_md.need_clone == 0) return;

        hdr.mpls0.setInvalid();
        hdr.mpls1.setInvalid();
        hdr.bier.setInvalid();
        if (hdr.ipv4.isValid()) ig_md.ethertype = ETHERTYPE_IPV4;
        if (hdr.ipv6.isValid()) ig_md.ethertype = ETHERTYPE_IPV6;
        if (hdr.mpls8.isValid()) ig_md.ethertype = ETHERTYPE_MPLS_UCAST;

        ig_intr_md.mcast_grp = ig_md.clone_session;

    }


}


