    bit<4>    dstSeaidType;
    bit<4>    srcSeaidType;
    bit<4>    dstSeaidLen;
    bit<4>    srcSeaidLen;
    bit<6>    srvType;
    bit<50>   preference;
    bit<4>    reserved;
    bit<4>    flag;
    bit<160>  dstSeaid;
    bit<160>  srcSeaid;
}

header common_t{
    bit<8> version;
    bit<8> ctype;
}

header seadp_data_t{
    bit<8>    flags;
    bit<8>    preference;
    bit<128>  rs_ip;
    bit<16>   mylength;
    bit<16>   checksum;
    bit<32>   packet_number;
    bit<32>   offset;
    bit<32>   len;
}

struct metadata {
    bit<32>   typo_select;
    bit<32>   link_drop;
    bit<32>   typo;
    bit<1>    router;
    bit<1>    drop;
}

struct headers {
    ethernet_t   ethernet;
    ipv6_t       ipv6;
    idp_t        idp;
    common_t     common;
    seadp_data_t seadp;
}

/*************************************************************************
*********************** P A R S E R  ***********************************
*************************************************************************/

parser MyParser(packet_in packet,
                out headers hdr,
                inout metadata meta,
                inout standard_metadata_t standard_metadata) {

    state start {
        transition parse_ethernet;
    }

    state parse_ethernet {
        packet.extract(hdr.ethernet);
        transition select(hdr.ethernet.etherType) {
            TYPE_IPV6: parse_ipv6;
            default: accept;
        }
    }

    state parse_ipv6 {
        packet.extract(hdr.ipv6);
        transition select(hdr.ipv6.nextHeader) {
            TYPE_IDP: parse_idp;
            default: accept;
        }
    }

    state parse_idp{
        packet.extract(hdr.idp);
        transition select(hdr.idp.pType){
            TYPE_SEADP: parse_common;
            default: accept;
        }
    }

    state parse_common{
        packet.extract(hdr.common);
        transition select(hdr.common.ctype){
            TYPE_SEADP_DATA: parse_seadp_data;
            default: accept;
        }
    }

