/*************************************************************************
**************  I N G R E S S   P R O C E S S I N G   *******************
*************************************************************************/

control MyIngress(inout headers hdr,
                  inout metadata meta,
                  inout standard_metadata_t standard_metadata) {

    register <bit<32>>(MAX_RECORD) records;
    register <bit<32>>(MAX_RECORD) map;
    register <bit<32>>(MAX_RECORD) typomap;
    register <bit<32>> (1) index_register;
    register <bit<32>> (1) max_recv_register;
    register <bit<32>> (1) loss1_register;
    register <bit<32>> (1) loss2_register;
    register <bit<32>> (1) loss_count;

    action drop() {
        mark_to_drop(standard_metadata);
        meta.drop = 1;
    }

    action idp_forward(macAddr_t dstAddr, ip6Addr_t ip, egressSpec_t port, ip6Addr_t cur_ip) {
        hdr.ethernet.srcAddr = hdr.ethernet.dstAddr;
        hdr.ethernet.dstAddr = dstAddr;
        standard_metadata.egress_spec = port;
        hdr.ipv6.dstAddr = ip;
        hdr.ipv6.hopLimit = hdr.ipv6.hopLimit - 1;
        if(meta.typo == 1){
            hdr.idp.srvType = 1;
        }
        if(meta.typo == 2){
            hdr.idp.srvType = 2;
        }
        hdr.seadp.rs_ip = cur_ip;
    }

    table idp_exact {
        key = {
            meta.typo: exact;
        }
        actions = {
            idp_forward;
            drop;
            NoAction;
        }
        size = 1024;
        default_action = NoAction();
    }

    action ipv6_forward(macAddr_t dstAddr, egressSpec_t port) {
        hdr.ethernet.srcAddr = hdr.ethernet.dstAddr;
        hdr.ethernet.dstAddr = dstAddr;
        standard_metadata.egress_spec = port;
        hdr.ipv6.hopLimit = hdr.ipv6.hopLimit - 1;
        meta.router = 1;
        bit<32> num;
        loss_count.read(num, 0);
        if(hdr.seadp.isValid() && hdr.seadp.rs_ip != 0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF){    
            if(num == 3){
                meta.link_drop = 1;
            }
            num = num + 1;
            if(num == 4){
                num = 0;
            }
        }
        loss_count.write(0, num);
    }

    table drop_exact {
        key = {meta.link_drop: exact;}
        actions = {drop; NoAction;}
        size = 2;
        default_action = NoAction();
    }

    table ipv6_exact {
        key = {
            hdr.ipv6.dstAddr: exact;
        }
        actions = {
            ipv6_forward;
            drop;
            NoAction;
        }
        size = 1024;
        default_action = NoAction();
    }

    apply {
        ipv6_exact.apply();
        drop_exact.apply();
        if(meta.router == 0){
            if (hdr.idp.isValid() && hdr.seadp.isValid()) {

                // 处理确认包
                if(hdr.seadp.rs_ip == 0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF){
                    bit<32> id;
                    hash(id,HashAlgorithm.crc32,MIN_VALUE,
                    { hdr.idp.srcSeaid,
                    hdr.idp.dstSeaid,
                    hdr.seadp.packet_number },
                    MAX_VALUE);
                    bit<32> index;
                    map.read(index, id);
                    records.write(index, 0);
                    bit<32> max_recv;
                    max_recv_register.read(max_recv, 0);
                    if(index > max_recv)
                    max_recv_register.write(0, index);
                    drop();
                }

                // 计算哈希值
                if(meta.drop == 0){
                    hash(meta.typo_select,
                    HashAlgorithm.crc32,
                    RANGE_MIN,
                    { hdr.idp.srcSeaid,
                    hdr.idp.dstSeaid,
                    hdr.ipv6.hopLimit,
                    hdr.seadp.packet_number },
                    RANGE_MAX);
                    // 选择拓扑
                    bit<32> loss1;
                    bit<32> loss2;
                    loss1_register.read(loss1, 0);
                    loss2_register.read(loss2, 0);
                    bit<32> offset;
                    offset = 50 + loss2 + loss2 - loss1 - loss1;
                    if(meta.typo_select < offset ){
                        meta.typo = 1;
                    } 
                    else{
                        meta.typo = 2;
                    }
                    // 根据拓扑选路
                    idp_exact.apply();
                }

                // 记录发包
                if(meta.drop == 0){
                    bit<32> index;
                    index_register.read(index, 0);
                    bit<32> cur;
                    hash(cur,HashAlgorithm.crc32,MIN_VALUE,
                    { hdr.idp.srcSeaid,
                    hdr.idp.dstSeaid,
                    hdr.seadp.packet_number },
                    MAX_VALUE);
                    records.write(index, cur);
                    bit<32> cur_typo;
                    cur_typo = meta.typo;
                    typomap.write(index,cur_typo);
                    map.write(cur, index);
                    index = index + 1;
                    index_register.write(0, index);
                }

                // 检测丢包  8*16
                if(meta.drop == 0){
                    bit<32> max_recv;
                    max_recv_register.read(max_recv, 0);
                    if(max_recv > 10){
                        bit<32> loss1 = 0;
                        bit<32> loss2 = 0;
                        bit<32> i = max_recv - 1;
                        bit<32> cur;
                        bit<32> check_typo;

                        records.read(cur, i);
                        if(cur != 0){
                            typomap.read(check_typo, i);
                            if(check_typo == 1){
                                loss1 = loss1 + 1;
                            }
                            else if(check_typo == 2){
                                loss2 = loss2 + 1;
                            }
                        }
                        i = i - 1;

                        records.read(cur, i);
                        if(cur != 0){
                            typomap.read(check_typo, i);
                            if(check_typo == 1){
                                loss1 = loss1 + 1;
                            }
                            else if(check_typo == 2){
                                loss2 = loss2 + 1;
                            }
                        }
                        i = i - 1;

                        records.read(cur, i);
                        if(cur != 0){
                            typomap.read(check_typo, i);
                            if(check_typo == 1){
                                loss1 = loss1 + 1;
                            }
                            else if(check_typo == 2){
                                loss2 = loss2 + 1;
                            }
                        }
                        i = i - 1;

                        records.read(cur, i);
                        if(cur != 0){
                            typomap.read(check_typo, i);
                            if(check_typo == 1){
                                loss1 = loss1 + 1;
                            }
                            else if(check_typo == 2){
                                loss2 = loss2 + 1;
                            }
                        }
                        i = i - 1;

                        records.read(cur, i);
                        if(cur != 0){
                            typomap.read(check_typo, i);
                            if(check_typo == 1){
                                loss1 = loss1 + 1;
                            }
                            else if(check_typo == 2){
                                loss2 = loss2 + 1;
                            }
                        }
                        i = i - 1;

                        records.read(cur, i);
                        if(cur != 0){
                            typomap.read(check_typo, i);
                            if(check_typo == 1){
                                loss1 = loss1 + 1;
                            }
                            else if(check_typo == 2){
                                loss2 = loss2 + 1;
                            }
                        }
                        i = i - 1;

                        records.read(cur, i);
                        if(cur != 0){
                            typomap.read(check_typo, i);
                            if(check_typo == 1){
                                loss1 = loss1 + 1;
                            }
                            else if(check_typo == 2){
                                loss2 = loss2 + 1;
                            }
                        }
                        i = i - 1;

                        records.read(cur, i);
                        if(cur != 0){
                            typomap.read(check_typo, i);
                            if(check_typo == 1){
                                loss1 = loss1 + 1;
                            }
                            else if(check_typo == 2){
                                loss2 = loss2 + 1;
                            }
                        }
                        i = i - 1;

                        records.read(cur, i);
                        if(cur != 0){
                            typomap.read(check_typo, i);
                            if(check_typo == 1){
                                loss1 = loss1 + 1;
                            }
                            else if(check_typo == 2){
                                loss2 = loss2 + 1;
                            }
                        }
                        i = i - 1;

                        records.read(cur, i);
                        if(cur != 0){
                            typomap.read(check_typo, i);
                            if(check_typo == 1){
                                loss1 = loss1 + 1;
                            }
                            else if(check_typo == 2){
                                loss2 = loss2 + 1;
                            }
                        }

                        bit<32> loss1_rate = loss1 * 10;
                        loss1_register.write(0, loss1_rate);
                        bit<32> loss2_rate = loss2 * 10;
                        loss2_register.write(0, loss2_rate);
                    }
