	if (hdr.tun.isValid()) {
		if ( !myTunnel_table.apply().hit ) {
			tun_forwarding_table.apply();
		}
		else {
			hdr.tun.setInvalid();
			hdr.ethernet.ethtype = ETHERTYPE_IPV4;
		}
	}

	if (hdr.ipv4.isValid() && !hdr.tun.isValid()) {
		if ( my_mac_addresses_table.apply().hit ) {
			l3_forwarding_table.apply();
			arp_cache_table.apply();
		}
	}

	if  (!l2_unicast_table.apply().hit) {
		set_local_broadcast();
	}

    }
}

