		hdr.ipv4.dstAddr : lpm;
	}
	actions = { set_nhgrp; drop; }
	size = 256;
	default_action = drop;
}

table ipv4_forward {
    key = {
		meta.routing_metadata.nhgrp : exact;        
    }
    actions = {pkt_send; drop; }
    size = 64;
    default_action = drop;
}



apply {

	if ( (hdr.ethernet.dstAddr == OWN_MAC) || (hdr.ethernet.dstAddr == BCAST_MAC) )
	{
		    if ( hdr.ipv4.isValid() ) {
			    ue_selector.apply();
			    teid_rate_limiter.apply();

			    ipv4_lpm.apply();
			    ipv4_forward.apply();
		    }
    	}
      }
}



