                ((bit<2>) ((bit<1>) t2.apply().hit)) +
                ((bit<2>) ((bit<1>) t3.apply().hit))) {
                0: { hdr.ethernet.src_addr[15:8] = 1; }
                1: { hdr.ethernet.src_addr[15:8] = 2; }
                2: { hdr.ethernet.src_addr[15:8] = 3; }
                3: { hdr.ethernet.src_addr[15:8] = 4; }
            }
        }
    }
}

