struct headers_t {
    ethernet_h    ethernet;
}

struct metadata_t {
}

parser ingressParserImpl(
    packet_in pkt,
    out headers_t hdr,
    inout metadata_t umd,
    inout standard_metadata_t stdmeta)
{
    state start {
        pkt.extract(hdr.ethernet);
        transition accept;
    }
}

control verifyChecksum(
    inout headers_t hdr,
    inout metadata_t umd)
{
    apply { }
}

bit<8> fn1 (in bit<8> x, inout bit<8> y, inout standard_metadata_t stdmeta) {
    if (x < 10) {
        y = y + 127;
        return x;
    } else {
        y = y - 1;
        mark_to_drop(stdmeta);
        return x + 10;
    }

}

control ingressImpl(
    inout headers_t hdr,
    inout metadata_t umd,
    inout standard_metadata_t stdmeta)
{
    bit<8> ret1 = 0;
    action my_drop() {
        mark_to_drop(stdmeta);
    }
    action t1_a1() {
        hdr.ethernet.src_addr[7:0] = 1;
    }
    action t1_a2() {
        hdr.ethernet.src_addr[7:0] = 2;
        exit;
    }
    action t1_a3() {
        stdmeta.egress_spec = 2;
    }
    table t1 {
        key = { hdr.ethernet.dst_addr[7:0] : exact; }
        actions = { t1_a1; t1_a2; t1_a3; NoAction; }
        const default_action = NoAction;
    }
    apply {
        stdmeta.egress_spec = 1;
        if (hdr.ethernet.isValid()) {

            hdr.ethernet.src_addr[15:8] =
                fn1(hdr.ethernet.dst_addr[15:8], hdr.ethernet.src_addr[23:16],
                    stdmeta) +
                (bit<8>) ((bit<1>) t1.apply().hit);
        }
    }
}

control egressImpl(
    inout headers_t hdr,
    inout metadata_t umd,
    inout standard_metadata_t stdmeta)
{
    apply { }
}

control updateChecksum(
    inout headers_t hdr,
    inout metadata_t umd)
{
    apply { }
}

control egressDeparserImpl(
    packet_out pkt,
    in headers_t hdr)
{
    apply {
        pkt.emit(hdr.ethernet);
    }
}

V1Switch(ingressParserImpl(),
         verifyChecksum(),
         ingressImpl(),
         egressImpl(),
         updateChecksum(),
         egressDeparserImpl()) main;

