// -- Protocol headers 

#define ETHERNET_HEADER_BYTES 14

header ethernet_t {
  ethernet_addr_t dst_addr;
  ethernet_addr_t src_addr;
  ether_type_t ether_type;
}

header vlan_t {

  bit<3> priority_code_point;

// PCP
  bit<1> drop_eligible_indicator;

// DEI
  vlan_id_t vlan_id;

  ether_type_t ether_type;
}

#define IPV4_HEADER_BYTES 20

header ipv4_t {
  bit<4> version;
  bit<4> ihl;
  bit<6> dscp;

  bit<2> ecn;

  bit<16> total_len;
  bit<16> identification;
  bit<1> reserved;
  bit<1> do_not_fragment;
  bit<1> more_fragments;
  bit<13> frag_offset;
  bit<8> ttl;
  bit<8> protocol;
  bit<16> header_checksum;
  ipv4_addr_t src_addr;
  ipv4_addr_t dst_addr;
}

#define IPV6_HEADER_BYTES 40

header ipv6_t {
  bit<4> version;
  bit<6> dscp;

  bit<2> ecn;

  bit<20> flow_label;
  bit<16> payload_length;
  bit<8> next_header;
  bit<8> hop_limit;
  ipv6_addr_t src_addr;
  ipv6_addr_t dst_addr;
}

#define UDP_HEADER_BYTES 8

header udp_t {
  bit<16> src_port;
  bit<16> dst_port;
  bit<16> hdr_length;
  bit<16> checksum;
}

header tcp_t {
  bit<16> src_port;
  bit<16> dst_port;
  bit<32> seq_no;
  bit<32> ack_no;
  bit<4> data_offset;
  bit<4> res;
  bit<8> flags;
  bit<16> window;
  bit<16> checksum;
  bit<16> urgent_ptr;
}

header icmp_t {
  bit<8> type;
  bit<8> code;
  bit<16> checksum;
  bit<32> rest_of_header;
}

header arp_t {
  bit<16> hw_type;
  bit<16> proto_type;
  bit<8> hw_addr_len;
  bit<8> proto_addr_len;
  bit<16> opcode;
  bit<48> sender_hw_addr;
  bit<32> sender_proto_addr;
  bit<48> target_hw_addr;
  bit<32> target_proto_addr;
}

#define GRE_HEADER_BYTES 4

header gre_t {
  bit<1> checksum_present;
  bit<1> routing_present;
  bit<1> key_present;
  bit<1> sequence_present;
  bit<1> strict_source_route;
  bit<3> recursion_control;
  bit<1> acknowledgement_present;
  bit<4> flags;
  bit<3> version;
  bit<16> protocol;
}

#define IPFIX_HEADER_BYTES 16


// IP Flow Information Export (IPFIX) header, pursuant to RFC 7011 section 3.1.
header ipfix_t {

// Version of IPFIX to which this Message conforms.
  bit<16> version_number;

  bit<16> length;

  bit<32> export_time;

  bit<32> sequence_number;

  bit<32> observation_domain_id;
}

#define PSAMP_EXTENDED_BYTES 28

// PSAMP extended header, pursuant to RFC5476.
header psamp_extended_t {
  bit<16> template_id;
  bit<16> length;

// Ingress timestamp in nanoseconds.
  bit<64> observation_time;
  bit<16> flowset;
  bit<16> next_hop_index;
  bit<16> epoch;
  bit<16> ingress_port;
  bit<16> egress_port;
  bit<16> user_meta_field;
  bit<8> dlb_id;
  bit<8> variable_length;
  bit<16> packet_sampled_length;
}


