      headers.packet_out_header.setInvalid();
      headers.packet_in_header = {
        ingress_port = (port_id_t) local_metadata.packet_in_ingress_port,
        target_egress_port =
          (port_id_t) local_metadata.packet_in_target_egress_port,
        unused_pad = 0
      };
    }
