// Structs
struct headers {
    ethernet_t                  ethernet;
    ipv4_t                      ipv4;
    tcp_t                       tcp;
    udp_t                       udp;
    /* INT header (shim + header) */
    int_tcpudp_shim_t           int_shim;
    int_header_t                int_header;
    /* INT metadata */
    int_switch_id_t             int_switch_id;
