    action a() { standard_meta.egress_spec = 0; }
    action a_with_control_params(bit<9> x) { standard_meta.egress_spec = x; }

    table t_exact {

  	key = {
            h.h.row.e : exact;
        }

	actions = {
            a;
            a_with_control_params;
        }

	default_action = a;

        const entries = {
            0x01 : a_with_control_params(1);
            0x02 : a_with_control_params(2);
        }
    }

    apply {
        t_exact.apply();
    }
}


