        transition select(addrType) {
            0x01: ipv4;
            0x02: ipv6;
        }
    }

    state ipv4 {
        packet.extract(addr.ipv4);
        transition accept;
    }

    state ipv6 {
        packet.extract(addr.ipv6);
        transition accept;
    }
}

parser ProtParser(packet_in packet,
                out headers hdr,
                inout metadata meta,
                inout standard_metadata_t standard_metadata) {
