#include <core.p4>
#include <v1model.p4>

struct metadata { }
struct headers { }

parser MyParser(packet_in packet,
                out headers hdr,
                inout metadata meta,
                inout standard_metadata_t standard_metadata) {

    state start {
        transition select(8w7) {
            7 : first_state;
            _ : accept;
        }
    }

    state first_state {
        standard_metadata.egress_spec = 1;
        transition select(8w6) {
            6 : second_state;
            _ : accept;
        }
    }

    state second_state {
        standard_metadata.egress_spec = 2;
        transition select(8w7) {
            0 : accept;
            _ : third_state;
        }
    }

    state third_state {
        standard_metadata.egress_spec = 3;
        transition select(8w7) {
            0 : accept;
            default : fourth_state;
        }
    }

    state fourth_state {
