    state parse_ipv4 {
        pkt.extract(hdr.ipv4);
        transition select(hdr.ipv4.protocol) {
            6       : parse_tcp;
	    0x11      : parseOther;
            default : accept;
        }
    }
    state parseOther {
	transition select(test){
	    false : accept;
	    true : parse_udp;
	}
    }
