        do_round(x);
        do_round(x);
        do_round(x);
        do_round(x);
        do_round(x);
        do_round(x);
        do_round(x);
        do_round(x);
        do_round(x);
        do_round(x);
        do_round(x);
    }
    apply {
	if (hdr.ethernet.isValid()) {
            do_n_rounds(hdr.ethernet.f);
        }
    }
